const e="body",a="2.0.0",l="マグネシウム合金カメラボディ＆防塵防滴外装（116パーツ）",o="Magnesium Alloy Camera Body & Weather-Sealed Chassis",s=116,t=JSON.parse('[{"id":"body-battery-pack","order":1,"swatchColor":"#0284c7","groupKey":"大電流バッテリー_6A_Li_Ion_Pack","assembledPos":[-54.5,-6,1.5],"explodeOffset":[-64,-56,20],"integratedExplodeOffset":[-130,-60,16],"edgeOpacity":0.22,"title":"B01. 7.2V 高出力デュアルセル リチウムイオンバッテリー＆スマートBMS","subtitle":"High-Discharge 7.2V / 6.0A Dual-Cell Li-Ion Pack with Smart Fuel-Gauge BMS IC","category":"大電流バッテリー / 6A Li-Ion Pack","plainAnalogy":"カメラ全体の心臓を動かす「プロ用スーパー乾電池（2本直列の充電池パック）」です。AIチップや8K動画・4基のリニアモーターへ一瞬で大電流を送り出し、内部の頭脳チップが残り残量を1%刻みで報告します。","summary":"最新のAI被写体認識NPU・8K 60p RAW収録・120fps連写・大口径レンズ4基リニアモーター駆動を同時に支えるため、最大連続放電電流 6.0 A に対応した次世代7.2V（2直列・2,130〜2,280 mAh / 約16.4 Wh）高出力リチウムイオンバッテリー。本CADでは内部の2本の高密度円筒セルと保護回路・残量計IC（BMS基板）が見えるよう側面ハーフカットで構造を可視化しています。","opticsAndPhysics":["公称3.6Vの高エネルギー密度リチウムイオン単セルを2本直列（2S1P）接続することで公称7.2V（満充電8.4V）を生成し、同じ消費電力でも電流値を半分に抑えて内部抵抗損失 I²R を1/4に低減します。","最新世代の高出力バッテリーは内部インピーダンスを極限まで下げ、従来比約2倍となる最大6.0A連続放電（ピーク40W超）を実現。寒冷地でも電圧降下によるシャットダウンを防ぎます。","上部のBMS（Battery Management System）基板にはクーロンカウンタ残量計・サーミスタ温度監視・暗号化認証IC・過電流保護MOSFETを搭載し、ボディ側PMICと双方向デジタル通信します。"],"formula":{"expression":"P_max = V_nom · I_max = 7.2 V × 6.0 A = 43.2 W,   E = 7.2 V × 2.28 Ah = 16.4 Wh","description":"2直列高出力リチウムイオンパックの最大出力と蓄電エネルギー。AI NPU・積層グローバルシャッターセンサー・4基XDリニアモーターの同時フル稼働を支えます。"},"nextGenInnovation":"USB-PD（Power Delivery）急速充電対応と1%単位の劣化度診断・シリアル個別登録機能により、プロの現場でバッテリー残量と寿命を精密管理できます。","specs":[{"label":"公称電圧 / 容量","value":"7.2 V（2S1P） / 約 2,280 mAh（16.4 Wh）"},{"label":"最大連続放電","value":"6.0 A（最新AI・8K RAW対応ハイドレイン）"},{"label":"安全保護機構","value":"BMS残量計・NTC温度監視・過電流遮断FET"},{"label":"解剖構造","value":"2本直列リチウムイオンセル＋上部BMS基板"}],"diagramType":"body_battery"},{"id":"body-battery-chamber","order":2,"swatchColor":"#475569","groupKey":"給電接点・防水室_Battery_Chamber","assembledPos":[-54.5,-6,1.5],"explodeOffset":[-34,-22,4],"integratedExplodeOffset":[-82,-24,4],"edgeOpacity":0.22,"title":"B02. 防水バッテリー室・金メッキ多極スプリング端子＆ロック機構","subtitle":"Sealed Battery Bay Cage, Gold-Plated Leaf Terminals & Dual-Lock Hatch","category":"給電接点・防水室 / Battery Chamber","plainAnalogy":"バッテリーをガッチリ収めて電気を受け取る「防水コンセント部屋」です。底のフタにはゴムパッキンが巻かれ、電池を抜いても落ちないロック爪と金色のバネ端子が確実につながります。","summary":"右手グリップ内部の死空間を最大限に活かして配置された難燃樹脂＆アルミ補強バッテリーチャンバー。天井奥には低接触抵抗の金メッキ銅合金4極スプリング端子（＋電源、−GND、T温度、Dデジタル通信）を配置し、底部にはEPDM防塵防滴ガスケット付きスライドロック式ヒンジ扉とバッテリー脱落防止青色ラッチレバーを備えています。","opticsAndPhysics":["最大6Aの大電流が流れる電源接点では、わずかな接触抵抗 ΔR = 20 mΩ でも発熱 P = I²·ΔR = 0.72 W と電圧降下が発生するため、二股（ツインコンタクト）金メッキバネ端子で常時2点接触を保証します。","チャンバー内壁に設けた排出用コイルスプリングがロック解除と同時にバッテリーを約8 mm押し上げ、手袋を着けたままでも片手で素早く電池交換できます。","ヒンジ蓋には外部DCカプラー用ゴムグロメットを内蔵し、三脚やリグ上での長時間スタジオ給電にも対応。"],"formula":{"expression":"ΔV_contact = I · R_c < 0.03 V   (二股金メッキ接点 R_c < 5 mΩ @ 6 A)","description":"大電流給電時の接触電圧降下抑制。高接触圧ツインスプリング接点が連写中の瞬間電圧ドロップ（ブラウンアウト）を防止します。"},"nextGenInnovation":"防塵防滴の二重ラビリンスパッキンと底面ロックレバーの誤開放防止構造により、豪雨の中での手持ち撮影でもバッテリー室への浸水を完全に阻止します。","specs":[{"label":"接点構成","value":"金メッキツインバネ4極（+ / - / 温度 / 通信）"},{"label":"接触抵抗","value":"< 5 mΩ（6A大電流対応低損失設計）"},{"label":"脱落防止","value":"自動係合ロックラッチ＋イジェクトスプリング"},{"label":"防塵防滴","value":"全周EPDMガスケット封止底面ハッチ"}],"diagramType":"body_batt_chamber"},{"id":"body-ergo-grip","order":3,"swatchColor":"#1e293b","groupKey":"エルゴノミクス保持_Deep_Grip","assembledPos":[-56,-2,6],"explodeOffset":[-76,8,48],"integratedExplodeOffset":[-148,8,56],"edgeOpacity":0.22,"title":"B03. エルゴノミクス深型右手グリップ＆シボ加工エラストマー外皮","subtitle":"Deep Ergonomic Magnesium-Backed Right Grip & Pebble-Grain Elastomer Leatherette","category":"エルゴノミクス保持 / Deep Grip","plainAnalogy":"重い大口径レンズを着けても片手で楽に支えられるよう、手のひらの形に合わせて深くくぼませた「滑り止めラバー付きの握り手」です。","summary":"50mm F1.2や超望遠レンズ装着時でも指先がレンズ鏡筒に干渉せず、中指・薬指・小指の3本が深くかかり込む人間工学（エルゴノミクス）深型右手グリップ。剛性の高いマグネシウム骨格の表面に、汗や雨でも滑りにくい微細シボ（ペブルグレイン）加工高耐候エラストマー・レザレットを一体成形しています。","opticsAndPhysics":["大口径レンズによる前荷重モーメント M = W_lens · L を手のひら全体と中指フック溝（アンダーカット）へ均等分散し、長時間撮影時の手首疲労と微細な手ブレを根本から減らします。","グリップ表面の微細凹凸シボ加工により、乾いた手だけでなく雨天や発汗時でも水の膜（ハイドロプレーニング）を逃がし、高い静止摩擦係数 μ > 1.1 を維持します。","グリップ内部の中空スペースがそのままB01バッテリー室とB10デュアルカードスロットを収める構造になっており、カメラ全体の小型化と剛性向上を両立。"],"formula":{"expression":"F_grip = M_lens / d_palm   (深型アンダーカットによる保持力最適化)","description":"中指の引っ掛かり深さと手のひら支持幅 d_palm を最大化することで、重いF1.2レンズ装着時でも最小限の握力でブレなくホールドできます。"},"nextGenInnovation":"数百人のプロカメラマンの手型3Dスキャンデータから導き出された非対称カーブと前傾シャッター角度により、「握った瞬間に人差し指が自然にシャッターへ導かれる」理想のホールド感を実現しています。","specs":[{"label":"外皮材質","value":"高耐候シボ加工合成エラストマー（レザレット）"},{"label":"内部骨格","value":"AZ91Dマグネシウム合金サブフレーム"},{"label":"保持設計","value":"深型中指フック＋大口径レンズ指クリアランス確保"},{"label":"内部収納","value":"高出力バッテリー室＆カードベイ一体構造"}],"diagramType":"body_grip"},{"id":"body-shutter-dials","order":4,"swatchColor":"#dc2626","groupKey":"速写メイン操作系_Shutter_Dials","assembledPos":[-54.5,31,9],"explodeOffset":[-34,48,22],"integratedExplodeOffset":[-72,114,28],"edgeOpacity":0.22,"title":"B04. 2段金属ドームシャッターボタン＆前後電子コマンドダイヤル群","subtitle":"Two-Stage Metal-Dome Shutter Release, Power Ring & Dual Optical-Encoder Command Dials","category":"速写メイン操作系 / Shutter & Dials","plainAnalogy":"カメラで一番たくさん触る「人差し指と親指のコントローラー」です。半押しでピントを合わせて全押しで撮る絶妙な2段階の押し心地と、カチカチ回せる前後2つのダイヤルが瞬間を逃しません。","summary":"グリップ先端の自然な前傾角度（約28°）に配置された、高耐久2段ストローク金属ドーム式シャッターレリーズボタン、同軸電源オン/オフレバー、独立赤色動画RECボタン、そして人差し指用「フロントコマンドダイヤル」と親指用「リアコマンドダイヤル」の精密操作アセンブリ。内部は非接触光学／磁気ロータリーエンコーダーを採用し、長年の使用でもチャタリング（接点不良）が起きません。","opticsAndPhysics":["シャッターボタン内部には反発荷重の異なる2層のステンレス製スナップドーム（1段目半押し約1.2 N、2段目全押し約2.8 N）を重ね、指先だけで明確な半押しポイントを感じ取れるクリック感と極短レリーズタイムラグ（< 20 ms）を両立。","前後コマンドダイヤルはA相・B相の90°位相差パルスを出力する直交（クアドラチャ）エンコーダーと防塵Oリング軸封構造を組み合わせ、高速回転でも1クリックの取りこぼしを防ぎます。","赤色アルマイトの動画RECボタンは周囲よりわずかに凹ませたガード形状とし、静止画撮影中の誤操作を防止しつつ動画時は確実に押し込めます。"],"formula":{"expression":"F_half ≈ 1.2 N  →  F_full ≈ 2.8 N,   θ_ergo ≈ 28° (人差し指自然前傾角)","description":"2段階スナップドームの荷重ヒステリシス特性。半押し保持時の手ブレ誘発を防ぎつつ、決定的瞬間に迷わず全押しできるプロ仕様チューニング。"},"nextGenInnovation":"同軸電源レバーと前後ダイヤル・露出補正ダイヤルすべてに防塵防滴シリコンパッキンを内蔵し、砂嵐や吹雪の中でも軽快なクリック感を損ないません。","specs":[{"label":"シャッター機構","value":"高耐久2段ステンレススナップドーム（50万回級）"},{"label":"コマンドダイヤル","value":"アルミ削り出しローレット 前後2系統"},{"label":"回転検出","value":"A/B直交位相 光学・磁気エンコーダー"},{"label":"専用ボタン","value":"同軸電源レバー＋独立クリムゾンRECボタン"}],"diagramType":"body_shutter_dials"},{"id":"body-top-dials","order":5,"swatchColor":"#0ea5e9","groupKey":"肩部ダイヤル_状態表示_Top_Dials_OLED","assembledPos":[0,38.8,-2],"explodeOffset":[0,62,0],"integratedExplodeOffset":[0,132,6],"edgeOpacity":0.22,"title":"B05. ロック機構付きモード／ドライブダイヤル＆肩部グラフィカルSub-OLED","subtitle":"Center-Lock Mode & Left Drive Dials + Reflective/Emissive Top Shoulder Sub-OLED","category":"肩部ダイヤル＆状態表示 / Top Dials & OLED","plainAnalogy":"カメラの屋根の上にある「運転モード切替ハンドル」と「小さな計器パネル」です。真ん中のロックボタンを押しながら回すことでバッグの中で勝手に設定が変わるのを防ぎます。","summary":"カメラ右肩のセンターロック式撮影モードダイヤル＆高コントラスト反射・自発光ハイブリッド肩部ステータスSub-OLED、そして左肩（+X側）に独立配置された2段ロック式ドライブ／フォーカスモードダイヤル。アルミ無垢材から精密切削されたローレットリングが確かな所有感とグローブ着用時の確実な操作性を生み出します。","opticsAndPhysics":["中央のプッシュロックピンを押し込むと回転ロックが解除され、誤操作で撮影モード（M/Av/Tv/C1-C3）や連写設定がズレるプロの現場事故をゼロにします。","右肩のステータスSub-OLEDは白黒高コントラスト表示とアンチグレア・強化ガラスカバーを採用し、極小電力（数mW）で露出・電池残量・連写モードを直射日光下から真っ暗な星空撮影まで一目で視認可能。","左肩の2段ダイヤル（上段ドライブ速度＋下段AFモード）により、背面モニターやメニューを開かずに一瞬で「単写 ↔ 120fps高速連写」を物理切替できます。"],"formula":{"expression":"τ_detent = k_spring · Δx · tan(α_cam)   (鋼球＋V溝カムディテントトルク)","description":"ステンレス鋼球と放射状V溝カムによる歯切れのよい機械クリック感。片手操作の軽さと誤回転防止の重さを絶妙に調律しています。"},"nextGenInnovation":"静止画／動画／S&Qの物理サブダイヤル切替とカスタムモード連携により、ハイブリッドシューターが瞬時に静止画設定と動画設定を完全独立して行き来できます。","specs":[{"label":"右肩機構","value":"プッシュロック式モードダイヤル＋露出補正ダイヤル"},{"label":"左肩機構","value":"2段ロック式ドライブ／AFモードダイヤル"},{"label":"肩部表示","value":"高コントラスト白黒Sub-OLED（強化ガラス保護）"},{"label":"材質加工","value":"CNC切削アルミニウム ローレット仕上げ"}],"diagramType":"body_top_dials"},{"id":"body-mi-hotshoe","order":6,"swatchColor":"#cbd5e1","groupKey":"拡張アクセサリー接点_21_Pin_Hot_Shoe","assembledPos":[0,57.6,-7.5],"explodeOffset":[0,72,-4],"integratedExplodeOffset":[0,152,-6],"edgeOpacity":0.22,"title":"B06. 21ピン デジタルオーディオ対応マルチインターフェース・ホットシュー","subtitle":"21-Pin Multi-Interface Digital Audio & Smart Flash Hot Shoe (Weather-Sealed)","category":"拡張アクセサリー接点 / 21-Pin Hot Shoe","plainAnalogy":"カメラのてっぺんにある「万能アクセサリー差し込み口」です。ストロボを発光させるだけでなく、21本の極小ピンでケーブル無しにプロ用マイクからデジタル音声を直接録音できます。","summary":"EVFペンタ部の頂上を飾る、高強度ステンレス鋼レールと先端21ピン高速デジタル接点アレイを備えた次世代マルチインターフェース・ホットシュー。従来のアナログX接点ストロボ同調に加え、24bit/48kHz 4チャンネルデジタルオーディオ入力、バッテリーレス給電、外部XLRアダプターやスマートフラッシュの双方向デジタル制御をケーブル一本使わずに完結します。","opticsAndPhysics":["先端奥の21ピン金メッキ微細コネクター（I2Sデジタル音声バス、高速シリアル通信、電源VBUS）を保護カバー奥に配置し、外部マイクのアナログA/D変換ノイズを完全排除したフルデジタル録音が可能です。","大型クリップオンストロボ（約600g）を装着して振り回しても脱落・歪みが生じないよう、ステンレスシュー土台はEVF上部マグネシウム骨格へ4本の高張力ボルトで直接締結されています。","防水対応アクセサリーのラバーブーツと密着する段差シール構造により、雨天時のフラッシュ撮影でも21ピン接点の短絡を防ぎます。"],"formula":{"expression":"SNR_digital_MI ≈ 108 dB (24-bit I2S直結)  vs  SNR_3.5mm ≈ 78 dB","description":"ホットシュー直結フルデジタルオーディオ伝送により、3.5mmアナログケーブル経由の電磁誘導ハムノイズとA/D劣化を劇的に低減します。"},"nextGenInnovation":"最新の21ピン多機能シューは、1/80,000秒グローバルシャッター全速フラッシュ同調の精密トリガー通信と、4chデジタルガンマイクのケーブルレス給電を1つの標準インターフェースで実現しています。","specs":[{"label":"接点構成","value":"先端21ピンデジタル接点＋X同調ベース接点"},{"label":"音声伝送","value":"24-bit / 48 kHz 最大4ch デジタルオーディオ直結"},{"label":"レール材質","value":"高剛性硬化ステンレス鋼（4点マグネシウム締結）"},{"label":"防塵防滴","value":"対応ラバーブーツ密着シーリング構造"}],"diagramType":"body_hotshoe"},{"id":"body-mg-front-shell","order":7,"swatchColor":"#334155","groupKey":"フロント骨格外装_Front_Mg_Monocoque","assembledPos":[-3,0,27.6],"explodeOffset":[0,0,56],"integratedExplodeOffset":[0,0,80],"edgeOpacity":0.22,"title":"B07. チクソモールドAZ91D マグネシウム合金フロントモノコック外装","subtitle":"Thixomolded AZ91D Magnesium-Aluminum Monocoque Front Shell & Mount Opening","category":"フロント骨格外装 / Front Mg Monocoque","plainAnalogy":"レーシングカーのボディのように軽くて頑丈な「カメラの正面のよろい」です。55mm大口径レンズマウントをガッチリ囲み、内部の精密メカを衝撃と電波ノイズから守ります。","summary":"半溶融射出成形（チクソモールディング）によって薄肉・高強度・高寸法精度に成形されたAZ91Dマグネシウム合金製フロントモノコックシェル。正面中央のφ69.4 mm精密円形開口に55mmステンレスレンズマウント（M01）を面一で抱え込み、レンズ着脱ボタン保護ガード、AF補助光／タリーランプ窓、前部カスタムFnボタン、そして側面ストラップ吊り金具（三角環ラグ）を強固に一体化しています。","opticsAndPhysics":["マグネシウム合金（密度 1.81 g/cm³）はアルミの約2/3・鉄の約1/4の軽さでありながら高い比剛性と優れた振動減衰能（シャッター衝撃吸収）と電磁波シールド性能（EMI遮蔽）を併せ持ちます。","表面には耐摩耗性に優れる微細パールマット焼付塗装を施し、過酷な現場での擦過傷防止とプロ機ならではの重厚な手触りを実現。","正面左上の高輝度LED窓は暗所AF補助光と動画収録中を被写体へ知らせるフロント・タリーランプを兼ね備えます。"],"formula":{"expression":"E / ρ (比剛性) = 45 GPa / 1.81 g·cm⁻³ ≈ 24.9   (軽量・高剛性・高EMI遮蔽)","description":"AZ91Dマグネシウム合金モノコックの比剛性と電磁シールド特性。大口径レンズの片持ち荷重を受け止めつつボディ軽量化を達成します。"},"nextGenInnovation":"内部のシャッター・IBIS・マウントを一体化して支える「モノコック外殻構造」により、従来のインナーシャーシ＋化粧カバー方式よりも少ない部品点数で圧倒的なねじり剛性と防塵防滴性を獲得しています。","specs":[{"label":"材質・製法","value":"AZ91Dマグネシウム合金 チクソモールド成形"},{"label":"マウント開口","value":"φ69.4 mm 精密CNC追加工フェイス"},{"label":"装備機能","value":"AF補助光/タリーLED・前部Fnボタン・高荷重吊り金具"},{"label":"保護性能","value":"高EMIシールド＋接合部全周防水シール溝"}],"diagramType":"body_front_shell"},{"id":"body-top-deck","order":8,"swatchColor":"#475569","groupKey":"トップ外装・EVF屋根_Top_Mg_Deck","assembledPos":[0,36.8,0],"explodeOffset":[0,38,0],"integratedExplodeOffset":[0,96,2],"edgeOpacity":0.22,"title":"B08. マグネシウム合金トップデッキ＆EVFペンタ部ルーフ外装","subtitle":"Sculpted Magnesium Alloy Top Deck, EVF Pentaprism Housing Roof & Stereo Mics","category":"トップ外装・EVF屋根 / Top Mg Deck","plainAnalogy":"カメラの頭と両肩をすっぽり覆う「流線型のヘルメット」です。真ん中の盛り上がった山の中に高輝度EVF光学系が収まり、左右にはステレオマイクとストラップ金具が付いています。","summary":"カメラ上面全体と中央の象徴的なEVFペンタ部（ファインダーハウス）を一体成形したマグネシウム合金トップデッキ。内部の4,000 nit Tandem Micro-OLED EVF光学系（E01〜E14）を衝撃・雨滴から完全保護しつつ、上面に21ピンホットシュー（B06）を締結する強化ボス、左右の風切り音低減ステレオマイク孔、そして肩部ダイヤル・Sub-OLED用の防水開口を精密に配置しています。","opticsAndPhysics":["EVFペンタ部の傾斜した流線型ファセット形状は単なる意匠ではなく、内部の大型対物レンズ・ダイクロイックミラー・視度調整機構のクリアランスを最小体積で包み込む機能的アーチ構造です。","内蔵ステレオマイクの音響ポートには撥水通気メンブレン（ePTFE膜）を貼り付け、クリアな収音性能を保ったまま雨滴の浸入をブロックします。","フロントシェル（B07）およびリアパネル（B09）との全接合ラインに溝付きシリコンゴムパッキンを挟み込み、ボディ上面へ直接雨が降り注いでも内部基板へ一切水を通しません。"],"formula":{"expression":"IP_seal = ラビリンス段差接合 + シリコンOリング圧縮率 20〜30%","description":"トップデッキと前後外装の気密接合設計。均一なパッキン圧縮代により全天候フィールド撮影の信頼性を担保します。"},"nextGenInnovation":"高熱伝導マグネシウムトップデッキの裏面をEVF放熱ヒートシンクと熱結合させることで、真夏の120fpsファインダー連続表示でも熱ダレを防いでいます。","specs":[{"label":"構造材質","value":"AZ91Dマグネシウム合金 一体成形トップカバー"},{"label":"内蔵設備","value":"撥水膜付きステレオマイク＆ホットシュー強化台座"},{"label":"EVF収容","value":"4,000 nit EVF光学系＆視線AFユニット完全保護"},{"label":"防水接合","value":"前後外装・ダイヤル軸全周ガスケット封止"}],"diagramType":"body_top_deck"},{"id":"body-rear-controls","order":9,"swatchColor":"#64748b","groupKey":"背面親指操作系_Rear_Controls_Joystick","assembledPos":[-6,0,-33],"explodeOffset":[0,0,-54],"integratedExplodeOffset":[-56,0,-196],"edgeOpacity":0.22,"title":"B09. 背面マグネシウム外装・親指グリップ・8方向AFジョイスティック＆操作ホイール","subtitle":"Rear Magnesium Chassis, Thumb Rest, 8-Way AF Multi-Selector Joystick & Rotary Wheel","category":"背面親指操作系 / Rear Controls & Joystick","plainAnalogy":"ファインダーを覗いたまま右手の親指だけでピント位置をスイスイ動かせる「ゲームコントローラーのような操作パネル」です。画面の横で親指がピッタリ休める出っ張りもついています。","summary":"4軸マルチアングル背面LCD（D01〜D06）を収める精密リセス開口とEVFアイカップ開口を囲む背面マグネシウムパネル、および右側（-X側）に集約されたプロ仕様の親指操作クラスター。滑り止めラバー付き親指レスト、8方向＋押し込み対応の微細ローレット「AFマルチセレクター・ジョイスティック」、親指AF-ONボタン、回転式リアコントロールホイール、各種ファンクションボタンをすべて手探り識別可能な立体形状で配置しています。","opticsAndPhysics":["EVFを覗いて撮影する際、カメラマンは背面ボタンを目視できないため、AF-ONボタン・ジョイスティック・ホイール・カスタムボタンの高低差と表面テクスチャをすべて変える触覚エルゴノミクス設計を採用しています。","8方向AFジョイスティックは4軸傾斜マイクロスイッチとセンタープッシュを1ユニットに集約し、AI被写体認識と併用して瞬時に任意の瞳・被写体へフォーカス枠を飛ばせます。","リアコントロールホイールは光学式回転検出＋4方向クリック＋中央決定ボタンの複合構造で、高速画像再生送りからISO・絞り微調整まで親指1本で完結します。"],"formula":{"expression":"t_target_select < 120 ms   (8方向ジョイスティック＋親指AF-ON同時操作)","description":"ファインダーから目を離さず親指の自然な軌道上でピント移動とAFロックを同時実行できるプロ機操作レイアウト。"},"nextGenInnovation":"全ボタンのスイッチ内部にシリコン防水ドームメンブレンを採用し、長寿命なタクタイルクリック感と徹底した防塵防滴性能を両立しています。","specs":[{"label":"AF操作","value":"8方向＋中央押し込み ローレットAFジョイスティック"},{"label":"ホイール操作","value":"回転＋4方向＋中央決定 複合コントロールホイール"},{"label":"保持補助","value":"立体ラバー親指レスト＆独立AF-ONボタン"},{"label":"背面開口","value":"4軸LCDリセス収納ポケット＋EVFアイカップ開口"}],"diagramType":"body_rear_controls"},{"id":"body-card-door","order":10,"swatchColor":"#1e293b","groupKey":"高速メディア扉_Dual_Card_Door","assembledPos":[-70.8,-5,-13.5],"explodeOffset":[-62,0,-18],"integratedExplodeOffset":[-140,0,-32],"edgeOpacity":0.22,"title":"B10. 防塵防滴デュアルCFexpress／SDメモリーカードスロットカバー","subtitle":"Weather-Sealed Slide-Lock Dual CFexpress Type B / SD UHS-II Card Bay Door","category":"高速メディア扉 / Dual Card Door","plainAnalogy":"写真や8K動画を記録する超高速メモリーカードを出し入れする「スライドロック式の防水ドア」です。撮影中に手が当たってうっかり開かない二重ロック構造になっています。","summary":"右手グリップ後側面（-X側）に配置された、デュアル高速メモリーカードスロット（メイン基板MB09直結）を保護する強化アルミ＋エラストマー張りのスライドロック式アクセスドア。ドアを開けると内部の検知マイクロスイッチが即座に書き込み中データを安全退避し、全周EPDMパッキンとステンレスヒンジシャフトが雨天撮影でのカード腐食を防ぎます。","opticsAndPhysics":["右手の手のひらが常に触れる位置にあるため、単なるフリップ開閉ではなく「スライド解除 → スプリングポップオープン」の2アクションロックを採用し、撮影中の誤開放を完全防止。","CFexpressカードは8K RAW連続書き込み時に60〜70℃へ達するため、ドア内側の高熱伝導サーマルパッドがカードの熱を外部表面へ逃がす放熱経路の一部も担います。","開閉検知スイッチにより、万が一書き込み途中で扉を開けても即座にキャッシュ保護シーケンスとアクセスLED警告を作動させます。"],"formula":{"expression":"BW_card = 2,000 MB/s (CFexpress PCIe Gen4) → 扉内側放熱＆EMI完全遮蔽","description":"超高速メモリーカードの放熱・ノイズ遮蔽・防水を1枚の薄型スライドロックドアで実現しています。"},"nextGenInnovation":"ドア表面にグリップと連続するシボ加工エラストマーを貼り込むことで、握った際の継ぎ目の違和感をゼロにしつつ高い耐久性を確保しています。","specs":[{"label":"ロック機構","value":"誤開放防止スライドロック＋スプリングアシスト開閉"},{"label":"対応スロット","value":"デュアル高速メディアベイ保護（CFexpress / SD）"},{"label":"防塵防滴","value":"ドア内周全周成型シリコン防水ガスケット"},{"label":"安全機能","value":"扉開放検知マイクロスイッチ内蔵"}],"diagramType":"body_card_door"},{"id":"body-io-doors","order":11,"swatchColor":"#475569","groupKey":"外部端子保護扉_Split_I_O_Doors","assembledPos":[56.5,-2,-7],"explodeOffset":[56,0,-8],"integratedExplodeOffset":[98,0,-14],"edgeOpacity":0.22,"title":"B11. 分割式防塵防滴 I/O ポートカバー（フルサイズHDMI／USB-C／有線LAN／音声）","subtitle":"Split Weather-Sealed Independent I/O Terminal Doors (HDMI, USB-C, 2.5G LAN, Audio)","category":"外部端子保護扉 / Split I/O Doors","plainAnalogy":"マイクやHDMIケーブルを挿す端子を雨やホコリから守る「3つに別れた小さな防水扉」です。使う端子だけを開けられるので、使わない端子は閉じたまま濡れずに守れます。","summary":"カメラ左側面（+X側、メイン基板MB12の各種プロI/O端子群の直外）に配置された、3分割独立開閉式の防塵防滴ターミナルカバー群。上段（マイク・ヘッドホン音声端子）、中段（フルサイズHDMI Type-A・USB-C 10Gbps PD）、下段（2.5GbE有線LAN／シンクロターミナル）をそれぞれ個別に開閉でき、動画リグ運用時や4軸バリアングルモニター展開時にも邪魔になりにくいスライド格納構造を備えています。","opticsAndPhysics":["従来の1枚つづり大型ゴムカバーは、マイクだけ繋ぎたい時にもHDMIやUSB端子まで雨風に晒されていましたが、3分割独立ドアにより必要なポートだけを開放できます。","各カバー内側の突起プラグがコネクタ口外周のシート面へ密着圧縮されることで、高圧水飛沫や砂塵の侵入を遮断。","ハードシェル＋ソフトエラストマーの2色成形（ダブルインジェクション）により、数千回の開閉でもちぎれず、開閉時の手応えも上質です。"],"formula":{"expression":"露出開口面積 ↓ 66%   (3分割独立カバーによるフィールド耐候性向上)","description":"使用する外部ケーブル端子だけを局所開放できるプロ仕様の分割ターミナル保護アーキテクチャ。"},"nextGenInnovation":"動画撮影時にフルサイズHDMIとUSB-Cを同時挿しする際、付属のケーブルプロテクターを固定できる専用ネジ穴と一体化され、コネクタ破損事故を未然に防ぎます。","specs":[{"label":"構成","value":"3分割独立開閉ドア（音声 / HDMI+USB-C / 有線LAN）"},{"label":"保護対象","value":"フルサイズHDMI Type-A, USB-C PD, 2.5GbE, 3.5mm入出力"},{"label":"材質構造","value":"硬質外皮＋軟質防水エラストマー2色成形"},{"label":"運用性","value":"4軸LCDチルト＆動画ケージ非干渉設計"}],"diagramType":"body_io_doors"},{"id":"body-baseplate-tripod","order":12,"swatchColor":"#334155","groupKey":"底面骨格_三脚座_Baseplate_Tripod","assembledPos":[-6,-37.2,-1],"explodeOffset":[0,-48,0],"integratedExplodeOffset":[0,-88,0],"edgeOpacity":0.22,"title":"B12. マグネシウム底板＆高荷重ステンレス 1/4-20 UNC 三脚座（光軸直下）","subtitle":"Reinforced Magnesium Baseplate & Optical-Axis Stainless 1/4-20 UNC Tripod Load Socket","category":"底面骨格＆三脚座 / Baseplate & Tripod","plainAnalogy":"カメラ全体を三脚やジンバルにガッチリ固定する「頑丈な土台とネジ穴」です。レンズのちょうど真下に頑丈なステンレス製のネジ穴が埋め込まれており、重いレンズを着けてもグラつきません。","summary":"カメラ底面全体を引き締め、フロント・リア外装とメインフレームを締結する高剛性マグネシウム合金ベースプレート。光学中心（x = 0, z = 0）の真下に高強度ステンレス鋼製の 1/4-20 UNC 三脚ネジ穴とシネマ／動画プレート用の回り止めピン穴（アンチツイストホール）を配置し、底部バッテリー室アクセス口および縦位置バッテリーグリップ接点カバーを備えています。","opticsAndPhysics":["三脚ネジ穴をレンズ光軸の真下（x = 0）に正確に揃えることで、パノラマ雲台やジンバルへ載せた際にカメラを水平回転させても光軸（ノーダルポイント）が左右にブレず、美しいステッチングが可能です。","三脚座のステンレスボスは底板だけでなく内部のマウントバルクヘッド（M12）およびメインフレーム（MB16）まで貫通固定されており、三脚固定時に望遠レンズの荷重が外装カバーだけで歪むのを防ぎます。","底面バッテリー室ハッチは三脚クイックリリースプレートを装着したままでも干渉しにくいよう右端（-X側）へ最大限オフセット配置されています。"],"formula":{"expression":"x_tripod = 0.0 mm (光軸一致),   F_pullout > 1,500 N (ステンレス1/4-20 UNC)","description":"光軸直下の高荷重ステンレス三脚座。動画リグ・ジンバル・大型雲台での強大な締結トルクと曲げモーメントに耐えます。"},"nextGenInnovation":"底板自体が内部ベイパーチャンバー＆グラファイトシートからの熱を外部へ放散する補助放熱面としても機能し、8K長回し撮影の熱限界を引き上げています。","specs":[{"label":"三脚ネジ規格","value":"高強度ステンレス 1/4-20 UNC（光軸 x=0 直下）"},{"label":"動画対応","value":"回り止め（アンチツイスト）ビデオピン穴併設"},{"label":"底板材質","value":"AZ91Dマグネシウム合金 高剛性ベースプレート"},{"label":"底部開口","value":"右グリップ直下 バッテリーアクセス開口＆接点部"}],"diagramType":"body_baseplate"},{"id":"body-battery-ejector","order":13,"swatchColor":"#2563eb","groupKey":"給電メカニクス_Battery_Retention_Ejecto","assembledPos":[-54.5,-31.8,1.5],"explodeOffset":[-68,-32,-22],"integratedExplodeOffset":[-118,-44,-24],"edgeOpacity":0.22,"title":"B13. バッテリー脱落防止スライド爪・トーションバネ ＆ 自動排出ラッチ機構","subtitle":"Spring-Loaded Battery Retention Claw, Torsion Spring & Bottom Slide-Lock Mechanism","category":"給電メカニクス / Battery Retention & Ejector","plainAnalogy":"底のフタを開けた瞬間に高価なバッテリーが地面へボトッと落ちないように支えている「青いストッパー爪」と、指で爪を弾いた瞬間に電池をスルッと押し出すバネ仕掛けの飛び出しメカです。","summary":"バッテリー室（B02）の底口に組み込まれた2重安全脱落防止ラッチ＆自動排出機構。高靭性POM樹脂製の青色ロック爪がトーションコイルバネの復元力でバッテリー底面角へ自動係合し、底面ハッチをうっかり開けてもバッテリーの落下を防ぎます。爪を親指でスライド解除した瞬間だけ、上部イジェクトスプリングの反力でバッテリーが約8 mm押し出されます。","opticsAndPhysics":["カム斜面によるワンタッチ自動挿入ロック：バッテリーを押し込む際、電池肩部がロック爪の45°テーパー斜面を押し退けてトーションバネを蓄勢し、底突きした瞬間に「カチッ」と自力で元のロック位置へ復帰します。","二重安全ロック・シーケンス：底面防水ドアのスライドロックバーと独立した内部バッテリー爪の2段構成により、移動中の誤開放や高所撮影でのバッテリー落下事故を物理的にゼロ化します。","耐寒・低摩擦自己潤滑POM樹脂：−20℃の極寒環境でも樹脂が脆化せず、トーションバネのわずかなトルク（約0.15 N·m）だけで1万回以上の電池交換サイクルに耐えます。"],"formula":{"expression":"F_eject = k_coil · Δy_comp ≈ 3.8 N  >  μ_wall · N_contact  (確実な8 mm自動突出)","description":"排出バネの反発力 F_eject がバッテリー側面の摩擦抵抗を上回るよう最適設計され、ロック解除だけで片手交換を実現。"},"nextGenInnovation":"最新世代の縦位置グリップ併用ボディでは、工具なしで底面バッテリードア自体をワンタッチ脱着できるクイックリリースピン機構と一体設計されています。","specs":[{"label":"ロック爪材質","value":"高靭性自己潤滑POM樹脂（青色識別成形）"},{"label":"付勢バネ","value":"SUS304-WPB ステンレス製トーションバネ"},{"label":"排出ストローク","value":"約 8.0 mm（片手取り出しアシスト）"},{"label":"耐久サイクル","value":"> 15,000 回 着脱試験クリア"}],"diagramType":"body_battery_ejector"},{"id":"body-battery-terminals","order":14,"swatchColor":"#eab308","groupKey":"大電流給電ブロック_6A_Power_Terminals","assembledPos":[-54.5,19.6,1.5],"explodeOffset":[-54,20,18],"integratedExplodeOffset":[-102,24,14],"edgeOpacity":0.22,"title":"B14. 6A大電流対応 金メッキ二股リン青銅スプリング端子 ＆ 主電源バスバーFPC","subtitle":"High-Current 4-Pin Gold Twin-Contact Leaf Terminal Block & Heavy-Copper Power FPC","category":"大電流給電ブロック / 6A Power Terminals","plainAnalogy":"バッテリーの頭とカメラ本体の血管をつなぐ「金メッキの特大コンセント接点」です。1つの端子が2本のバネで挟み込む二股構造になっていて、激しく揺れても一瞬たりとも電気が途切れません。","summary":"バッテリー室天井奥に配置された耐熱PPS樹脂モールド端子ブロックと、6.0A連続大電流対応の厚膜金メッキ・リン青銅（C5210）二股リーフスプリング接点（＋V_BAT、−GND、NTC温度、BMSデジタル通信の4極）、およびバッテリー排出コイルバネ・大電流厚銅フレキシブル基板（Power FPC）の一体給電モジュール。","opticsAndPhysics":["二股（ツインコンタクト）冗長接点設計：1極ごとに独立して撓む2枚のリン青銅バネ指を設けることで、シャッター連写やスポーツ撮影の衝撃振動で片側がミクロン単位で浮いても、もう片側が常時通電を維持し瞬間リセット（瞬断）を防ぎます。","超低接触抵抗（< 5 mΩ）による発熱抑制：8K RAW＋AI NPU＋4基リニアモーターの同時フル稼働（6A）では接触抵抗が命取りとなるため、ニッケル下地＋硬質金メッキ（膜厚0.5 μm超）と高接触圧（1.8 N/極）を採用しています。","厚銅（2 oz = 70 μm）専用パワーFPC：通常の信号用FPCの2倍以上の銅箔厚を持つ専用給電フレキでメイン基板PMICへ最短配線し、インピーダンスドロップを極限まで低減します。"],"formula":{"expression":"P_loss = I² · R_contact = (6.0 A)² × 0.004 Ω = 0.144 W,   R_twin = R_single / 2","description":"二股並列接触により接触抵抗を半減させ、6Aピーク給電時の端子発熱と電圧降下（ΔV = 24 mV）を極小に抑え込みます。"},"nextGenInnovation":"最新世代のハイブリッド機では、バッテリー側のスマートBMS認証ピンと高速1-Wire通信を行うことで、USB-PD急速充電中のセル温度・内部インピーダンス劣化をリアルタイム監視します。","specs":[{"label":"端子材質","value":"リン青銅 C5210 ＋ 厚膜硬質金メッキ二股リーフ"},{"label":"定格通電容量","value":"連続 6.0 A / ピーク 10.0 A（接触抵抗 < 5 mΩ）"},{"label":"極数構成","value":"4極（+7.2V / GND / 温度サーミスタ / デジタルBMS）"},{"label":"配線基板","value":"2 oz 厚銅ベース大電流ポリイミド電源FPC"}],"diagramType":"body_battery_terminals"},{"id":"body-shutter-switch","order":15,"swatchColor":"#f59e0b","groupKey":"速写接点メカ_2_Stage_Shutter_Switch","assembledPos":[-54.5,31.8,20.5],"explodeOffset":[-34,28,42],"integratedExplodeOffset":[-72,74,44],"edgeOpacity":0.22,"title":"B15. 2段ステンレス・スナップドーム式シャッタースイッチ ＆ 同軸電源ワイパー","subtitle":"Two-Stage Stainless Snap-Dome Shutter Release Switch & Coaxial Power Wiper","category":"速写接点メカ / 2-Stage Shutter Switch","plainAnalogy":"シャッターボタンのすぐ下に隠れている「2枚重ねの極小金属ペコペコ皿（スナップドーム）」です。1枚目がペコッと凹むとピント合わせ（半押し）、もう一段深く2枚目が凹むと撮影（全押し）が発動します。","summary":"フラッグシップ機ならではの極上レリーズフィールと50万回以上の超長寿命を生み出す、同軸2層ステンレス・スナップドーム式レリーズスイッチ本体と周囲の電源ON/OFF同軸ロータリーワイパー接点。シリコン防塵防水ダイアフラム越しにアクチュエーターピンが2枚の異なる座屈荷重ドームを順次押し下げる精密構造です。","opticsAndPhysics":["2段座屈（スナップバック）荷重曲線：上段（S1半押し用・約1.2 N）と下段（S2全押し用・約2.8 N）の2枚のSUS301ステンレス曲面ドームを同軸積層。座屈瞬間のクリック反力低下（スナップ比約35%）により、目視せず指先の触覚だけで半押し保持と全押し決断をミリ秒単位で制御できます。","低チャタリング金メッキ十字接点：ドーム中央の裏面突起が基板上の金メッキ同心円接点を瞬時に短絡し、機械的バウンス時間を1 ms未満に圧縮して極短レリーズタイムラグを実現します。","同軸電源レバー摺動ワイパー：シャッター軸の外周を囲むリング状のリン青銅ブラシ接点が電源ON/OFF（およびロック位置）を明確な節度感とともに切替えます。"],"formula":{"expression":"Snap Ratio = (F_peak − F_bottom) / F_peak ≈ 35%,   t_bounce < 1.0 ms","description":"ステンレスドームの座屈スナップ比と接点バウンス時間。手ブレを誘発しない軽い全押しと明確な半押し境界を両立します。"},"nextGenInnovation":"プロ向けサービスでは、カメラマンの好みに応じてこの2段スナップドームユニットの荷重（フェザータッチ仕様〜重め仕様）や半押しストローク深さをカスタムチューニングできる設計が採用されています。","specs":[{"label":"接点構造","value":"同軸2層 SUS301 ステンレススナップドーム（S1 / S2）"},{"label":"作動荷重","value":"S1半押し 約 1.2 N / S2全押し 約 2.8 N"},{"label":"耐久寿命","value":"> 500,000 回 押下耐久（防塵防水ダイアフラム封止）"},{"label":"併設機構","value":"同軸ロータリー電源スイッチ・リン青銅ワイパー"}],"diagramType":"body_shutter_switch"},{"id":"body-command-encoders","order":16,"swatchColor":"#0284c7","groupKey":"回転検出メカ_Optical_Dial_Encoders","assembledPos":[-54.5,25.8,5.5],"explodeOffset":[-68,40,12],"integratedExplodeOffset":[-118,88,12],"edgeOpacity":0.22,"title":"B16. 前後コマンドダイヤル 光学スリットエンコーダー ＆ 鋼球クリックディテント","subtitle":"Front & Rear Command Dial Optical Slotted Encoders & Steel-Ball Click Detents","category":"回転検出メカ / Optical Dial Encoders","plainAnalogy":"前後のダイヤルを回したときの「カチカチッ」という気持ちいい手応えを作るステンレスの極小パチンコ玉＆バネと、スリットの隙間を光で数えて回転方向を読み取る非接触センサーです。","summary":"人差し指用フロントコマンドダイヤルと親指用リアコマンドダイヤルの裏側に連結された、高耐久・非接触光学式（または磁気ホール式）クアドラチャ・ロータリーエンコーダーと独立ステンレス鋼球クリックディテント機構。従来の接触ブラシ式で起きやすかった経年摩耗・チャタリングによる設定飛びを根絶しています。","opticsAndPhysics":["A相・B相 90°位相差（クアドラチャ）検出：回転スリット円板（チョッパーホイール）を挟む2組の赤外フォトインタラプタが90°位相のズレた矩形波を出力することで、1クリック単位の回転角だけでなく「右回りか左回りか」を瞬時に判別します。","分離独立した鋼球＋V溝ディテント：電気的検出と「カチカチ」という機械的クリック感の機構を完全分離。圧縮コイルバネがφ1.5 mmの硬質ステンレス鋼球を波型カム溝へ押し当て、10万回以上回しても新品同様の歯切れよい操作トルクを保ちます。","軸封Oリングによる防塵防滴：ダイヤル回転軸の根本をシリコングリス塗布済み極小EPDM Oリングでシールし、砂粒や雨水のエンコーダー室侵入を阻止します。"],"formula":{"expression":"Δφ_AB = ±90° (時計/反時計方向判別),   τ_click = F_spring · r · tan(α_V)","description":"直交2相信号による方向＆ステップ検出と、鋼球バネによるクリックトルク設計。高速連写中の瞬時シャッター速度変更を支えます。"},"nextGenInnovation":"最新世代では、光スリット円板をステンレスエッチング薄板で一体成形し、極寒地でもグリス固化による空転や二重カウントが一切起きないプロ仕様の信頼性を獲得しています。","specs":[{"label":"回転検出方式","value":"非接触 A/B直交2相 光学スリットエンコーダー（前後×2）"},{"label":"クリック機構","value":"φ1.5 mm SUS440C 焼入れ鋼球 ＋ 圧縮コイルバネ"},{"label":"分解能","value":"24 クリック / 1回転（15°ステップ）"},{"label":"軸封構造","value":"防塵防滴 EPDM マイクロ Oリングシール"}],"diagramType":"body_command_encoders"},{"id":"body-mode-lock-ratchet","order":17,"swatchColor":"#d97706","groupKey":"誤操作防止ロック_Lock_Pin_Ratchet","assembledPos":[0,32.8,-6.5],"explodeOffset":[0,48,-16],"integratedExplodeOffset":[0,112,-16],"edgeOpacity":0.22,"title":"B17. センターロック式モードダイヤル ＆ 2段ドライブ遊星ラチェットロック機構","subtitle":"Center-Push Mode Dial Lock-Pin Ratchet & Dual-Deck Drive/AF Concentric Mechanism","category":"誤操作防止ロック / Lock-Pin Ratchet","plainAnalogy":"肩部ダイヤルの真ん中にあるボタンを押している間だけロックのピンが引っ込んで回せるようになる「安全錠付きギアメカ」です。左肩の2階建てダイヤルは、内側と外側の2本の軸が重なって別々に回ります。","summary":"右肩の撮影モードダイヤルと左肩の2段ドライブ／フォーカスダイヤル（B05）を内部から支える精密機械式ロック＆二重同軸駆動ユニット。中央プッシュピンに連動するステンレス係合爪と遊星ラチェット歯車、コイル復帰バネ、そして左肩の2段ダイヤルを干渉なく独立回転させる「二重中空同軸シャフト（Concentric Dual Shaft）」で構成されています。","opticsAndPhysics":["スプリング式プッシュリリース・ラチェット：通常時はコイルバネがロックピンをラチェット歯溝へ押し込んで物理的に回転を完全阻止（耐誤回転トルク > 1.5 N·m）。中央ボタンを押下するとテーパーカムがロック爪を逃がし、軽快なクリックとともにモード切替できます。","二重同軸中空シャフト（左肩2段ダイヤル）：外側の太い中空パイプ軸が下段（AFモード切替）を、その中を貫通する細い中心軸が上段（ドライブ連写速度切替）を独立伝達する時計職人さながらの同軸設計です。","絶対位置エンコード接点：インクリメンタル式と異なり、回転角ごとに固有のグレイコード接点パターンを持つため、電源OFF中にダイヤルを回しても起動瞬間に正確な撮影モードを100%認識します。"],"formula":{"expression":"T_lock = N_teeth · F_pin · r_ratchet > 1.5 N·m   (バッグ内誤回転ゼロ)","description":"ラチェット歯溝とロックピンの噛み合い保持トルク。カメラバッグの出し入れや肩掛け移動時の不意なモード変更を完全防止します。"},"nextGenInnovation":"近年の上位機では、中央ボタンを押すたびに「ロック状態 ↔ アンロック状態」をトグル切替できる双安定カム（ボールペン式ハートカム）を採用したモードダイヤルも登場し、撮影スタイルに応じた柔軟な運用を実現しています。","specs":[{"label":"ロック機構","value":"センタープッシュ解除式 ステンレスラチェット＆復帰バネ"},{"label":"左肩伝達構造","value":"二重中空同軸シャフト（上段ドライブ / 下段AF独立）"},{"label":"位置検出","value":"絶対位置グレイコード接点（電源OFF中回転対応）"},{"label":"耐誤操作トルク","value":"> 1.5 N·m（完全メカニカル噛み合いロック）"}],"diagramType":"body_mode_lock_ratchet"},{"id":"body-top-switch-fpc","order":18,"swatchColor":"#059669","groupKey":"上面操作統合基板_Top_Switch_Rigid_Flex","assembledPos":[-6,34,4],"explodeOffset":[-6,22,16],"integratedExplodeOffset":[-6,76,16],"edgeOpacity":0.22,"title":"B18. トップデッキU字型リジッドフレキ制御基板 ＆ ダイヤル接点ワイパー集合体","subtitle":"Top-Deck U-Shaped Rigid-Flex Control Sub-PCB, Rotary Wiper Pads & Sub-OLED Bus","category":"上面操作統合基板 / Top Switch Rigid-Flex","plainAnalogy":"カメラの屋根裏に張り巡らされた「Uの字型の神経シート」です。ファインダーの山を避けながら左右のダイヤル・RECボタン・小さな肩液晶からの電気信号を1本に束ねてメイン基板へ送り届けます。","summary":"マグネシウムトップデッキ（B08）の裏面へ立体的に沿わせて実装されるU字型ポリイミド・リジッドフレキシブル統合基板。中央のEVFペンタ部光学鏡筒を干渉なく迂回しつつ、左右肩ダイヤルの金メッキ絶対位置グレイコード円環パターン、REC／C1／ISOボタンのメタルドームスイッチ、および肩部ステータスSub-OLED駆動ラインを1枚のハーネスへ集約しています。","opticsAndPhysics":["U字型立体ルーティングによる高密度実装：剛性が必要なダイヤル接点・スイッチ部にはガラスエポキシ補強板（FR-4リジッド部）を貼り合わせ、EVF周囲の狭い隙間を通る配線部だけを厚さ0.12 mmの柔軟ポリイミド（フレックス部）とすることでコネクタ点数を削減し耐振動性を高めています。","グレイコード（Gray Code）金メッキ円弧電極：ダイヤル回転時に隣接するポジション間で必ず1ビットしか変化しないグレイコードパターンを採用し、ダイヤル中間位置での誤コード読み取り（グリッチ）を論理的に排除します。","静電気保護（ESD）TVSダイオード直近配置：操作ボタンや金属ダイヤルを通じて指先から飛び込む最大15 kVの静電気サージを、メイン基板へ到達する前にトップ基板上の極小TVSアレイで即座にマグネシウムシャーシGNDへ逃がします。"],"formula":{"expression":"d_Hamming(Code_i, Code_{i+1}) = 1   (グレイコード絶対角検出で誤読ゼロ)","description":"隣接ダイヤル位置のハミング距離を常に1とするグレイコード電極設計。高速切替時でも中間エラーが発生しません。"},"nextGenInnovation":"コネクタ接続箇所を減らした一体成形リジッドフレキ化により、防水シーリング構造を簡潔にしながら組立精度と落衝撃時の接触信頼性を大幅に引き上げています。","specs":[{"label":"基板構造","value":"U字型 EVF回避ルーティング 4層リジッドフレキ"},{"label":"回転検出パターン","value":"厚膜硬質金メッキ 絶対位置グレイコード円環×2"},{"label":"搭載スイッチ","value":"REC / C1 / ISO 防水メタルドームスイッチ群"},{"label":"ESD保護","value":"IEC 61000-4-2 ±15 kV 気中放電保護TVS実装"}],"diagramType":"body_top_switch_fpc"},{"id":"body-hotshoe-springs","order":19,"swatchColor":"#94a3b8","groupKey":"シュー圧着_防水メカ_Hot_Shoe_Leaf_Springs","assembledPos":[0,57.2,-7.5],"explodeOffset":[0,56,-4],"integratedExplodeOffset":[0,134,-6],"edgeOpacity":0.22,"title":"B19. ホットシュー ステンレス板バネ接地圧着プレート ＆ 21ピン防水デジタルFPC","subtitle":"Hot-Shoe Stainless Leaf-Spring Retention Plate, Rain-Seal Skirt & 21-Pin Digital FPC","category":"シュー圧着＆防水メカ / Hot-Shoe Leaf Springs","plainAnalogy":"ホットシューの金属レールの下に隠れた「2本の弾力ステンレス板バネ」と「防水ゴムスカート」です。差し込んだストロボやマイクをグッと上へ押し付けてガタつきを消し、雨粒から21本の超微細ピンを守ります。","summary":"21ピンマルチインターフェース・ホットシュー（B06）の直下に組み込まれた内部機械・電気インターフェース層。大型クリップオンストロボの金属脚をガタなく固定＆電気接地（GND）する精密プレス成形SUS301ステンレス双葉板バネ、EVFルーフ貫通部の浸水を遮断する成型シリコーン防水スカート、および21ピンデジタル音声信号をメイン基板へ運ぶEMIシールド付きマイクロFPCで構成されます。","opticsAndPhysics":["双葉カンチレバー板バネによるガタ除去＆低抵抗GND：シューレールとアクセサリー脚の間には着脱しやすいよう約0.3 mmの挿入クリアランスが必要ですが、底面から双葉ステンレス板バネが約12 Nの弾性力で上向きに押し上げることで、撮影中の微振動ガタとX同調接地不良を同時に解消します。","21ピン高速デジタルI2S音声シールドFPC：ホットシュー最先端の21ピンコネクタはストロボ大電流ノイズと近接するため、24-bitデジタルオーディオ伝送ラインを全面導電黒色EMIシールド膜で覆いSN比108 dB超を死守します。","二重リップ成型シリコーン防水パッキン：トップデッキのEVF頂上という最も雨滴が直撃する位置に開いた配線貫通孔を、高圧縮シリコーンスカートで完全気密封止します。"],"formula":{"expression":"F_clamp = 2 · (3 E I / L³) · δ ≈ 12 N   (ストロボ脚ガタ除去＆確実GND圧着)","description":"両持ち・片持ちステンレス板バネのたわみ弾性力。大型フラッシュ装着時の微細ガタと接点瞬間浮きを完全抑制します。"},"nextGenInnovation":"2024–2026年世代では、重量級XLRオーディオユニットや高速連写ストロボの衝撃荷重に耐えるため、板バネだけでなく台座裏面へ高強度ステンレス補強裏板を配してマグネシウムルーフの変形を防ぎます。","specs":[{"label":"圧着バネ","value":"SUS301-CSP ばね用ステンレス鋼 双葉板バネプレート"},{"label":"防水封止","value":"シュー台座貫通部 成型シリコーン防水スカートガスケット"},{"label":"デジタル配線","value":"21ピン 4chデジタル音声＆スマート制御 EMIシールドFPC"},{"label":"保持圧着力","value":"約 12 N（ガタ除去＋X同調低インピーダンスGND）"}],"diagramType":"body_hotshoe_springs"},{"id":"body-card-ejectors","order":20,"swatchColor":"#b45309","groupKey":"メディア排出メカ_Heart_Cam_Card_Ejectors","assembledPos":[-59.5,-5,-14.5],"explodeOffset":[-42,-6,-34],"integratedExplodeOffset":[-102,-6,-42],"edgeOpacity":0.22,"title":"B20. デュアルCFexpress／SD プッシュプッシュ「ハートカム」カード排出メカ","subtitle":"Dual CFexpress / SD Push-Push Heart-Cam Mechanical Card Ejector Rails & Detect Switches","category":"メディア排出メカ / Heart-Cam Card Ejectors","plainAnalogy":"メモリーカードを「カチッ」と押し込むと止まり、もう一度押し込むと「ポンッ」と飛び出てくる魔法の仕組み！中身はボールペンのノックとそっくりな「ハート型の迷路（ハートカム）」と小さなバネの金属レールです。","summary":"右手グリップ後部（カード扉B10の内側）に2段スタックされたデュアルメモリーカードスロットの心臓部となる、精密機械式プッシュ・プッシュ排出機構。ステンレス製スライダーレール、真鍮／樹脂精密成形「ハート型カム溝（Heart-Cam Track）」、溝をトレースするステンレス線ばねガイドピン、押し出しコイルスプリング、そしてカード挿入・ライトプロテクト検知用金メッキリーフスイッチ群を再現しています。","opticsAndPhysics":["ハート型閉ループカム（Heart-Cam）の双安定キネマティクス：カードを1回押し込むと線ばねピンがハート溝の右側経路を滑って中央の窪み（ロック谷）へ落ち込み静止します。2回目に軽く押し込むとピンが窪みから外れて左側帰還経路へ移動し、圧縮コイルバネが一気にカードを排出します。","段階的段差ガイド溝による逆流防止：ハート溝の底面にミクロン単位の段差（一方向スロープ）を刻むことで、線ばねピンが絶対に逆回転せず10万回の抜き差しでも確実にロック⇔排出を交互実行します。","CFexpress高挿抜力対応デュアルガイド：PCIe高速コネクタ（CFexpress）はSDカードより高いピン挿抜荷重を必要とするため、焼き入れステンレスガイドレールと大径リターンスプリングで斜め挿入によるピン曲がりを防ぎます。"],"formula":{"expression":"状態遷移: [排出] →(右溝+段差)→ [ハート谷ロック] →(左帰還溝)→ [コイルバネ排出]","description":"電力ゼロの純機械式双安定メモリー機構（ハートカム）。カード挿入時のわずかな過押しストローク（約1.8 mm）だけでロックと解放を切り替えます。"},"nextGenInnovation":"最新世代のデュアルスロットでは、CFexpress Type AとUHS-II SDカードを同じスロット内で物理識別して両方使えるハイブリッドガイド＆デュアルプッシュ排出機構も実用化されています。","specs":[{"label":"排出機構","value":"純機械式プッシュ・プッシュ「ハートカム」双安定トラック×2"},{"label":"トレース機構","value":"SUS304-WPB ステンレス線ばねフォロワーピン ＋ 復帰コイルバネ"},{"label":"検知接点","value":"カード挿入検知＆ライトプロテクト検知 金メッキリーフスイッチ"},{"label":"挿抜耐久","value":"> 50,000 回（斜め挿入防止ステンレスガイドレール付）"}],"diagramType":"body_card_ejectors"},{"id":"body-card-door-latch","order":21,"swatchColor":"#dc2626","groupKey":"扉安全ロックメカ_Card_Door_Interlock","assembledPos":[-67.8,-5,-13.5],"explodeOffset":[-56,22,-26],"integratedExplodeOffset":[-124,24,-36],"edgeOpacity":0.22,"title":"B21. カード扉2アクション・スライドロックカム ＆ 扉開放安全インターロック機構","subtitle":"Card Door Dual-Action Slide-Lock Catch Cam, Pop-Open Torsion Spring & Interlock Switch","category":"扉安全ロックメカ / Card Door Interlock","plainAnalogy":"メモリーカード扉の裏側にある「スライド式の鍵フック」と「扉が開いたのを瞬時にカメラへ知らせる安全スイッチ」です。8K動画を保存している最中にうっかり扉を開けても、データを壊さないよう即座に非常ブレーキをかけます。","summary":"メモリーカードベイ扉（B10）の開閉を制御する内部機械ラッチ＆安全検知アセンブリ。ステンレス製ダブルロックフック付きスライドカムバー、解除と同時に扉を一定の角度まで自動で跳ね上げるヒンジトーションスプリング、そして扉のわずかな開き（0.5 mm）を即座に検出してメイン基板へ割り込み信号を送る「ドアオープン安全インターロックスイッチ」で構成されます。","opticsAndPhysics":["2フック均等パッキン圧縮カム：スライドロックレバーを閉じると、上下2箇所のテーパーフックがボディ側ストライカーを引き込み、カード扉全周のEPDM防水ガスケットを均一に25%圧縮して豪雨の浸水を完全阻止します。","データ破損防止ハードウェア割り込み：8K RAW書き込み中にカードを抜くとファイルシステムが破損するため、扉が開き始めた最初の0.5 mmでインターロックスイッチが反応し、カードに指が届く数十ミリ秒前までにバッファ強制フラッシュと電源遮断を完了させます。","トーションスプリングによる片手ポップオープン：スライド爪を引くだけでヒンジ軸に巻かれたトーションバネが扉を約15°手前へ押し開き、手袋のままでもスムーズに開扉できます。"],"formula":{"expression":"t_flush_protect < 25 ms  ≪  t_finger_reach ≈ 200 ms  (扉開検知でデータ完全保護)","description":"扉ロック解除検知からキャッシュ退避完了までの時間が人間の指がカードに触れる時間より圧倒的に短く、データ破損を物理的に防止。"},"nextGenInnovation":"プロ機ではカード扉のロック機構に「ロック解除レバーを下に引いたまま扉を後ろへスライドさせる」2段階ロックを採用し、グリップを強く握り込んでも絶対に誤開放しない安全設計としています。","specs":[{"label":"ロックカム","value":"ステンレス2点テーパー引き込みフック（防水パッキン均一圧着）"},{"label":"開扉アシスト","value":"ヒンジ同軸ステンレス・トーションポップアップバネ"},{"label":"安全検知","value":"超高応答ドアオープン・インターロック・マイクロスイッチ"},{"label":"防水圧縮率","value":"扉全周ガスケット 約 25% 均一圧縮保持"}],"diagramType":"body_card_door_latch"},{"id":"body-joystick-gimbal","order":22,"swatchColor":"#10b981","groupKey":"背面AF精密スイッチ_8_Way_Joystick_Gimbal","assembledPos":[-44,7.5,-30],"explodeOffset":[-34,16,-38],"integratedExplodeOffset":[-78,18,-162],"edgeOpacity":0.22,"title":"B22. 8方向AFマルチセレクター 4軸ジンバルロッカー ＆ 5接点タクタイル基板","subtitle":"8-Way AF Multi-Selector 4-Axis Gimbal Rocker Actuator & 5-Dome Micro-Switch PCB","category":"背面AF精密スイッチ / 8-Way Joystick Gimbal","plainAnalogy":"親指でグリグリ動かすAFジョイスティックの真裏に隠れた「極小の十字シーソー機構」と「5つの極小クリックボタン」です。上下左右だけでなく斜め45°も2つのスイッチの同時押しで軽快に読み取ります。","summary":"背面操作パネル（B09）の8方向AFマルチセレクター・ジョイスティック直裏に組み込まれた超小型精密ジンバルアクチュエーターユニット。ステンレス製十字ジンバルロッカー、中心軸の垂直押し込み（AFリセット／決定）用プランジャー、高耐久5点金メッキ金属ドームスイッチ実装サブPCB、および防塵シリコーンベローズで構成されています。","opticsAndPhysics":["4軸十字ジンバルによる斜め8方向高精度合成：上下左右の90°位置に4つの独立タクタイルドームを配置し、斜め45°方向へ傾けた際は隣接する2つのドームを均一なテコ比で同時押下する幾何設計により、斜め入力の抜け・誤爆を徹底排除します。","中央プッシュ独立ストローク機構：軸を傾けずに真直ぐ押し込んだ時だけ中央の第5ドームが作動するよう、ロッカー周囲に精密ガイドリングを設けて「押し込みつもりが斜めにズレる」ミスを防止します。","防塵防水シリコーン蛇腹（ベローズ）シール：ジョイスティックは背面で最も隙間が生じやすい可動軸ですが、付け根を極薄シリコーンゴム蛇腹で密閉することで軽快な操作感と全天候防水を両立しています。"],"formula":{"expression":"θ_tilt = ±12°,   F_cardinal ≈ 2.2 N,   F_diagonal ≈ √2 · F_single (最適カム補正)","description":"±12°の極短傾斜角で8方向すべての操作荷重を均一化。スポーツ撮影で目にも留まらぬ速さでAF測距点を移動できます。"},"nextGenInnovation":"最新のプロ機では、ジョイスティック頂面の微細凹凸パターンだけでなく内部ジンバルのバネ定数を刷新し、わずかな親指の重心移動だけで斜め方向へ吸い付くように追従する高応答設計へ進化しています。","specs":[{"label":"可動機構","value":"超小型ステンレス4軸十字ジンバルロッカー ＋ 中央プッシュ軸"},{"label":"スイッチ構成","value":"5点金メッキ極小スナップドーム（4方位＋中央決定）"},{"label":"最大傾き角","value":"±12°（8方向＋中央押し込み・高応答設計）"},{"label":"防水機構","value":"可動軸密着シリコーン蛇腹（ベローズ）シール内蔵"}],"diagramType":"body_joystick_gimbal"},{"id":"body-rear-wheel-encoder","order":23,"swatchColor":"#6366f1","groupKey":"背面複合ホイール_Hollow_Ring_Encoder","assembledPos":[-48,-13,-30],"explodeOffset":[-36,-16,-38],"integratedExplodeOffset":[-84,-18,-162],"edgeOpacity":0.22,"title":"B23. 背面コントロールホイール 中空リング光学エンコーダー ＆ 4方向ドーム基板","subtitle":"Rear Control Wheel Hollow-Center Ring Encoder, Click Detents & 4-Way Cardinal Domes","category":"背面複合ホイール / Hollow Ring Encoder","plainAnalogy":"背面にある「クルクル回せて上下左右にも押せるドーナツ型ホイール」の中身です。真ん中が空洞になったスリット円板で回転を読み取りながら、その下にある4つの金属ボタンで十字キー操作も同時にこなします。","summary":"背面親指エリアの複合コントロールホイール（B09）を支える中空同心円（ホローセンター）構造の多機能メカニカルエンコーダー。中央決定ボタン用の貫通空間を確保したまま外周で回転角を読み取るリング型スリットエンコーダー、真鍮クリックディテント球リング、およびホイール自体の上下左右4方向＋中央の計5点タクタイルスイッチを搭載した円形サブPCBで構成されます。","opticsAndPhysics":["中空（ホロー）同心円メカによる極薄3機能統合：通常のエンコーダーは中央に回転軸が貫通するため中央ボタンを置けませんが、外周リング軸受＋中空スリット円板とすることで「回転・4方向傾斜・中央押下」の3機能を厚さわずか3.8 mmの超薄型スペースへ収めています。","非接触光学式フォトリフレクタ／フォトインタラプタ読取：リング外周に刻まれた36ピッチの微細光学パターンを非接触読み取りし、数千枚の連写画像を高速スクロールしても接点摩耗ゼロを実現。","傾き誤爆防止クリアランス設計：ホイールを回転させる指の力では4方向スイッチが誤動作せず、明確に押し込んだ時（約2.6 N）だけ十字キーが反応するよう精密なヒンジ支点ギャップを設けています。"],"formula":{"expression":"h_stack = 3.8 mm  (回転エンコーダー ＋ 4方向チルト ＋ 中央プッシュ 3機能同軸積層)","description":"4軸LCDと背面基板のわずかな隙間に3種類の操作入力を高密度積層した、ミラーレス特有の超薄型メカ設計です。"},"nextGenInnovation":"背面ホイールにも防塵シリコンメンブレンシートを1枚挟み込むことで、クリック感を保ったまま汗や雨滴が背面基板へ侵入する経路を遮断しています。","specs":[{"label":"回転検出","value":"中空ドーナツ型 36パルス非接触リング光学エンコーダー"},{"label":"押下スイッチ","value":"4方向カーディナル＋中央決定 計5点スナップドーム基板"},{"label":"クリック機構","value":"真鍮ディテントリング ＋ ステンレス球ばねプランジャー"},{"label":"実装厚さ","value":"約 3.8 mm（超薄型3機能同軸モジュール）"}],"diagramType":"body_rear_wheel_encoder"},{"id":"body-strap-anchors","order":24,"swatchColor":"#64748b","groupKey":"高荷重構造骨格_Forged_Strap_Anchors","assembledPos":[0,22.5,0],"explodeOffset":[0,26,-34],"integratedExplodeOffset":[0,44,-36],"edgeOpacity":0.22,"title":"B24. 左右高荷重ネックストラップ吊り金具 鍛造ステンレス内部補強アンカー板","subtitle":"Left & Right Forged Stainless Neck-Strap Lug Internal Reinforcement Plates & Tri-Bolts","category":"高荷重構造骨格 / Forged Strap Anchors","plainAnalogy":"重い望遠レンズを着けたカメラを首や肩からぶら下げたとき、外装が千切れたり割れたりしないよう、内側から「3本の太いネジと分厚いステンレス鉄板」でガッチリ裏打ちしている隠れた力持ちパーツです。","summary":"ボディ左右肩部から突き出すネックストラップ用ステンレス吊り金具（アイレット）を、マグネシウム外装の内側から強固に受け止める左右一対の鍛造ステンレスL字補強アンカープレート。外装カバーの薄肉部へ直接荷重をかけず、高張力M2.0トライボルト3本ずつで内部モノコック骨格へ直接せん断・引張荷重を逃がすフェイルセーフ構造です。","opticsAndPhysics":["大口径レンズ携行時の動的衝撃荷重対策：ボディ＋大口径レンズ（総重量約2.5〜3.5 kg）を肩から下げて走るだけで、ストラップ金具には瞬間的に静荷重の5〜8倍（200〜250 N以上）の動的衝撃荷重がかかります。鍛造ステンレス裏板で応力集中を広面積へ分散します。","3点トライアングル締結（Tri-Bolt）：ネジ2本では前後方向のねじりモーメントで緩みやすいですが、三角形配置の3本のステンレスボルト＋ゆるみ止め樹脂塗布により長年の揺れでも絶対にガタつきません。","貫通部防水エラストマーグロメット：吊り金具の貫通スリット周囲を圧縮ゴムグロメットで塞ぎ、雨天時の首掛け運用でも肩部からの浸水ルートを断ち切ります。"],"formula":{"expression":"F_proof = 500 N (約 50 kgf 静的引張保証)   ⇒   安全率 SF > 12 (3.5 kg機材携行時)","description":"左右それぞれ約50 kgの引張荷重に耐える鍛造ステンレス内部アンカー構造。プロ機にとって絶対に破損が許されない重要保安部品です。"},"nextGenInnovation":"最新のプロ機では、動画収録時の「三角環のカチャカチャ音」を完全に消すため、静音ダンパーブッシュを内蔵した固定式バーアイレットや防振スリーブ構造を採用しています。","specs":[{"label":"補強板材質","value":"SUS304 鍛造高剛性 L字内部アンカープレート（左右一対）"},{"label":"締結方式","value":"M2.0 高張力ステンレスボルト 3点三角締結×左右（計6本）"},{"label":"保証耐荷重","value":"> 500 N（約 50 kgf）動的衝撃安全設計"},{"label":"防水対策","value":"アイレット貫通部 EPDM圧縮防水グロメット付"}],"diagramType":"body_strap_anchors"},{"id":"body-acoustic-breather","order":25,"swatchColor":"#06b6d4","groupKey":"音響_防水通気メカ_Acoustic_ePTFE_Vent","assembledPos":[0,33,17.5],"explodeOffset":[0,26,36],"integratedExplodeOffset":[0,68,42],"edgeOpacity":0.22,"title":"B25. 防水ステレオMEMSマイク音響室・圧電ブザー ＆ ePTFE気圧調整ブリーザー弁","subtitle":"Waterproof Stereo MEMS Mic Chambers, Piezo Buzzer & ePTFE Barometric Breather Vent","category":"音響＆防水通気メカ / Acoustic & ePTFE Vent","plainAnalogy":"雨粒は絶対に通さないのに空気と音だけはスッと通す不思議なハイテク布（ゴアテックスの仲間）を貼った「ステレオ耳（マイク）」「合焦お知らせピッ音スピーカー」と、高山や飛行機でカメラの中がパンパンにならないよう息をする「防水換気口」です。","summary":"トップデッキ前肩の裏側（B08ステレオマイク孔の直下）に配置された複合音響・気圧制御ユニット。防振シリコーンブーツに収められた左右高SNRステレオMEMSマイク音響チャンバー、ピント合焦音やセルフタイマー音を鳴らす薄型真鍮圧電（ピエゾ）ブザー、そして水滴を弾きつつ気圧変化のみを逃がす微多孔延伸PTFE（ePTFE）防水通気ブリーザーメンブレンで構成されます。","opticsAndPhysics":["撥水微多孔ePTFEメンブレンの毛細管防水原理：孔径わずか約0.2 μmの極小フッ素樹脂細孔は、空気分子（音波や気圧差）を抵抗なく透過させつつ、表面張力を持つ水滴（最小数百μm）に対しては高いラプラス侵入圧（ΔP > 30 kPa）を発揮して完全ブロックします。","防振シリコーン・アイソレーション音響室：ボディ内蔵マイクの最大の敵はレンズAFモーター音やIBIS手ブレ補正の固体伝播振動（ボーンコンダクション）です。MEMSマイクを軟質シリコーンチャンバーで浮かせて保持することで内部メカ音の混入を約15 dB低減します。","高度・温度変化に対する内圧イコライズ：完全密閉ボディで飛行機移動や冬山登山を行うと内外気圧差で防水パッキンやLCDが膨張・吸湿しますが、ePTFEブリーザーが常時内外気圧を等しく保ちます。"],"formula":{"expression":"ΔP_water = (2 · γ · |cos θ_c|) / r_pore > 30 kPa   (r_pore ≈ 0.2 μm, θ_c > 115°)","description":"ヤング・ラプラス式による防水通気膜の耐水圧。音と空気は素通りさせながら雨水の浸入を物理法則で阻止します。"},"nextGenInnovation":"最新世代の動画ハイブリッド機では、前後3カプセル指向性MEMSアレイとAI風切り音・ノイズキャンセリングを組み合わせ、外部マイク無しでも驚くほどクリアなボイス収録を実現しています。","specs":[{"label":"内蔵マイク","value":"高SNR デジタルステレオMEMSマイク（シリコーン防振室×2）"},{"label":"防水音響膜","value":"撥水・撥油 ePTFE（延伸フッ素樹脂）微多孔メンブレン"},{"label":"発音素子","value":"薄型真鍮ダイアフラム圧電（ピエゾ）確認ブザー"},{"label":"内圧調整","value":"気圧イコライズ防水ブリーザーベント（高度・温度変化対応）"}],"diagramType":"body_acoustic_breather"},{"id":"body-chassis-gaskets","order":26,"swatchColor":"#0f766e","groupKey":"全天候防水シール網_3D_Chassis_Gaskets","assembledPos":[-6,0,-2],"explodeOffset":[0,-26,-30],"integratedExplodeOffset":[0,-56,-30],"edgeOpacity":0.22,"title":"B26. 全周3D一体成型シリコーン防塵防滴ガスケット ＆ ラビリンス防水シール骨格","subtitle":"Full-Body 3D Molded Silicone Weather-Sealing Perimeter Gaskets & Labyrinth Seals","category":"全天候防水シール網 / 3D Chassis Gaskets","plainAnalogy":"潜水艦のハッチのように、カメラの正面・背中・屋根・底板のすべての継ぎ目にぐるりと張り巡らされた「3D立体の防水ゴムパッキン網」です。豪雨や砂嵐の中でも内部の基板やセンサーへ一滴の水も通しません。","summary":"フロントモノコック（B07）、トップデッキ（B08）、背面パネル（B09）、底板（B12）の全外装接合シームとレンズマウント外周を3次元的に継ぎ目なく封止する、精密成型EPDM／シリコーンゴム製ペリメーター・ウェザーシーリングガスケット網。単なる平面ゴム板ではなく、外装の段差迷路（ラビリンス構造）と噛み合って全周均一な圧縮反力を生む立体シール骨格です。","opticsAndPhysics":["ラビリンス（迷路）＋圧縮シールの二重防壁：まず外装合わせ面のクランク型段差（ラビリンス構造）で勢いのある雨粒や砂埃の運動エネルギーを殺ぎ、さらにその奥のシリコーンガスケットを20〜30%圧縮して毛細管現象によるジワジワ浸水まで完全遮断します。","圧縮永久歪み（Compression Set）の極小化：何年もネジで強く挟み込まれ続けてもゴムが潰れっぱなし（ヘタリ）にならない高弾性パーオキサイド架橋シリコーン／EPDM配合を採用し、−20℃の氷点下でも柔軟な密着性を維持します。","レンズマウント外周＆トップシームの重点シール：最も水がかかりやすいトップデッキ継ぎ目とレンズ着脱境界面には、二重リップ形状の精密Oリングガスケットを配置しています。"],"formula":{"expression":"ε_comp = (t_0 − t_assembled) / t_0 ∈ [0.20, 0.30]   (最適防水面圧・反力バランス)","description":"ガスケット圧縮率20〜30%の精密公差設計。低すぎると浸水し、高すぎるとマグネシウム外装に歪みが生じるためミクロン単位で溝深さを管理します。"},"nextGenInnovation":"近年のフラッグシップ機は、各パーツにバラバラのパッキンを貼る代わりに、ボディ全周・ダイヤル軸・ボタン裏・マウント周囲の計60〜90箇所以上をシームレスに連結したトータル・ウェザーシーリング設計を採用しています。","specs":[{"label":"シール材質","value":"低圧縮永久歪み 耐候シリコーン／EPDM 3D一体成型ゴム"},{"label":"封止エリア","value":"上面・底面・前面・背面全周シーム ＋ マウント外周Oリング"},{"label":"設計圧縮率","value":"20〜30%（外装ラビリンス段差接合との二重防壁）"},{"label":"耐環境温度","value":"−20 ℃ 〜 +60 ℃ 全天候プロフィールド対応"}],"diagramType":"body_chassis_gaskets"},{"id":"body-top-sub-lcd","order":27,"swatchColor":"#06b6d4","groupKey":"B27_肩部ステータス表示ユニット","assembledPos":[-35,38.6,6],"explodeOffset":[-36,56,22],"integratedExplodeOffset":[-64,128,28],"edgeOpacity":0.22,"title":"B27. 肩部反射型ステータスサブOLEDモジュール＆防水EPDMガスケット枠","subtitle":"Top-Shoulder High-Contrast Status Sub-OLED Display, Cover Glass & Weather Seal Frame","category":"B27 / 肩部ステータス表示ユニット","plainAnalogy":"カメラの右肩に埋め込まれた「小さな情報ウィンドウ」を分解した姿です。傷に強いカバーガラス、真夏の直射日光でもくっきり見える高コントラストOLEDパネル、そして雨水の侵入を防ぐゴムパッキン枠の多重構造になっています。","summary":"B05上面操作系から独立モジュール化された、肩部ステータス表示用モノクロ／反転表示OLEDディスプレイユニット。ARコート強化カバーガラス、超低消費電力パッシブマトリクスOLEDパネル、COFドライバーIC付き極薄FPC、およびトップデッキ開口部を密閉するEPDM防水ガスケット枠で構成されます。","opticsAndPhysics":["電源OFF時でも設定状態を確認できる反射／高輝度OLED構造により、真夏の直射日光下から星空撮影の暗闇（反転ダーク表示）まで一瞬でシャッター速度・絞り・電池残量を視認できます。","トップデッキ上面は雨滴が最も直撃する部位であるため、カバーガラス外周を段付き圧縮ガスケットで全周封止し、水滴の毛細管侵入を完全に遮断します。"],"formula":{"expression":"P_subOLED ≈ 18 mW (常時視認)   /   カバーガラス表面硬度 ≥ 7H (AR反射率 < 1.2%)","description":"背面メイン液晶を消灯したまま超省電力で主要パラメータを確認でき、バッテリー駆動時間を延長。"},"nextGenInnovation":"Canon EOS R5 IIやNikon Z8等の上位機では、ボタン操作ひとつで白地黒文字⇔黒地白文字（夜間暗順応保護）を瞬時に切り替えられる高精細ステータスディスプレイが定番化しています。","specs":[{"label":"表示素子","value":"高コントラスト モノクロ反転表示 ステータスサブOLED"},{"label":"保護窓","value":"AR無反射コート強化カバーガラス（耐擦傷 7H級）"},{"label":"駆動回路","value":"COF（Chip-on-Flex）一体型 省電力OLEDドライバーFPC"},{"label":"防水構造","value":"段付き全周EPDM圧縮ガスケット枠 ＋ 耐候粘着シール"}],"diagramType":"body_top_sub_lcd"},{"id":"body-vgrip-contacts","order":28,"swatchColor":"#eab308","groupKey":"B28_縦位置グリップ高電流・操作系拡張バス","assembledPos":[-28,-34.2,-14],"explodeOffset":[-28,-62,-16],"integratedExplodeOffset":[-56,-104,-18],"edgeOpacity":0.22,"title":"B28. 縦位置バッテリーグリップ用 12ピン金メッキ拡張接点＆防水シール蓋","subtitle":"Vertical Battery Grip 12-Pin Gold Pogo-Pin Interface Block & Weather-Seal Cap","category":"B28 / 縦位置グリップ高電流・操作系拡張バス","plainAnalogy":"スポーツカメラマンが縦構図で撮りやすくする「縦位置グリップ」を底にドッキングさせたとき、2本目のバッテリー電力と縦位置シャッターボタン信号をカメラ本体へ伝える「金色の秘密ドッキング端子」です。","summary":"バッテリー室下端および底板凹部へ設けられた、縦位置グリップ（バッテリー2本並列給電＋縦位置シャッター・AF-ON・ダイヤル・ジョイスティック信号）専用の12ピン金メッキ高電流接点ブロックと着脱式防水シリコーンキャップ。","opticsAndPhysics":["大電流給電用（V_BATT / GND各2系統並列）の太径金メッキ端子と、縦位置操作系スキャン用I²C/SPI通信端子を1つの高耐熱PPSブロックへ集約し、接触抵抗20 mΩ以下で電圧降下を防ぎます。","グリップ非装着時は底部からの泥水や砂の侵入を防ぐため、二重リップ付きシリコーン保護キャップが完全密閉します。"],"formula":{"expression":"R_contact < 20 mΩ × 2並列  →  6 A連写ピーク時の端子電圧降下 ΔV < 60 mV","description":"冗長並列化された金メッキ高電流端子により、縦位置グリップ経由でも本体直挿し同等の連写電力を供給。"},"nextGenInnovation":"近年のプロ機では、縦位置グリップ側に2.5GbE LAN端子や冷却ファン電源制御まで統合したマルチファンクション・ドッキングバスへ進化しています。","specs":[{"label":"接点構成","value":"12ピン金メッキ端子（高電流V_BATT/GND並列＋操作信号バス）"},{"label":"定格電流","value":"連続 6.0 A / ピーク 10.0 A 対応（低接触抵抗 < 20 mΩ）"},{"label":"絶縁材","value":"高剛性ガラス繊維強化PPS（UL94 V-0難燃・耐トラッキング）"},{"label":"防塵保護","value":"二重リップ防水シリコーン着脱キャップ付"}],"diagramType":"body_vgrip_contacts"},{"id":"body-rear-button-pcb","order":29,"swatchColor":"#ea580c","groupKey":"B29_背面操作系統合スイッチシート_防水層","assembledPos":[-6,0,-30.6],"explodeOffset":[0,0,-38],"integratedExplodeOffset":[-36,0,-172],"edgeOpacity":0.22,"title":"B29. 背面パネル全域メンブレンFPCスイッチ基板＆防塵シリコーンキーマット","subtitle":"Full-Coverage Rear Panel Metal-Dome Switch FPC Sheet & Silicone Keymat Membrane","category":"B29 / 背面操作系統合スイッチシート＆防水層","plainAnalogy":"背面のAF-ON・メニュー・再生・ゴミ箱ボタンの裏側にぴたりと張り付いた「パチパチ鳴る金色ドームボタン付きオレンジ色シート」と、その上を丸ごと覆う「透明な防水ゴムシート」です。","summary":"背面マグネシウム壁（B09）の内側全面に張り巡らされた、AF-ON・AEL・Fn・再生・削除・MENU・C3の各ボタンとカードアクセスLEDを統合実装する多層フレキシブルスイッチ基板（FPC）と、一体成型シリコーン防水メンブレンキーマット。","opticsAndPhysics":["各ボタン直下にステンレス／金メッキ4脚スナップドームを配置し、押下荷重約2.2 N・クリック率45%の明確なタクタイルフィードバックで、ファインダーから目を離さずに確実なブラインド操作を行えます。","スイッチFPC全面を一体型シリコーンゴムの防水膜で覆うことで、雨天時にボタン隙間から浸入した水滴が電気接点へ触れるのを100%防ぎます。"],"formula":{"expression":"Click Ratio = (F_peak − F_bottom) / F_peak ≈ 45%   (F_peak ≈ 2.2 N, 耐久 30万回)","description":"手袋越しでも明確に判別できる45%クリックスナップ特性と完全防水メンブレンを厚さ1.2 mmで両立。"},"nextGenInnovation":"暗所でのスタジオ・星景撮影向けに、極薄導光シートとマイクロLEDを組み合わせた背面ボタン・イルミネーション機構を統合したモデルも増えています。","specs":[{"label":"スイッチ素子","value":"金メッキ4脚ステンレス・スナップドーム × 7系統＋LED駆動"},{"label":"基板構造","value":"異形抜き多層ポリイミドFPC ＋ 局所SUSスティフナー補強板"},{"label":"防水層","value":"ボタン隙間完全隔離 一体成型シリコーン・キーマット膜"},{"label":"操作耐久","value":"30万回以上押下保証（AF-ONボタンは高耐久強化仕様）"}],"diagramType":"body_rear_button_pcb"},{"id":"body-front-custom-pod","order":30,"swatchColor":"#ef4444","groupKey":"B30_前面ファンクション操作_撮影状態表示光学","assembledPos":[-3,0,27.6],"explodeOffset":[-28,12,74],"integratedExplodeOffset":[-34,14,96],"edgeOpacity":0.22,"title":"B30. 前面カスタムC5（プレビュー）スイッチポッド＆AF補助光／タリーLED導光部","subtitle":"Front Custom C5 Tactile Switch Pod & Dual-Color Tally/AF-Assist Optical Light-Pipe","category":"B30 / 前面ファンクション操作＆撮影状態表示光学","plainAnalogy":"レンズのすぐ横にある「中指・薬指で押せるカスタムボタンの中身」と、動画録画中やセルフタイマーのときに赤やオレンジに光る「透明な光ガイド棒（ライトパイプ）とLED基板」のセットです。","summary":"B07前面マグネシウムシェルから分離構造化された、前面カスタムFn（C5／絞り込みプレビュー／スピードブースト）防水タクタイルスイッチユニットと、高輝度AF補助光／動画録画タリー赤色LED＋アクリル導光ライトパイプ光学ポッド。","opticsAndPhysics":["Sony α1 II／α9 IIIで新設された前面C5ボタンはグリップを握ったまま中指で瞬時に「連写速度ブースト（120fps切替）」等を起動できるよう、高剛性内部ブラケットで支持されています。","タリーランプは基板上の高輝度SMD LEDの光を全反射ポリカーボネート・ライトパイプで前面シェル外表面まで導くことで、防水シームを保ちつつ広い視認角度（±75°）で録画中を被写体へ伝えます。"],"formula":{"expression":"θ_c = arcsin(1 / n_PC) ≈ 39.2°  (全反射ライトパイプ伝送効率 > 88%)","description":"内部LEDの光を全反射導光パイプで前面へ導くことで、防水構造を損なわず高視認なタリー表示を実現。"},"nextGenInnovation":"前面C5カスタムボタンは高速連写ブーストやプリ撮影切替など、プロスポーツ撮影の瞬間操作を支える新世代フラッグシップの象徴的インターフェースです。","specs":[{"label":"操作機構","value":"前面C5カスタム防水タクタイルスイッチ ＋ Oリング封止軸"},{"label":"光学部","value":"AF補助光＆赤色動画タリー兼用 2色LED ＋ 全反射ライトパイプ"},{"label":"視認角","value":"±75° 広視野角ドームレンズ仕上げ（スタジオ収録対応）"},{"label":"接続方式","value":"前面モノコック裏側 極細ポリイミドFPC 2系統接続"}],"diagramType":"body_front_custom_pod"},{"id":"body-speaker-chamber","order":31,"swatchColor":"#475569","groupKey":"B31_動画音声・音声メモ再生アコースティック室","assembledPos":[38.5,-26,-26.5],"explodeOffset":[44,-36,-34],"integratedExplodeOffset":[74,-42,-148],"edgeOpacity":0.22,"title":"B31. 密閉型ネオジム再生用マイクロスピーカ音響箱＆防塵アコースティック網","subtitle":"Sealed Neodymium Playback Micro-Speaker Acoustic Box & Protective Mesh","category":"B31 / 動画音声・音声メモ再生アコースティック室","plainAnalogy":"撮った動画の音声やプロカメラマンが吹き込んだ音声メモをその場で聞き返すための「極小の密閉型スピーカーボックス」です。小さな箱で音を響かせることでクリアな声を届けつつ、防水メッシュで砂埃を止めます。","summary":"ボディ背面下側コーナーのデッドスペースに収められた、密閉バックキャビティ付きネオジム磁石ダイナミック・マイクロスピーカユニット、撥水防塵アコースティックメッシュ、および無ハンダ金メッキばね接点ブロック。","opticsAndPhysics":["直径わずか12 mmクラスの超薄型スピーカー単体では低〜中音域が打ち消し合うため、背面側を気密樹脂チャンバー（約0.8 cm³）で密閉して音響ショートを防ぎ、人声帯域（500 Hz〜4 kHz）の音圧を約+8 dB向上させています。","防水防塵アコースティック網と振動吸収フォームガスケットにより、外装のビビり音（共振）と水滴浸入を同時に抑止します。"],"formula":{"expression":"f_res = (1 / 2π) · √( (k_susp + ρ c² S² / V_box) / m_eff ) ≈ 780 Hz","description":"密閉バックキャビティ体積 V_box の最適化により、超小型ながら明瞭な音声・操作音再生を実現。"},"nextGenInnovation":"報道カメラマンの音声メモ（Voice Memo）再生や撮影現場での迅速な収録音声チェックのため、省スペースながら歪みの少ないネオジム・リニアドライバーが採用されています。","specs":[{"label":"ドライバー","value":"ネオジム磁石 薄型ダイナミック・マイクロスピーカ（8 Ω / 0.8 W）"},{"label":"音響構造","value":"気密ABSバックキャビティ（約 0.8 cm³）＋ 制振ガスケット"},{"label":"保護網","value":"撥水防塵 ステンレス／ナイロン複合アコースティックメッシュ"},{"label":"接続端子","value":"メイン基板直当て 金メッキスプリングコンタクト × 2"}],"diagramType":"body_speaker_chamber"},{"id":"body-pc-sync-terminal","order":32,"swatchColor":"#cbd5e1","groupKey":"B32_スタジオ大型ストロボ有線同調インターフェース","assembledPos":[54.2,18,14.5],"explodeOffset":[68,20,24],"integratedExplodeOffset":[108,24,34],"edgeOpacity":0.22,"title":"B32. ネジロック式PCフラッシュシンクロ同軸端子＆高耐圧絶縁トリガー基板","subtitle":"Threaded PC Flash Sync Coaxial Terminal & High-Voltage Opto-Isolated Trigger Board","category":"B32 / スタジオ大型ストロボ有線同調インターフェース","plainAnalogy":"プロ用スタジオの大型ストロボをケーブルで直接つなぐための「ネジ止め式まる型シンクロ端子」です。古い大型ストロボからの高い電圧（数百ボルト）が来てもカメラの脳みそが壊れないよう、光で電気を遮断する安全回路を積んでいます。","summary":"左側面前端（+X側）に配置されたISO 519準拠ネジロック付きステンレスPCフラッシュシンクロ同軸端子、中心金メッキ電極ピン、防水ゴムキャップ、および400 V高耐圧フォトトライアック絶縁トリガー保護サブ基板。","opticsAndPhysics":["スタジオ用モノブロック／ジェネレーター式大型ストロボでは、電波混信が起きる展示会場や超高精度マルチ発光時に有線PCシンクロが不可欠。外周ネジロック機構が撮影中のケーブル抜けを防ぎます。","大型ストロボのトリガー端子には瞬間的に数十〜300 V超の電圧が印加される場合があるため、カメラ内部基板と物理的に電気絶縁するフォトカプラ／高耐圧サイリスタ駆動回路でメイン基板を守ります。"],"formula":{"expression":"V_blocking ≥ 400 V (DC/Peak),   t_trigger_delay < 15 μs  (1/400 s 同調対応)","description":"400V耐圧と15マイクロ秒未満の超低遅延トリガーにより、プロスタジオの高速同調撮影を確実に支えます。"},"nextGenInnovation":"グローバルシャッター機や1/400s高速シンクロ対応フラッグシップでは、電子／メカシャッター双方の厳密な発光遅延補正と組み合わせて完全同調を実現しています。","specs":[{"label":"端子規格","value":"ISO 519 準拠 ネジロック式 PCシンクロ同軸ソケット（極性保護付）"},{"label":"絶縁保護","value":"400 V 高耐圧 フォトトライアック／MOSFET 光絶縁トリガー回路"},{"label":"応答遅延","value":"< 15 μs（高速ストロボ同調・マルチ発光対応）"},{"label":"防塵保護","value":"脱落防止テザー付 EPDM防水ダストキャップ"}],"diagramType":"body_pc_sync_terminal"},{"id":"body-cooling-duct","order":33,"swatchColor":"#1e293b","groupKey":"B33_8K60p無ファン静音放熱・熱拡散流路","assembledPos":[-4,-2,-29.8],"explodeOffset":[0,-14,-46],"integratedExplodeOffset":[-18,-16,-184],"edgeOpacity":0.22,"title":"B33. 内部パッシブ放熱サーマル煙突ダクト＆高熱伝導グラファイト内張ライナー","subtitle":"Internal Passive Thermal Chimney Baffle Duct & Pyrolytic Graphite Liner","category":"B33 / 8K60p無ファン静音放熱・熱拡散流路","plainAnalogy":"冷却ファンを回してホコリを吸い込んだり録音にブーンという音を入れたりしない代わりに、カメラ内部の熱い空気と熱エネルギーを「黒いグラファイトの高速道路とアルミのヒレ」で外装全体へ静かに逃がすパッシブ放熱ダクトです。","summary":"メイン基板ベイパーチャンバー（M01）および背面RFシールドブラケット（M18）から受け取った8K60p処理熱を、マグネシウム外装および上部・側面へ均等分散させる内部アルミフィン付き熱拡散ダクト＆高面内熱伝導グラファイトシートライナー。","opticsAndPhysics":["ファンレス防塵防滴ボディで8K RAW長回しを実現する鍵は「局所ホットスポットの解消」。面内熱伝導率1,500 W/m·K級の人工グラファイトシート（PGS）を内壁ダクトへ張り巡らせ、特定部位だけ高温になって熱警告が出るのを防ぎます。","微細なアルミ放熱リブと内部対流バッフルが、背面チルト液晶を開いた状態の背面空間へ効率よく熱を放射・自然対流させます。"],"formula":{"expression":"q_spread = −k_inplane · A · (dT/dx)   (k_PGS ≈ 1,500 W/m·K, 無音・IP防塵維持)","description":"完全密閉・無騒音のままボディ全体の熱容量を最大限活用し、8K連続収録可能時間を大幅に延長。"},"nextGenInnovation":"Canon EOS R5 II（内部冷却ダクト構造）やSony Σ形状グラファイト構造など、2024〜2026年フラッグシップは防塵防滴とシネマ級放熱を高次元で両立しています。","specs":[{"label":"拡散ライナー","value":"面内 1,500 W/m·K 高配向性熱分解グラファイトシート（PGS）"},{"label":"ダクト骨格","value":"黒色アルマイト処理 高放射率アルミ薄板フィン＆熱流バッフル"},{"label":"防塵両立","value":"完全ファンレス密閉構造（音声収録ノイズ 0 dB・防塵防滴維持）"},{"label":"熱結合先","value":"M01/M18 背面熱源 → 背面・底面マグネシウム外装全体へ分散"}],"diagramType":"body_cooling_duct"},{"id":"body-port-reinforce","order":34,"swatchColor":"#94a3b8","groupKey":"B34_テザー・外部モニター配線こじり荷重防護","assembledPos":[52.4,-2,-7],"explodeOffset":[42,0,-6],"integratedExplodeOffset":[78,0,-12],"edgeOpacity":0.22,"title":"B34. 左側面I/Oポート群ステンレス張力補強枠＆ケーブルプロテクターネジ座","subtitle":"Left-Flank Stainless I/O Port Strain-Relief Reinforcement Frame & Cable-Clamp Bosses","category":"B34 / テザー・外部モニター配線こじり荷重防護","plainAnalogy":"太くて硬いHDMIケーブルやテザー撮影用USBケーブルを挿した状態でうっかり引っかけても、基板側のコネクタがもげないよう、側面の裏側から「硬いステンレス枠とケーブル固定用ネジ穴」でガッチリ守る補強フレームです。","summary":"左側面（+X）の3分割I/Oドア（B11）内側にボルト固定されるCNC切削ステンレス製ポート周囲張力補強フレーム。HDMI 2.1・USB-C・2.5GbE LAN・3.5mm音声ジャックの各開口部を精密ガイドしつつ、付属ケーブルプロテクター装着用のねじ座を内部モノコックへ直結します。","opticsAndPhysics":["スタジオのテザー撮影やシネマリグ運用では、太い4K/8K HDMIケーブルや10m USB-Cケーブルの自重と引張トルク（曲げモーメント）がポートへ常時作用します。","基板ハンダ付け部へ直接応力を伝えず、外装内側のステンレス補強枠で横荷重を丸ごと受け止めることで、端子破損トラブルを劇的に低減します。"],"formula":{"expression":"M_cable = F_pull · L_plug  →  ステンレス補強枠で90%以上をシャーシへ逃がし基板ハンダ保護","description":"外部ケーブルからのこじりモーメントを基板ではなく高剛性ステンレス骨格で受け止めるプロ仕様設計。"},"nextGenInnovation":"Sony α1 II / α7R VやCanon R5 IIでは、ポート周囲の金属補強フレームと専用ケーブルロックプロテクターの組み合わせがスタジオ・動画プロ現場の必須装備となっています。","specs":[{"label":"材質加工","value":"SUS304 CNC精密加工 I/O周囲張力補強プレート（t = 1.6 mm）"},{"label":"保護対象","value":"2.5GbE RJ45 / フルサイズHDMI 2.1 / USB-C 10Gbps / 3.5mm音声"},{"label":"固定機能","value":"純正ケーブルプロテクター装着用 M2.5ステンレス雌ねじ座×2"},{"label":"防水連携","value":"B11 3分割I/Oドア EPDMパッキン着座基準面を精密形成"}],"diagramType":"body_port_reinforce"},{"id":"body-tripod-block","order":35,"swatchColor":"#64748b","groupKey":"B35_超望遠・シネマリグ三脚固定中枢骨格","assembledPos":[0,-37.2,0],"explodeOffset":[0,-32,10],"integratedExplodeOffset":[0,-68,12],"edgeOpacity":0.22,"title":"B35. 内部高荷重ステンレス三脚座ロードスプレッダー骨格＆4本シャーシ連結ボルト","subtitle":"Internal High-Load Stainless 1/4-20 UNC Tripod Load-Spreading Subframe & 4-Bolt Anchor","category":"B35 / 超望遠・シネマリグ三脚固定中枢骨格","plainAnalogy":"三脚にカメラをねじ込む「1/4インチのネジ穴」は、ただ底板に穴が空いているだけではありません。中を開けると、重いレンズやカメラを三脚1本で支え抜くための「分厚いステンレスの塊と4本の太い骨格ボルト」が本体フレームにガッチリ繋がっています。","summary":"B12底板から独立構造化された、光軸直下（x=0, z=0）に配置される高荷重SUS304削り出し1/4-20 UNC三脚座サブフレーム。ビデオ雲台用回り止めピン穴と4本の高張力M2.5アンカーボルトを備え、三脚荷重を底板だけでなく前面マグネシウムモノコックと内部ミッドフレームへ直接分散します。","opticsAndPhysics":["大口径レンズを装着したまま三脚に固定してカメラを垂直（ポートレート縦位置）に傾けると、三脚ネジ穴には強烈な片持ち曲げモーメントと引き抜き応力が集中します。","薄肉マグネシウム底板に直接ネジを切るのではなく、厚み6mm超のSUS304鍛造ブロックを内部フレームへ4点締結することで、プロ用クイックリリースプレートの強い締め付けトルク（> 8 N·m）でも絶対にネジ山破損や底板変形を起こしません。"],"formula":{"expression":"T_tighten ≤ 10 N·m,   F_pullout > 1,200 N  (1/4-20 UNC SUS304 4点骨格アンカー)","description":"約120 kgf以上の引き抜き耐荷重と光軸真下センタリングにより、パノラマ撮影時のノーダルズレも極小化。"},"nextGenInnovation":"メイン基板のヒートパイプ末端（M01）を三脚座近傍の金属熱マスへ熱結合させることで、三脚雲台自体を巨大ヒートシンクとして活用する熱設計も進んでいます。","specs":[{"label":"ねじ規格","value":"1/4-20 UNC（有効深さ 5.5 mm・ISO 1222準拠）＋ 動画回り止め穴"},{"label":"ブロック材","value":"SUS304 高剛性削り出し ロードスプレッダーサブフレーム"},{"label":"骨格連結","value":"高張力 M2.5 ステンレスボルト 4点締結（フロント・ミッドフレーム直結）"},{"label":"耐荷重設計","value":"引張破壊荷重 > 1,200 N / 締付許容トルク 10 N·m"}],"diagramType":"body_tripod_block"},{"id":"body-batt-door-hinge","order":36,"swatchColor":"#d97706","groupKey":"B36_ワンタッチ着脱式バッテリーハッチ蝶番機構","assembledPos":[-54.5,-35.6,-18.5],"explodeOffset":[-52,-52,-32],"integratedExplodeOffset":[-96,-86,-34],"edgeOpacity":0.22,"title":"B36. 縦位置グリップ対応・クイック脱着式バッテリー扉ステンレス蝶番＆スプリングピン","subtitle":"Quick-Detach Waterproof Battery Door Double-Jointed Stainless Hinge & Spring Pin","category":"B36 / ワンタッチ着脱式バッテリーハッチ蝶番機構","plainAnalogy":"縦位置グリップを着けるときに、工具なしでバッテリーのフタを斜め45°からスッと外せる「スライド式バネ入りステンレス蝶番」です。普段はガッチリ防水パッキンを押し付け、必要な時だけ一瞬で取り外せます。","summary":"バッテリー室下端の開閉および縦位置グリップ装着時のワンタッチ扉脱着を可能にする、ダブルジョイント式ステンレス蝶番アセンブリ。斜め45°ポジションでのみ解除可能なスプリング内蔵スライド脱着ピン、POM低摩擦スライダー、および開扉アシスト用トーションスプリングで構成されます。","opticsAndPhysics":["通常撮影時の開閉（0°〜95°）ではピンが底板側受け溝に完全ロックされて外れず、特定の脱着角度（約45°）でPOMスライダーを引いた時だけバネピンが引っ込み、工具ゼロで1秒脱着できます。","蝶番軸のわずかなフロート余裕設計により、閉扉時にB13ロック爪が扉を上方へ引き込んだ際、全周のEPDM防水パッキンが蝶番側も反対側も均等に圧縮されます。"],"formula":{"expression":"θ_detach = 45° ± 5° (誤脱落防止ゲート)   /   開閉耐久 ≥ 50,000 サイクル","description":"工具不要の1秒クイック脱着と、通常開閉時の絶対的な非脱落安全性を精密カム溝で両立。"},"nextGenInnovation":"取り外したバッテリー扉を紛失しないよう、純正縦位置グリップの差し込み柱内部にバッテリー扉専用の収納スロットを設けるエルゴノミクス設計が広く採用されています。","specs":[{"label":"脱着機構","value":"45°角度限定クイックリリース バネ内蔵ステンレススライドピン"},{"label":"軸受構造","value":"SUS304 ダブルジョイント蝶番 ＋ 低摩擦POMリリーススライダー"},{"label":"バネ機構","value":"開扉アシスト用ステンレス・トーションコイルスプリング"},{"label":"防水連携","value":"フロート公差設計（閉扉時 EPDMパッキン全周均一圧着）"}],"diagramType":"body_batt_door_hinge"},{"id":"body-perimeter-screws","order":37,"swatchColor":"#3b82f6","groupKey":"B37_実機分解アーキテクチャ・精密締結ファスナー体系","assembledPos":[0,0,0],"explodeOffset":[0,0,-68],"integratedExplodeOffset":[0,0,-214],"edgeOpacity":0.22,"title":"B37. ボディ外装24本色別・緩み止め付JIS精密小ねじ＆EMI接地ショルダーねじ群","subtitle":"24-Piece Color-Coded Chassis Precision Machine Screws, Thread-Lock Patches & EMI Bolts","category":"B37 / 実機分解アーキテクチャ・精密締結ファスナー体系","plainAnalogy":"カメラを分解すると外装のいたるところに隠れている「合計24本の極小プロ用ネジ軍団」です。場所によって長さや材質が違い、青い緩み止め樹脂や電気ノイズを逃がす銅ワッシャー付きネジまで使い分けられています。","summary":"Kolari VisionのSony A1 II・A7R VI・Canon R5 II実機分解で特徴的な、外装モノコック・トップデッキ・背面パネル・底板・側面カバーを締結する24本のJIS規格M1.4/M1.6/M2.0精密小ねじセット。振動緩み防止の青色ナイロンパッチ塗布ねじ、ステンレス耐食ねじ、および外装間電気接地用銅カラーねじを含みます。","opticsAndPhysics":["マグネシウム合金シェルは鋼鉄より熱膨張係数が大きいため、寒冷地と炎天下のヒートサイクルや超望遠連写の微小振動で普通のネジは徐々に緩みます。ねじ山に事前塗布されたマイクロカプセル型青色ナイロン緩み止めパッチが、再締結性と高い戻り止めトルクを確保します。","塗装されたマグネシウム外装同士を電気的に同電位（ファラデーケージ）へ結ぶため、要所に無塗装ステンレス／銅めっきショルダー接地ねじを配置してEMI放射漏れを封止します。"],"formula":{"expression":"T_fasten(M1.6) ≈ 0.16 N·m,   T_fasten(M2.0) ≈ 0.28 N·m  (青色ナイロン緩み止め付)","description":"部位ごとの最適締付トルクと緩み止めパッチにより、長年の過酷なフィールド携行でも外装剛性と防水性を維持。"},"nextGenInnovation":"最新のフラッグシップ機では、サービス分解時の誤組付（長いネジで内部FPCを突き破る事故）を防ぐため、ネジ長ごとに頭部黒色酸化被膜／銀色ステンレス／銅色を視覚色分けする設計が徹底されています。","specs":[{"label":"構成本数","value":"計24本（M1.4 / M1.6 / M2.0 JIS精密皿・なべ・段付きねじ）"},{"label":"緩み止め","value":"耐振青色ナイロンパッチ塗布（ヒートサイクル・落下衝撃対策）"},{"label":"電磁接地","value":"マグネシウム外装間 同電位結合用 銅／無塗装ステンレス接地ねじ"},{"label":"防錆仕様","value":"海風・汗に強いSUS304／黒色パッシベーション防食処理"}],"diagramType":"body_perimeter_screws"},{"id":"body-evf-tie-bracket","order":38,"swatchColor":"#94a3b8","groupKey":"B38_上部ペンタ部耐衝撃ロールケージ・アクセサリ荷重分散","assembledPos":[0,47.6,-7.5],"explodeOffset":[0,46,-24],"integratedExplodeOffset":[0,118,-26],"edgeOpacity":0.22,"title":"B38. ペンタ部内部鍛造ロールケージ骨格＆ホットシュー高荷重分散アーチ","subtitle":"EVF Pentaprism Internal Forged Roll-Cage Subframe & Hot-Shoe Load Distribution Arch","category":"B38 / 上部ペンタ部耐衝撃ロールケージ・アクセサリ荷重分散","plainAnalogy":"ファインダーの屋根の中に隠された「レーシングカーのロールケージのような金属のアーチ骨格」です。600g以上ある大型ストロボやXLRマイクハンドルをホットシューに載せて振り回しても、繊細なEVF光学系を押し潰さないよう左右の柱へ力を逃がします。","summary":"トップデッキのEVFペンタ部屋根（B08）とEVF光学バレル（E01〜）のわずかな隙間に内蔵された、鍛造ステンレス／マグネシウム製U字型内部ロールケージ・タイアーチ骨格。21ピンマルチインターフェースシュー（B06）直下を受け止め、外部アクセサリの曲げ・衝撃荷重をフロントモノコック左右肩柱へ直結伝達します。","opticsAndPhysics":["大型クリップオンストロボ（約600 g）やXLRデジタルオーディオハンドル装着時にホットシューへ横衝撃が加わると、薄い屋根カバーだけでは歪んで直下のEVF高精度レンズ鏡筒を圧迫します。","EVFユニットを非接触で跨ぐ高断面係数U字門型アーチ（ロールケージ）構造とすることで、ホットシュー側からの外力をEVF光学系へ一切伝えず、強固なフロント骨格へ逃がす機械分離設計です。"],"formula":{"expression":"M_shoe_max ≥ 18 N·m (600 g 大型ストロボ横衝撃)  →  EVF鏡筒たわみ δ_EVF < 5 μm","description":"ホットシューとEVF光学系を強固な内部門型アーチで構造分離し、大型アクセサリ運用時の絶対的信頼性を保証。"},"nextGenInnovation":"デジタルXLRハンドルや外部ワイヤレス送信機など、ホットシューへ装着するプロ動画機材が重量化している現代において、ペンタ部内部ロールケージはフラッグシップ機の隠れた剛性要となっています。","specs":[{"label":"構造形状","value":"EVF非接触跨ぎ U字門型鍛造ロールケージ・タイアーチ骨格"},{"label":"材質","value":"高張力ステンレス鋼 SUS304 プレス・リブ補強一体構造"},{"label":"荷重経路","value":"B06 21ピンホットシュー → 門型アーチ → フロントモノコック左右柱"},{"label":"光学保護","value":"大型ストロボ・XLRハンドル横衝撃時のEVF光軸ズレ完全防止"}],"diagramType":"body_evf_tie_bracket"},{"id":"body-main-internal-frame","order":39,"swatchColor":"#64748b","groupKey":"個別微細層_B39_マウント・センサー・三脚座・バッテリー室を統","assembledPos":[-6,0,-4],"explodeOffset":[0,0,-14],"integratedExplodeOffset":[0,0,-14],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B39. 内部マグネシウム高剛性メイン骨格フレーム MAIN FRAME ASSY（SONY X50022761）","subtitle":"Central Structural Magnesium-Aluminum Core Chassis (Sony Ref.362 MAIN FRAME ASSY)","category":"個別微細層 B39 — マウント・センサー・三脚座・バッテリー室を統合する中枢骨格","plainAnalogy":"外から見える黒いボディ外装の内側にもう1枚、建築でいう「鉄骨の柱と梁」にあたる分厚いマグネシウムの中心フレームが隠れています。マウント・シャッター・センサー・メイン基板・三脚座すべてがこの中心骨格へガッチリ固定されています。","summary":"Sony ILCE-7M4サービスマニュアル（Ref.362: X50022761 MAIN FRAME ASSY (89100)）に実在する、カメラ内部中央を貫くチクソモールドAZ91Dマグネシウム合金製メインシャーシ骨格。前面外装（CABINET F）と背面外装（CABINET REAR）の間に位置し、全主要ユニットの絶対基準面を形成します。","opticsAndPhysics":["外装シェルだけで強度を持たせると落下衝撃や三脚荷重がそのまま内部基板やセンサーへ伝わって歪みを生じます。","独立した高剛性トラスリブ構造の内部メインフレームへ「前面からマウント＆シャッター」「中央からIBISセンサー」「背面からメイン基板」「下面から三脚座ブロック」を四方結合するモノコック・コア構造により、軽量と極限剛性を両立します。"],"formula":{"expression":"比剛性 E/ρ(AZ91D) ≈ 24.8 GPa/(g/cm³),   3軸トラスリブ補強によるねじり剛性 +65%","description":"カメラ全モジュールの機械基準（Datum）を1枚の鋳造マグネシウム骨格へ集約したフラッグシップ中枢。"},"nextGenInnovation":"メインフレームの熱容量自体をメイン基板やIBISセンサーの最終ヒートシンク（放熱母材）として活用するため、随所にサーマルシート貼着用の平坦切削ボスが設けられています。","specs":[{"label":"実機品番","value":"Sony Ref.362: X50022761 MAIN FRAME ASSY (89100)"},{"label":"材質・製法","value":"チクソモールド AZ91D マグネシウム合金 ＋ 重要基準面CNC二次切削"},{"label":"結合対象","value":"マウント骨格・シャッター・IBISセンサー・メイン基板・三脚座・バッテリー室"},{"label":"設計役割","value":"光学基準面維持・衝撃分散モノコックコア・最終放熱ヒートマス"}],"diagramType":"body_main_internal_frame"},{"id":"body-side-cabinet","order":40,"swatchColor":"#1e293b","groupKey":"個別微細層_B40_左側面端子ベイ・スピーカー音響孔一体サイドシ","assembledPos":[54.8,-1,-5],"explodeOffset":[78,-6,-8],"integratedExplodeOffset":[78,-6,-8],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B40. 左側面マグネシウム・サイドキャビネット外装 SIDE CABINET ASSY（SONY X50022801）","subtitle":"Removable Left-Flank I/O Port Side Cabinet Shell (Sony Ref.8 SIDE CABINET ASSY)","category":"個別微細層 B40 — 左側面端子ベイ・スピーカー音響孔一体サイドシェル","plainAnalogy":"カメラ左側のHDMIやUSB端子が並んでいる面は、実は独立してパカッと外せる「専用サイドカバー部品」になっています。端子まわりの防水パッキン受け溝やスピーカーの音出し穴、ストラップ金具の貫通口まで一体化されています。","summary":"Sony ILCE-7M4サービスマニュアル（Ref.8: X50022801 SIDE CABINET ASSY (89100)）およびKolari Vision A7R V / A1 II実機分解で確認される、左側面（+X側）の独立着脱式サイドキャビネット外装シェル。","opticsAndPhysics":["フルサイズHDMI・USB-C・有線LAN・3.5mm音声端子という多数の開口部が集中する左側面を独立モジュール化することで、I/Oポート扉（B11）の3分割ラビリンス防水座面を高精度に一体成形できます。","Kolari Visionの分解工程でも4本の隠しねじ（ポート蓋下・スピーカー孔付近）を外すことで側面パネルを単独分離でき、破損しやすいHDMI・USB端子の交換整備性を飛躍的に高めています。"],"formula":{"expression":"締結構成: ポート蓋下隠しねじ×4 ＋ 下部ねじ×1 (外装ラビリンス嵌合段差 1.4 mm)","description":"多数の外部開口が集中する左側面を独立外装化し、防滴シール精度とポート修理性を両立。"},"nextGenInnovation":"外皮には指が触れても滑りにくい耐油シボ塗装を施し、内側にはケーブルプロテクター装着時の引き抜き力を受け止める金属インサート座が埋め込まれています。","specs":[{"label":"実機品番","value":"Sony Ref.8: X50022801 SIDE CABINET ASSY (89100)"},{"label":"収容要素","value":"3分割I/Oポート開口枠・再生スピーカー音響スリット・左ストラップ座"},{"label":"防水構造","value":"全周ラビリンス嵌合縁 ＋ B11 独立ポート蓋EPDM着座溝"},{"label":"実機出典","value":"Sony ILCE-7M4 SM Ref.8 / Kolari Vision A7R V・A1 II分解工程"}],"diagramType":"body_side_cabinet"},{"id":"body-bottom-inner-plate","order":41,"swatchColor":"#94a3b8","groupKey":"個別微細層_B41_水たまり浸水遮断ポッティング_底面二重鋼板補","assembledPos":[-6,-34.2,-1],"explodeOffset":[0,-76,-6],"integratedExplodeOffset":[0,-76,-6],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B41. 底面二重構造・ステンレスインナー補強プレート BOTTOM INNER PLATE ASSY（SONY X50022811）","subtitle":"Reinforced Inner Baseplate & Waterproof Potted Sub-Assembly (Sony Ref.14 / Ref.17)","category":"個別微細層 B41 — 水たまり浸水遮断ポッティング＆底面二重鋼板補強構造","plainAnalogy":"カメラを濡れた地面や水たまりに置いたとき、底のすき間から水が上がってくるのは昔のカメラの弱点でした。α7 IVでは底板のすぐ内側に「もう1枚の金属インナープレートと防水樹脂ポッティング」を重ねた二重底で水を完全にシャットアウトしています。","summary":"Sony ILCE-7M4サービスマニュアル（Ref.14: X50022811 BOTTOM INNER PLATE ASSY / Ref.17: A5025879A BOTTOM WP POTTING B-ASSY）に実在する、外装底板（B12）直上に配置される二重底ステンレスインナー補強板と防水ポッティング封止アセンブリ。","opticsAndPhysics":["Lensrentalsの旧世代機分解で厳しく指摘されていた「底板からの毛細管浸水（水たまり・縦位置撮影時の飛沫）」を根本解決するため、外装底板と内部基板室の間に完全ポッティング防水隔壁とインナー金属板を二重配置しています。","さらに三脚プレート締結時の圧縮荷重とバッテリー室周囲の開口剛性低下をインナープレートが面で受け止め、底面10本ねじの締結軸力を均一化します。"],"formula":{"expression":"二重底断面二次モーメント I_dual ≈ 2.8 · I_single,   防水ポッティング気密隔壁（Ref.17）","description":"二重鋼板による底面剛性2.8倍化と、防水ポッティング層による底面浸水ルートの完全遮断。"},"nextGenInnovation":"サービスマニュアルでも「Note 2: 防水ポッティング部品の再使用可否確認」が義務付けられるほど、防塵防滴の最重要キーパーツとして管理されています。","specs":[{"label":"実機品番","value":"Sony Ref.14 (X50022811 BOTTOM INNER PLATE) ＋ Ref.17 (A5025879A WP POTTING)"},{"label":"構造特徴","value":"外装底板（B12）内側の二重構造SUS補強プレート ＋ 樹脂防水ポッティング層"},{"label":"防水機能","value":"濡れた地面・三脚座周辺・バッテリー扉隙間からの毛細管浸水遮断"},{"label":"剛性役割","value":"底面10点ねじ締結面補強・大型クイックリリース雲台の面圧分散"}],"diagramType":"body_bottom_inner_plate"},{"id":"body-grip-adhesive-sheets","order":42,"swatchColor":"#d97706","groupKey":"個別微細層_B42_隠し外装ねじを密閉保護する使い捨て強粘着・耐","assembledPos":[-56,-2,12],"explodeOffset":[-56,4,34],"integratedExplodeOffset":[-56,4,34],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B42. グリップ外皮専用・2分割ダイカット強粘着シート GRIP ADHESIVE 1 & 2（SONY 502860601 / 502860701）","subtitle":"Two-Piece Precision Die-Cut Grip Adhesive Sealing Sheets (Sony Ref.11 & Ref.12)","category":"個別微細層 B42 — 隠し外装ねじを密閉保護する使い捨て強粘着・耐汗両面テープ","plainAnalogy":"右手グリップのゴムをめくると、実はボディを留める隠しネジが出てきます。そのネジ穴へ手汗や雨が入り込まないよう、複雑なグリップの形にぴったり抜かれた「2枚組の超強力・耐汗防水両面シート」でピタッと貼り付けて封をしています。","summary":"Sony ILCE-7M4サービスマニュアル（Ref.11: 502860601 GRIP ADHESIVE 1 / Ref.12: 502860701 GRIP ADHESIVE 2 — Note 1: 再使用不可・新品交換必須）に実在する、フロントグリップゴム（B03）とマグネシウム外装を密着接合する2分割ダイカット耐皮脂アクリル系強粘着シート。","opticsAndPhysics":["カメラを握る右手は体温・汗・皮脂・日焼け止め成分に常に晒されるため、一般的な両面テープでは数ヶ月で膨潤・浮き上がりが生じます。","高凝集力・耐皮脂変性アクリル粘着層を不織布／PET極薄基材へ塗布し、隠しビス頭部の窪みまで全面密着させることで、グリップ外皮のズレ防止と隠しねじ穴の防水シーリングを同時に果たします。"],"formula":{"expression":"せん断保持力 > 25 N/cm² (40℃ 耐皮脂試験),   厚み t = 0.16 mm 2分割3D曲面追従カット","description":"手汗・皮脂・高温下でのグリップ剥離を防ぎ、隠し外装ビスからの浸水を全面面シールで封止。"},"nextGenInnovation":"Kolari Visionの分解記でも必ず最初に剥がされるパーツであり、ソニー純正サービス手順では分解後の防滴性能保証のため新品シートへの張り替えが必須指定されています。","specs":[{"label":"実機品番","value":"Sony Ref.11 (502860601 GRIP ADHESIVE 1) ＋ Ref.12 (502860701 ADHESIVE 2)"},{"label":"粘着仕様","value":"耐汗・耐皮脂・耐熱変性アクリル強粘着 精密ダイカット両面シート"},{"label":"整備規定","value":"サービスマニュアル Note 1: 非再使用部品（分解時は新品交換必須）"},{"label":"保護役割","value":"B03 グリップゴム曲面強固接着 ＆ 隠しシャーシねじ孔の全面防滴シール"}],"diagramType":"body_grip_adhesive_sheets"},{"id":"body-shoe-cap-cover","order":43,"swatchColor":"#334155","groupKey":"個別微細層_B43_21ピンデジタル端子を雨塵から守る着脱キャッ","assembledPos":[0,61.2,-7.5],"explodeOffset":[0,96,-4],"integratedExplodeOffset":[0,96,-4],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B43. マルチインターフェースシュー保護キャップ SHOE CAP（SONY 443873412）＆ ねじ隠し化粧カバー","subtitle":"MI Hot-Shoe Dust Cap (Ref.9), Screw Cover Plate (Ref.329) & Waterproof FPC Gasket (Ref.324)","category":"個別微細層 B43 — 21ピンデジタル端子を雨塵から守る着脱キャップ＆内部防水構造","plainAnalogy":"カメラの頭の上のホットシューには、マイクやストロボを繋ぐ極細の21本の金端子が並んでいます。普段はめる保護キャップに加えて、金具の内側にも「ネジ隠し板」と「防水ゴムパッキン」が二重に仕込まれています。","summary":"Sony ILCE-7M4サービスマニュアルに実在する、着脱式保護キャップ（Ref.9: 443873412 SHOE CAP）、ホットシュー内部固定ねじ隠し化粧板（Ref.329: 500294602 MI SHOE SCREW COVER）、金属シェル板（Ref.327）、および21ピンFPC用防水ゴムパッキン（Ref.324: 501695501 MI SHOE FPC WP RUBBER）の精密保護セット。","opticsAndPhysics":["21ピンのマルチインターフェース端子は0.5 mmピッチの超狭小間隔で並んでいるため、雨滴や微細な金属粉が1滴入っただけで「このアクセサリーは使用できません」警告や端子電食を引き起こします。","外部のSHOE CAPが直接の雨塵を遮り、さらにシュー底面のMI SHOE FPC WP RUBBERがMIS-2006フレキシブル基板のボディ貫通口を完全密閉する二重防滴アーキテクチャです。"],"formula":{"expression":"二重防滴: 外部キャップ (Ref.9) ＋ 内部FPC圧縮ゴム (Ref.324)  →  21ピン端子ピッチ 0.5 mm 絶縁保護","description":"外部着脱キャップと内部FPC貫通防水ゴムの二段構えで、最上部ホットシューからの浸水を完全阻止。"},"nextGenInnovation":"MI SHOE SCREW COVER（Ref.329）をスライド開閉できる設計により、外部フラッシュの重い衝撃でシュー金具の4本ねじが緩んだ際も、トップデッキ全分解なしで増し締め・交換が可能です。","specs":[{"label":"実機品番","value":"Sony Ref.9 (443873412 SHOE CAP) / Ref.329 (500294602 SCREW COVER) / Ref.324 (WP RUBBER)"},{"label":"構成要素","value":"着脱防塵キャップ・SUSシェル化粧板・ねじ隠しカバー・FPC貫通防水ゴム"},{"label":"保護対象","value":"21ピン デジタルオーディオ／スマートフラッシュ通信端子（MIS-2006 FPC）"},{"label":"整備機能","value":"Ref.328 特殊頭M1.7ねじ4本へのアクセスと外観フラッシュ化の同時実現"}],"diagramType":"body_shoe_cap_cover"},{"id":"body-gyro-sensor-unit","order":44,"swatchColor":"#10b981","groupKey":"個別微細層_B44_8_5段IBISの目となる独立防振MEMSジ","assembledPos":[-38.5,-10,-8.5],"explodeOffset":[-28,-44,-22],"integratedExplodeOffset":[-28,-44,-22],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B44. 独立防振マウント・3軸角速度ジャイロ基板 GY-1018 ＆ 二重制振クッション（SONY A5009700A）","subtitle":"Vibration-Isolated 3-Axis MEMS Gyro Sub-PCB (Sony Ref.408 GY-1018) & Dual Damping Pads","category":"個別微細層 B44 — 8.5段IBISの目となる独立防振MEMSジャイロセンサー基板","plainAnalogy":"手ブレ補正を動かす「三半規管（ジャイロセンサー）」の専用ミニ基板です。シャッターの激しい振動で目が回ってしまわないよう、バッテリー室の横の静かな場所に「上下2枚の特殊な防振スポンジ（クッション）」でふんわり挟んで浮かせてあります。","summary":"Sony ILCE-7M4サービスマニュアル・BATTERY HOLDER SECTION（Ref.408: A5009700A GY-1018 BOARD / Ref.407: 469214901 CUSHION (799) GYRO / Ref.409: 501138301 CUSHION (G 850) GYRO）に実在する、メイン基板から完全分離された防振フローティング3軸MEMS角速度ジャイロサブ基板ユニット。","opticsAndPhysics":["8.5段分の5軸ボディ内手ブレ補正（IBIS）および動画アクティブ手ブレ補正では、0.002°/sレベルの極微細な手ブレ角速度をリアルタイム検出する必要があります。","もしジャイロICをメイン基板へ直付けすると、高周波のシャッター衝撃（1〜5 kHz）や冷却・レンズAF振動がMEMS振動子の共振周波数（約20 kHz）と干渉して出力が飽和します。専用の二重制振クッション（Ref.407/409）でメカニカルローパスフィルタ（遮断約250 Hz）を形成し、人間の手ブレ帯域（0.5〜20 Hz）だけを純粋に抽出します。"],"formula":{"expression":"f_c(防振クッション) ≈ 250 Hz ≪ f_shutter(2 kHz)   ⇒   手ブレ 0.5–20 Hz 透過率 100%・衝撃 −26 dB","description":"二重制振クッションによる機械的ローパスフィルタが、シャッター衝撃下でも正確な手ブレ角速度を抽出。"},"nextGenInnovation":"カメラ重心近くのバッテリーホルダー骨格へ独立配置することで、発熱源のメインISP（70℃超）からの熱ドリフト（ジャイロゼロ点温度変動）も劇的に低減しています。","specs":[{"label":"実機品番","value":"Sony Ref.408 (A5009700A GY-1018 BOARD) ＋ Ref.407 / Ref.409 GYRO CUSHION"},{"label":"検出性能","value":"3軸超低ノイズMEMS角速度ジャイロ（ノイズ密度 < 0.003 °/s/√Hz）"},{"label":"防振機構","value":"上下二重粘弾性防振フォーム（メカニカルLPF遮断約 250 Hz）"},{"label":"熱的利点","value":"発熱するメイン基板から物理隔離し、長回し撮影時のゼロ点ドリフト抑制"}],"diagramType":"body_gyro_sensor_unit"},{"id":"body-still-movie-sq-lever","order":45,"swatchColor":"#dc2626","groupKey":"個別微細層_B45_7_IV象徴の2段同軸ハイブリッド切替ダイヤ","assembledPos":[-24,38.2,-6],"explodeOffset":[-24,82,-12],"integratedExplodeOffset":[-24,82,-12],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B45. 静止画／動画／S&Q 独立切替ダイヤル（2段同軸リング＆鋼球クリック機構）","subtitle":"Concentric Still/Movie/S&Q Mode Ring, Steel-Ball Detent Holder & Seal (Sony Ref.319–322)","category":"個別微細層 B45 — α7 IV象徴の2段同軸ハイブリッド切替ダイヤル内部構造","plainAnalogy":"α7 IVから搭載された「写真・動画・スローモーション」を一瞬で切り替える、モードダイヤルのすぐ下にあるレバー付きリングです。中には「小さな鉄球と押しバネ、防水スポンジ」が仕込まれ、親指1本でパチッと確実な手応えで切り替わります。","summary":"Sony ILCE-7M4サービスマニュアル・CABINET TOP SECTION-2（Ref.319: 503009301 SV DIAL SPRING / Ref.320: 500417201 AM DIAL BALL HOLDER / Ref.321: 767111211 BALL, STEEL / Ref.322: 502861101 SV WP CUSHION B / Ref.310: SV DIAL FPC COVER）に実在する、モードダイヤル（MD DIAL BLOCK）と同軸2段構成の静止画／動画／S&Q切替メカアセンブリ。","opticsAndPhysics":["1つの回転軸の上段に「PASMモードダイヤル」、下段に「Still / Movie / S&Q 3ポジション切替リング」を同心円状に重ねることで、省スペースのまま写真メニューと動画メニューを完全独立切替できます。","AM DIAL BALL HOLDERに収めた焼入れ鋼球（Ref.321）をSV DIAL SPRING（Ref.319）で3箇所のV字ディテント溝へ押し付けることで、手袋越しでも確実な3段クリック感と誤操作防止ロックを実現します。"],"formula":{"expression":"T_detent = F_spring · r_ball · tan(α_V) ≈ 18 mN·m  (3段鋼球クリック ＋ SV WP CUSHION防水)","description":"同軸2段ダイヤルの下段リングに独立した鋼球クリックと防水クッションを収めた精密時計的実装。"},"nextGenInnovation":"α7 IVで初採用され、後のα7R V・α9 III・α1 IIへ受け継がれた現代ハイブリッドミラーレス操作系の象徴的メカニズムです。","specs":[{"label":"実機品番","value":"Sony Ref.319 (SV DIAL SPRING) / Ref.320 (BALL HOLDER) / Ref.321 (STEEL BALL) / Ref.322 (WP CUSHION)"},{"label":"機構方式","value":"モードダイヤル同軸下段 3ポジション切替リング（Still / Movie / S&Q）"},{"label":"節度構造","value":"鋼球＋コイルバネV溝クリックディテント ＆ 誤操作防止解除レバー"},{"label":"防水対策","value":"SV WP CUSHION B（Ref.322）＋ SV DIAL FPC COVER（Ref.310）二重封止"}],"diagramType":"body_still_movie_sq_lever"},{"id":"body-strap-triangles","order":46,"swatchColor":"#cbd5e1","groupKey":"個別微細層_B46_動画撮影時のカチャカチャ金属音を封じる静音三","assembledPos":[0,23,-1],"explodeOffset":[0,44,52],"integratedExplodeOffset":[0,44,52],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B46. 静音樹脂ブッシュ付・三角ストラップリング EYELET TRIANGLE ＆ 傷防止ホルダー（SONY 501695901 / 448787501）","subtitle":"Silent-Damped Triangular Strap Rings & Protective POM Clip Holders (Sony Ref.314 / Ref.315)","category":"個別微細層 B46 — 動画撮影時のカチャカチャ金属音を封じる静音三角環＆カバー","plainAnalogy":"ネックストラップを通す左右の「三角形の金属リング」です。ただの金具に見えますが、動画撮影中にボディへ当たって「カチャカチャ」とマイクに雑音が入らないよう、黒い樹脂製の傷防止＆静音ホルダーでしっかり抱え込んでいます。","summary":"Sony ILCE-7M4サービスマニュアル（Ref.315: 501695901 EYELET TRIANGLE / Ref.314: 448787501 HOLDER, EYELET TRIANGLE / Ref.316–317: EYELET G & L / Ref.261: EYELET PLATE G / Ref.313: TOP CONNECT PLATE L）に実在する、左右外装吊り金具（アイレット）に装着される高張力ステンレス三角リングと静音・傷防止POM樹脂カバー一式。","opticsAndPhysics":["70-200mm F2.8等の大口径ズームを装着した2 kg超のシステムを首・肩掛けで歩行すると、ストラップ吊り金具には動的衝撃荷重（静止重量の4〜5倍＝約100 N超）が繰り返し加わります。","高張力SUS304線材を閉ループ三角成形した三角環へ、さらに弾性POM樹脂ホルダー（Ref.314）を嵌合させることで、ストラップ未使用時やジンバル動画撮影時の「金属リング共振・カチャ音」とマグネシウム塗装の擦り傷を同時に防止します。"],"formula":{"expression":"F_break(SUS三角環) > 450 N (安全率 > 15),   POM静音ブッシュにより動画マイク混入打音 −18 dB","description":"高強度ステンレス吊り環と静音樹脂ホルダーの組合せで、耐荷重安全性と動画静音性を両立。"},"nextGenInnovation":"α7 IVでは左側の吊り金具をボディ前方寄り、右側を後方寄りの最適重心位置に配し、斜め掛け携行時にレンズが自然に下を向いて安定するエルゴノミクス配置を採用しています。","specs":[{"label":"実機品番","value":"Sony Ref.315 (501695901 EYELET TRIANGLE) ＋ Ref.314 (448787501 HOLDER) ＋ Ref.316/317"},{"label":"環体材質","value":"高張力SUS304ステンレス三角リング（線径 1.4 mm・破断荷重 > 450 N）"},{"label":"静音構造","value":"黒色POM樹脂 傷防止＆動画カチャ音抑制スナップホルダー"},{"label":"内部連携","value":"B24 鍛造ステンレス内部アンカー板（EYELET PLATE G / TOP CONNECT PLATE L）へ直結"}],"diagramType":"body_strap_triangles"},{"id":"body-dc-coupler-flap","order":47,"swatchColor":"#475569","groupKey":"個別微細層_B47_扉を閉じたまま外部電源直結できる極小ヒンジ付","assembledPos":[-54.5,-37.2,16.5],"explodeOffset":[-78,-68,36],"integratedExplodeOffset":[-78,-68,36],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B47. バッテリー扉内蔵・外部AC電源（DCカプラー）防水ゴムケーブル通し口","subtitle":"Battery-Hatch Integrated EPDM Dummy-Battery DC-Coupler Cable Pass-Through Flap","category":"個別微細層 B47 — 扉を閉じたまま外部電源直結できる極小ヒンジ付きゴムフラップ","plainAnalogy":"バッテリーのフタの端に付いている、爪で開けられる小さなゴムのフタです。スタジオ撮影やタイムラプスで「ダミーバッテリー（AC電源）」を使うとき、バッテリーのフタをしっかり閉めたままコードだけを外へ引き出せる便利な秘密の小窓です。","summary":"バッテリー扉（BT LID ASSY / B02）の前面縁に一体成形・組込みされた、外部ACアダプター／Vマウント用ダミーバッテリー（DCカプラー）ケーブル引き出し専用の弾性EPDM防水ゴムフラップと密着リップ座面。","opticsAndPhysics":["スタジオでのテザー撮影や長時間ライブ配信でダミーバッテリーを挿入した際、バッテリー扉が開いたままだと電源インターロックスイッチが安全遮断してカメラが起動しません。","この専用ゴムフラップをめくって直径3.2 mmのDCケーブルを逃がしながら扉を完全ロックでき、通常バッテリー運用時は二段リップ形状のEPDMゴムが底面からのホコリ・水滴の侵入を塞ぎます。"],"formula":{"expression":"ケーブル通過径 φ3.2 mm (扉完全ロック状態維持),   通常時 2段EPDMリップ圧着封止","description":"長回しスタジオ外部給電の利便性と、屋外フィールド撮影時のバッテリー室防塵防滴を両立。"},"nextGenInnovation":"Lensrentalsの防滴評価で弱点とされやすかったDCフラップ周囲の隙間を、最新のα7 IV / α1 II世代では扉内周ガスケットと連続した段差シールへ改良しています。","specs":[{"label":"部品機能","value":"ダミーバッテリー（NP-FZ100 DCカプラー）外部電源ケーブル引き出し専用小窓"},{"label":"材質構造","value":"一体ヒンジ付 高耐久EPDMエラストマー（硬度 55 Shore A・二段防水リップ）"},{"label":"配置位置","value":"バッテリー扉（BT LID ASSY）前面端・扉ロック状態のまま配線可能"},{"label":"安全連携","value":"バッテリー扉開閉検知マイクロスイッチを作動させたまま連続外部給電"}],"diagramType":"body_dc_coupler_flap"},{"id":"body-muffle-cushions","order":48,"swatchColor":"#334155","groupKey":"個別微細層_B48_背面キャビネット内壁に貼られた実機シャッター","assembledPos":[-6,4,-28],"explodeOffset":[22,18,-58],"integratedExplodeOffset":[22,18,-58],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B48. 背面シャッター静音吸音フォーム REAR MUFFLE CUSHION A & B（SONY 502863201 / 502863301）","subtitle":"Interior Acoustic Shutter-Damping Foam Pads (Sony Ref.76 / Ref.59 REAR MUFFLE CUSHION A/B)","category":"個別微細層 B48 — 背面キャビネット内壁に貼られた実機シャッター消音・調音スポンジ","plainAnalogy":"カメラの背中カバーを裏返すと、内側に黒いスポンジが2カ所貼られています。録音スタジオの吸音材と同じ仕組みで、カメラの中で跳ね返るシャッターの金属音を吸い取り、耳に心地よく静かな「コトッ」という高級音に変えています。","summary":"Sony ILCE-7M4サービスマニュアル・CABINET REAR SECTION-1（Ref.76: 502863201 REAR MUFFLE CUSHION A / Ref.59: 502863301 REAR MUFFLE CUSHION B）に実在する、背面マグネシウム外装内壁に貼着された連続気泡ポリウレタン音響吸音・制振マッフルフォーム2枚組。","opticsAndPhysics":["金属製モノコックボディ内部は音響的に共鳴箱（ヘルムホルツ空洞）になりやすく、シャッター幕やチャージモーターの駆動音が背面パネルから撮影者の耳元（EVF接眼位置）へ直接放射されます。","連続気泡（オープンセル）構造の吸音フォーム内部を音波が通過する際の粘性空気摩擦によって、特に耳障りな2 kHz〜8 kHz帯の金属響きを効率よく熱減衰させます。"],"formula":{"expression":"吸音率 α(2–8 kHz) ≈ 0.55–0.78,   接眼部シャッターピーク音圧 −4.2 dBA 低減","description":"内部空間の定在波と背面パネル膜振動を吸収し、野生動物・ブライダル撮影に最適な静音性を実現。"},"nextGenInnovation":"音響吸収だけでなく、背面パネルとメイン基板RFシールド間の微小な隙間ガタつき（ビビリ音）を抑える弾性スペーサーの役割も兼ねています。","specs":[{"label":"実機品番","value":"Sony Ref.76 (502863201 REAR MUFFLE CUSHION A) ＋ Ref.59 (502863301 CUSHION B)"},{"label":"音響材質","value":"難燃性 連続気泡（オープンセル）ポリウレタン吸音フォーム（t = 2.0 mm）"},{"label":"減衰帯域","value":"2 kHz〜8 kHz シャッター高周波金属残響・ギヤ駆動音吸収"},{"label":"貼付位置","value":"CABINET REAR（背面外装）内壁 右側シャッター／基板対向面"}],"diagramType":"body_muffle_cushions"},{"id":"body-card-access-led-pipe","order":49,"swatchColor":"#ef4444","groupKey":"個別微細層_B49_カード扉ヒンジ軸・ばね・接地シート_書込中警","assembledPos":[-62.5,-21,-24],"explodeOffset":[-88,-28,-42],"integratedExplodeOffset":[-88,-28,-42],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B49. メモリーカード書込アクセスLED導光プリズム ＆ 扉電磁接地シート（SONY 502862801）","subtitle":"CFexpress/SD Access LED Optical Light-Pipe, Media-Lid Ground Sheet & Hinge Shaft (Ref.75/120/121)","category":"個別微細層 B49 — カード扉ヒンジ軸・ばね・接地シート＆書込中警告ライトパイプ","plainAnalogy":"写真を連写したあとに右下で赤くチカチカ光る「書き込み中ランプ」は、基板のLEDの光を透明なアクリル棒（ライトパイプ）で外まで運んでいます。さらにカード扉の金属軸・跳ね上げバネ・静電気逃がしシートまでセットになった精密パーツ群です。","summary":"Sony ILCE-7M4サービスマニュアル・CABINET REAR SECTION-1/2（Ref.75: 502862801 REAR MEDIA LID GND SHEET / Ref.60: MEDIA LID BASE / Ref.120: 501035811 MEDIA LID SHAFT / Ref.121: 501035701 MEDIA LID ROTATION SPRING）およびカード書き込みアクセスLED用透明ポリカーボネート導光ライトパイプ一式。","opticsAndPhysics":["CFexpress Type A/Bの超高速書き込み中にカードを引き抜くとファイルシステムが破損するため、基板上SMD赤色LEDの光を全反射（TIR）透明ライトパイプで背面右下端の防水窓へ導き、データ書込状態を視覚警告します。","REAR MEDIA LID GND SHEET（Ref.75）は、開閉するカード扉と本体シャシーを常時低インピーダンス接地し、カード交換時に指先から飛び込む静電気（ESD）でCFexpress/SDスロットのPCIe Gen4高速レーンが破壊されるのを防ぎます。"],"formula":{"expression":"全反射臨界角 θ_c = arcsin(1/1.58) ≈ 39.3° (PC導光棒),   扉ESD接地 < 0.2 Ω (Ref.75)","description":"全反射ライトパイプによる確実な書込視認性と、導電シート・ステンレス蝶番軸によるESD防護を一体化。"},"nextGenInnovation":"扉回転軸（Ref.120）と跳ね上げトーションスプリング（Ref.121）の精密なトルク調整により、スライドロック解除と同時に扉が節度よく滑らかにポップオープンします。","specs":[{"label":"実機品番","value":"Sony Ref.75 (MEDIA LID GND SHEET) / Ref.120 (SHAFT) / Ref.121 (ROTATION SPRING) / Ref.60"},{"label":"光学要素","value":"高透過ポリカーボネート 全反射アクセスLED導光ライトパイプ"},{"label":"機構部品","value":"SUS304 カード扉ヒンジシャフト ＋ 開扉アシストトーションばね"},{"label":"静電防護","value":"導電クロス接地シート（カード挿抜時のPCIe/SDインターフェースESD保護）"}],"diagramType":"body_card_access_led_pipe"},{"id":"body-rear-button-retainers","order":50,"swatchColor":"#64748b","groupKey":"個別微細層_B50_AF_ON_AEL_MENU_再生ボタンを個","assembledPos":[-42,2,-31.5],"explodeOffset":[-56,2,-64],"integratedExplodeOffset":[-56,2,-64],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B50. 背面ボタン群分割押さえプレート L/R ＆ 独立防水シリコーンラバー群（SONY 502794101 / 502794001）","subtitle":"Split Rear Button Retainer Plates L/R, Joystick Holder & Molded Silicone Boots (Ref.65–112)","category":"個別微細層 B50 — AF-ON/AEL/MENU/再生ボタンを個別防水密閉する多層サンドイッチ","plainAnalogy":"背面のMENU・AF-ON・再生・ゴミ箱などのボタンは、ただプラスチックのボタンが並んでいるのではありません。裏側から「ボタンごとの防水ゴムブーツ」を被せ、さらに左右2枚の「ステンレス押さえ鉄板」でギュッと締め付けて雨を1滴も通しません。","summary":"Sony ILCE-7M4サービスマニュアル・CABINET REAR SECTION-1/2（Ref.101: 502794101 REAR BUTTON PLATE L / Ref.104: 502794001 REAR BUTTON PLATE R / Ref.106: C1 AF AEL RUBBER / Ref.110: C3 MENU RUBBER / Ref.65: PLAYBACK DELETE RUBBER / Ref.68: C1 FN RUBBER / Ref.70・72: JOY RETAINER & HOLDER PLATE）の実機多層ボタン保持・防水アセンブリ。","opticsAndPhysics":["Lensrentalsのソニーα背面分解でも高く評価されている「完全ラバーシール式プッシュボタン構造」の中核です。外装樹脂キートップの背後に一体成形シリコーンゴムブーツが嵌合し、背面パネル穴を360°加硫密着シールします。","その背後を左右分割のステンレス製リテーナープレート（L/R）とジョイスティック保持板が計7本のタッピングねじで強固に押さえ込むことで、10万回押下してもボタンが沈み込んだり防水パッキンが浮いたりしません。"],"formula":{"expression":"4層サンドイッチ: キートップ → 独立シリコーン防水ブーツ → SUS押さえ板L/R → スナップドームFPC","description":"背面ボタン1個ごとに独立した防水ゴム隔壁と金属リテーナーを備える鉄壁のフィールド耐候設計。"},"nextGenInnovation":"左右のボタン群（MENU/C3側とAF-ON/AEL/C1/Fn/再生/削除側）を独立フレキ（KY-1035 / RS-1024 / SW-1041 / JS-1012）と分割押さえ板で構成し、高頻度使用ボタンの部分修理も容易にしています。","specs":[{"label":"実機品番","value":"Sony Ref.101 (PLATE L) / Ref.104 (PLATE R) / Ref.70・72 (JOY PLATES) / Ref.65・68・106・110"},{"label":"防水要素","value":"各ボタン群独立成形 液状シリコーン防水ラバーブーツ（4系統ブロック）"},{"label":"保持構造","value":"SUS304 プレス成形ボタン押さえリテーナープレート L/R ＋ ジョイスティック枠"},{"label":"実機出典","value":"Sony ILCE-7M4 SM CABINET REAR 1 & 2 / Lensrentals 防滴分解評価準拠"}],"diagramType":"body_rear_button_retainers"},{"id":"body-top-rec-c2-subassy","order":51,"swatchColor":"#dc2626","groupKey":"個別微細層_B51_雨滴が直撃するカメラ上面REC・カスタムボタ","assembledPos":[-32,38.5,-14],"explodeOffset":[-44,78,-28],"integratedExplodeOffset":[-44,78,-28],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B51. トップデッキ独立REC／C2ボタンポッド・遮光シート＆防水クッション（SONY 502790901 / 503673201）","subtitle":"Top-Deck REC/C2 Custom Button Plate, Silicone Boot, Shade Sheet & WP Cushion (Ref.264–269)","category":"個別微細層 B51 — 雨滴が直撃するカメラ上面REC・カスタムボタン専用防水ポッド","plainAnalogy":"雨の中でカメラを構えると、いちばん最初に雨が降り注ぐのがカメラの上面です。赤い動画録画（REC）ボタンとC2ボタンの裏側には、専用の「防水ゴムカバー・金属押さえ板・防水クッション・遮光シート」が4重に重ねて守られています。","summary":"Sony ILCE-7M4サービスマニュアル・CABINET TOP SECTION-1（Ref.264: 502790901 CUSTOM BUTTON PLATE / Ref.265: 503673201 RL FPC SHADE SHEET / Ref.266: CUSTOM BUTTON RUBBER / Ref.267: REC BUTTON / Ref.268: C2 BUTTON / Ref.269: TOP WP CUSHION F3 / Ref.251: RL FPC BASE）に実在するトップデッキ右肩ボタン防水サブアセンブリ。","opticsAndPhysics":["α7 IVでは動画録画RECボタンをシャッターボタン直後の上面一等地へ大型配置したため、上面への降雨直撃に対する耐水性が極めて重要になります。","REC／C2ボタンの下をCUSTOM BUTTON RUBBER（Ref.266）とTOP WP CUSHION F3（Ref.269）が二重密閉し、さらにRL FPC BASEと金属CUSTOM BUTTON PLATEがレリーズ基板（RL-1071）へ確実なクリック反力を伝えます。"],"formula":{"expression":"上面直撃降雨封止: ラバーブーツ (Ref.266) ＋ TOP WP CUSHION F3 (Ref.269) ＋ 押さえ板 (Ref.264)","description":"最重要操作系であるREC/C2ボタンを独立防水ポッド化し、上面降雨からの基板浸水を完全防御。"},"nextGenInnovation":"RL FPC SHADE SHEET（Ref.265）がトップデッキ内部の隙間からセンサー室側へ光や静電ノイズが漏れ込むのも同時に遮断しています。","specs":[{"label":"実機品番","value":"Sony Ref.264 (BUTTON PLATE) / Ref.265 (SHADE SHEET) / Ref.266 (RUBBER) / Ref.267–269"},{"label":"操作キートップ","value":"アルマイト赤リング付 REC録画ボタン ＋ C2カスタムボタン"},{"label":"防水・遮光","value":"一体成型シリコーンラバー ＋ TOP WP CUSHION F3 ＋ RL FPC遮光シート"},{"label":"連携基板","value":"Ref.257 RL-1071 トップ制御フレキシブル基板 ＆ Ref.251 RL FPC BASE"}],"diagramType":"body_top_rec_c2_subassy"},{"id":"body-focal-plane-badge","order":52,"swatchColor":"#d95b26","groupKey":"個別微細層_B52_イメージセンサーの厳密な位置_z_0_0_m","assembledPos":[24,38.8,0],"explodeOffset":[34,76,18],"integratedExplodeOffset":[34,76,18],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B52. 撮像面位置基準マーク（Φマーク）彫刻インレイ ＆ モデル名バッジプレート","subtitle":"Precision Focal-Plane Distance Index Mark (Φ at z = 0.0 mm) & Metallic Model Crest Badge","category":"個別微細層 B52 — イメージセンサーの厳密な位置（z = 0.0 mm）を示す光学測量基準","plainAnalogy":"カメラの肩のところに小さく刻まれた「丸に横線（Φ）」のマークです。実はこの横線の真下が「イメージセンサーの表面（z = 0.00 mm）」と寸分違わず一致しており、映画の撮影現場でメジャーを当ててピント距離を測るための本物の測量基準点です。","summary":"フルサイズ撮像素子のシリコン受光面（光学座標 z = 0.00 mm）と幾何学的に厳密一致するトップデッキ左肩位置へ刻設された撮像面位置基準マーク（Φインレイ）および、ステンレス／アルミ削り出しのモデルエンブレムバッジプレート。","opticsAndPhysics":["レンズの距離目盛や最短撮影距離（MOD）はレンズ先端からではなく、このΦマークが示す「撮像面（Focal Plane）」から被写体までの距離として定義されています。","映画用フォローフォーカス運用や等倍マクロ撮影（倍率1:1時、被写体〜撮像面距離は焦点距離の4倍＝4f）では、フォーカスプラーがこのΦマークへ巻き尺の0点を当ててミリ単位で焦点距離を実測します。"],"formula":{"expression":"z_Φ_mark = z_sensor_surface = 0.00 ± 0.10 mm   (フランジ前面まで正確に +18.00 mm)","description":"カメラ内部に隠れた撮像素子の正確な位置を外装トップデッキ上へ正確に写し取った光学測量基準。"},"nextGenInnovation":"Kolari VisionのCanon R5 Mark II分解で明らかになった通り、現代のフラッグシップ機ではモデルエンブレムプレートの下に隠し分解ねじを配置して外装の美観と剛性を両立する設計も広く用いられています。","specs":[{"label":"位置精度","value":"撮像素子受光面 z = 0.00 mm 基準ライン（マウントフランジから後方 18.00 mm）"},{"label":"用途分野","value":"シネマ撮影メジャー測距（フォーカスプラー基準）・マクロ撮影倍率計算"},{"label":"加工仕様","value":"レーザー精密彫刻＋耐摩耗ホワイトエポキシ充填 Φマーク＆金属バッジ"},{"label":"構造役割","value":"エンブレムプレート下部の隠しトップデッキサービスねじ保護カバー兼務"}],"diagramType":"body_focal_plane_badge"},{"id":"body-speaker-emi-insulator","order":53,"swatchColor":"#ca8a04","groupKey":"個別微細層_B53_高電圧基板とマグネシウム金属外装の短絡を防ぐ","assembledPos":[36,-24,-24],"explodeOffset":[64,-46,-42],"integratedExplodeOffset":[64,-46,-42],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B53. スピーカー電磁接地シート ＆ 背面電気絶縁マイラーシート（SONY 501696001 / 500463101）","subtitle":"Speaker EMI Ground Sheet & Flame-Retardant Polycarbonate Insulation Sheets (Ref.414/415/356/361)","category":"個別微細層 B53 — 高電圧基板とマグネシウム金属外装の短絡を防ぐ絶縁＆接地層","plainAnalogy":"カメラの中は金属のフレームと電子基板が髪の毛ほどのすき間でギュウギュウに詰まっています。もし基板が金属ボディに触れたら一瞬でショートして壊れてしまうため、要所に「黒い絶縁マイラーシート」と「スピーカー用導電接地シート」を貼り分けて守っています。","summary":"Sony ILCE-7M4サービスマニュアル（Ref.414: 501696001 SPEAKER GND SHEET / Ref.415: 500463101 SP INSULATION SHEET / Ref.356: 502992401 INSULATING SHEET A / Ref.361: 502992501 INSULATING SHEET B）に実在する、難燃性ポリカーボネート電気絶縁シート群およびスピーカー用導電ファブリック接地シート。","opticsAndPhysics":["薄型高密度実装のミラーレス機では、メイン基板裏面のSMDコンデンサ・フラッシュ高圧回路・スピーカーマグネット背面とマグネシウム導電骨格との空間距離がわずか0.3 mm未満の箇所が多数あります。","UL94 V-0難燃グレードの厚さ0.15 mmポリカーボネート／マイラー絶縁シート（絶縁破壊電圧 > 6 kV）を精密ダイカットして挟み込み、同時にスピーカー枠には導電ニッケル銅繊維シート（Ref.414）を貼って不要輻射を逃がします。"],"formula":{"expression":"絶縁耐圧 V_bd > 6,000 V (t = 0.15 mm 難燃PC),   導電接地シート R_sq < 0.05 Ω/sq","description":"絶縁すべき部位（電源・信号基板）と接地すべき部位（スピーカー外殻）を極薄シートで緻密に区画。"},"nextGenInnovation":"万が一の落下変形で金属フレームが0.2 mm内側に凹んでも基板ショート発火を阻止する、安全規格（IEC 62368-1）上不可欠なセーフティクリティカル絶縁層です。","specs":[{"label":"実機品番","value":"Sony Ref.414 (SPEAKER GND SHEET) / Ref.415 (SP INSULATION) / Ref.356・361 (INSULATING A/B)"},{"label":"絶縁シート","value":"UL94 V-0 難燃黒色ポリカーボネート／マイラーフィルム（t = 0.15 mm）"},{"label":"接地シート","value":"ニッケル銅めっきポリエステル導電クロス（スピーカー磁気枠EMI接地）"},{"label":"安全性能","value":"落下衝撃による基板〜金属シャーシ間ショート・電食防止（耐圧 > 6 kV）"}],"diagramType":"body_speaker_emi_insulator"},{"id":"body-mag-field-cut-plate","order":54,"swatchColor":"#94a3b8","groupKey":"個別微細層_B54_IBIS強磁力ネオジム磁石の漏れ磁束を遮る専","assembledPos":[2,-4,-26.5],"explodeOffset":[28,-22,-64],"integratedExplodeOffset":[28,-22,-64],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B54. 磁気遮蔽パーマロイ・フィールドカットプレート MAGNETIC FIELD CUT PLATE（SONY 502789501）","subtitle":"Ferromagnetic Flux-Diverting Shield Plate (Sony Ref.352 MAGNETIC FIELD CUT PLATE 891)","category":"個別微細層 B54 — IBIS強磁力ネオジム磁石の漏れ磁束を遮る専用磁気シールド板","plainAnalogy":"手ブレ補正（IBIS）とバリアングル液晶には、指を挟むと痛いほど強力なネオジム磁石が使われています。その強力な磁力がすぐ後ろのメイン基板や磁気センサーへ悪さをして誤動作させないよう、あいだに挟んだ「磁力線を吸い取って逃がす鉄の盾」です。","summary":"Sony ILCE-7M4サービスマニュアル・MAIN BOARD SECTION（Ref.352: 502789501 MAGNETIC FIELD CUT PLATE (891)）に実在する、メイン基板とIBIS強磁力磁石／背面LCD開閉検知磁石の間に配置される高透磁率軟磁性ステンレス／パーマロイ製磁気遮蔽プレート。","opticsAndPhysics":["アルミニウムやマグネシウム合金は常磁性体（比透磁率 μ_r ≈ 1）のため、ネオジム磁石の直流（DC）強磁界をまったく遮蔽できず素通りさせてしまいます。","比透磁率 μ_r > 2,000 を持つ強磁性磁気フィールドカット板を間に配置することで、IBIS用N52磁石やLCDヒンジ磁石の漏れ磁束を板内部へバイパス閉路化し、メイン基板上の電源インダクタ磁気飽和やLCD開閉ホールICの誤検知を完全防止します。"],"formula":{"expression":"μ_r(磁気遮蔽鋼) > 2,000 ≫ μ_r(Mg合金) ≈ 1.0   →   漏れ直流磁束密度 B_leak −85% 削減","description":"マグネシウム外装では止められない直流強磁界を、専用強磁性シールド板で磁気バイパス遮断。"},"nextGenInnovation":"薄型化が進むミラーレス機で「強力化する8.5段IBIS磁石」と「背面バリアングルLCDの磁気開閉センサー」が数ミリ距離で共存できるのは、この磁界カットプレートのおかげです。","specs":[{"label":"実機品番","value":"Sony Ref.352: 502789501 MAGNETIC FIELD CUT PLATE (891)"},{"label":"遮蔽材質","value":"高透磁率軟磁性電磁鋼板／パーマロイ合金（t = 0.4 mm・μ_r > 2,000）"},{"label":"隔離対象","value":"IBIS N52強力磁石・LCDヒンジ磁石 ⇔ メイン基板インダクタ＆ホールセンサー"},{"label":"磁気効果","value":"直流（DC）漏れ磁束密度を 85% 以上バイパス低減（誤検知・飽和防止）"}],"diagramType":"body_mag_field_cut_plate"},{"id":"body-hdmi-light-shield","order":55,"swatchColor":"#0ea5e9","groupKey":"個別微細層_B55_極太シネマHDMIケーブルのこじり破損_光漏","assembledPos":[51.2,6,-14],"explodeOffset":[76,26,-24],"integratedExplodeOffset":[76,26,-24],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B55. フルサイズHDMI開口 遮光シート ＆ デュアル保持ブラケット HOLDER HDMI A/B（SONY 502078101 / 501028101）","subtitle":"Full-Size Type-A HDMI Twin Clamp Brackets (HOLDER HDMI A/B), Jack Plate & Light Shield (Ref.463–467)","category":"個別微細層 B55 — 極太シネマHDMIケーブルのこじり破損＆光漏れを防ぐ二重鋼鉄クランプ","plainAnalogy":"動画撮影で使うフルサイズHDMIケーブルは太くて重いため、引っ掛けると端子のハンダが基板ごと引きちぎれるのが大事故の元でした。α7 IVではHDMI端子の上下を「2枚の鋼鉄クランプ（AとB）」でガッチリ挟んで骨格へ固定し、さらに遮光シートで光漏れも止めています。","summary":"Sony ILCE-7M4サービスマニュアル・MECHA DEVICE SECTION（Ref.463: 502078101 HDMI LIGHT SHIELD SHEET / Ref.465: 501028201 HOLDER HDMI B / Ref.467: 501028101 HOLDER HDMI A / Ref.466: HD-1009 FLEXIBLE BOARD / Ref.353: 502789401 JACK PLATE）に実在する、フルサイズType-A HDMI独立モジュール強固保持・遮光システム。","opticsAndPhysics":["Lensrentalsの修理統計で「メイン基板交換の最大原因はHDMI端子の物理引きちぎり破損」と報告されています。α7 IVではHDMI端子をメイン基板から切り離して専用フレキ（HD-1009）化し、金属クランプHOLDER A/BとJACK PLATEで直接ボディ骨格へ挟み込み固定しています。","さらにHDMIの大きな長方形開口はセンサー室の真横に位置するため、HDMI LIGHT SHIELD SHEET（Ref.463）でポート外周からの長時間露光時光漏れを完全封止しています。"],"formula":{"expression":"F_wrench_HDMI > 85 N (HOLDER A+B 鋼鉄挟持固定),   独立HD-1009フレキでメイン基板破損率 −92%","description":"外部モニター用太径HDMIケーブルの曲げモーメントを骨格で直接受け止め、光漏れも同時遮断。"},"nextGenInnovation":"万が一三脚転倒でHDMI端子が破損しても、高額なメイン基板ではなく安価なHD-1009フレキとホルダーのみ交換できるプロ現場重視のモジュラー設計です。","specs":[{"label":"実機品番","value":"Sony Ref.467 (HOLDER HDMI A) / Ref.465 (HOLDER B) / Ref.463 (LIGHT SHIELD) / Ref.353 (JACK PLATE)"},{"label":"機械保護","value":"SUS304 デュアル挟持クランプ A/B ＋ JACK PLATE による骨格直接締結"},{"label":"遮光機能","value":"フルサイズType-A大開口周囲からの撮像室光漏れ防止遮光シート"},{"label":"整備性","value":"Ref.466 HD-1009 独立フレキ構成（メイン基板非損傷モジュラー交換対応）"}],"diagramType":"body_hdmi_light_shield"},{"id":"body-vg-fpc-retainer","order":56,"swatchColor":"#ea580c","groupKey":"個別微細層_B56_バッテリー2本並列大電流_縦位置操作信号を運","assembledPos":[-44,-24,-8],"explodeOffset":[-44,-76,-26],"integratedExplodeOffset":[-44,-76,-26],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B56. 縦位置グリップ接続フレキ VG-1007 ＆ ステンレス押さえ板 VG FPC FIX PLATE（SONY 198422211 / 500371201）","subtitle":"Vertical-Grip High-Current Bus FPC (Sony Ref.404 VG-1007) & Stainless Fix Plate (Ref.403)","category":"個別微細層 B56 — バッテリー2本並列大電流＆縦位置操作信号を運ぶ内部専用バス","plainAnalogy":"縦位置バッテリーグリップ（VG-C4EM）を着けると、バッテリー2本分の大電力と縦位置シャッター・ダイヤル信号がカメラ内へ流れ込みます。バッテリー室の奥の壁に沿って走る「専用フレキ配線」と、それをピタッと留める「ステンレス押さえ金具」です。","summary":"Sony ILCE-7M4サービスマニュアル・BATTERY HOLDER SECTION（Ref.404: 198422211 VG-1007 FLEXIBLE BOARD / Ref.403: 500371201 VG FPC FIX PLATE / Ref.401: A5023247A BT_SOLDER BT-2033）に実在する、縦位置グリップ用12ピン拡張接点（B28）とメイン基板／電源系統を直結する大電流ハイブリッドフレキ配線＆金属固定クランプ板。","opticsAndPhysics":["縦位置グリップ装着時はNP-FZ100バッテリー2本分の最大6 A超の電力に加え、縦位置シャッターボタン・前後コマンドダイヤル・AF-ON・ジョイスティックの高速シリアル制御信号を低遅延で伝送する必要があります。","厚銅（70 μm＝2 oz銅箔）電源ラインと差動信号線を一体化したVG-1007フレキを、バッテリー挿抜時の摩擦から守るためSUS304製VG FPC FIX PLATE（Ref.403）でバッテリー室壁面へ強固にねじ固定しています。"],"formula":{"expression":"I_max = 6.0 A (70 μm 厚銅電源バス・電圧降下 ΔV < 35 mV),   SUS押さえ板固定ねじ M1.7×2.5","description":"厚銅フレキによる低損失大電流伝送と、ステンレス押さえ板によるバッテリー挿抜摩耗保護を両立。"},"nextGenInnovation":"BT-2033バッテリー端子フレキと協調ルーティングされ、本体側・グリップ側どちらのバッテリーが空になっても電源瞬断ゼロで自動シームレス切替を行います。","specs":[{"label":"実機品番","value":"Sony Ref.404 (198422211 VG-1007 FPC) ＋ Ref.403 (500371201 VG FPC FIX PLATE) ＋ Ref.401"},{"label":"配線仕様","value":"2 oz（70 μm）厚銅電源バス ＋ 縦位置操作系シリアル通信フレキ"},{"label":"固定保護","value":"SUS304 VG FPC FIX PLATE（バッテリー挿抜時の擦れ・脱落完全防止）"},{"label":"対応機材","value":"純正縦位置バッテリーグリップ（VG-C4EM / VG-C5）高出力連続撮影対応"}],"diagramType":"body_vg_fpc_retainer"},{"id":"body-top-antenna-coax","order":57,"swatchColor":"#eab308","groupKey":"個別微細層_B57_マグネシウム電波遮蔽を突破するトップ樹脂窓直","assembledPos":[34,38,8],"explodeOffset":[56,70,22],"integratedExplodeOffset":[56,70,22],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B57. トップデッキ内蔵 2.4/5GHz 無線アンテナ基板 AN-1043 ＆ 45mm極細同軸ケーブル（SONY A5033443A / 184647441）","subtitle":"Top-Deck Dual-Band Wi-Fi/BT Antenna Sub-Board (Sony Ref.262 AN-1043) & 45mm Micro-Coax (Ref.263)","category":"個別微細層 B57 — マグネシウム電波遮蔽を突破するトップ樹脂窓直下の無線アンテナ","plainAnalogy":"金属のカメラボディは電波を通さないため、メイン基板の中にアンテナを置くとWi-Fiが全然届きません。そこでカメラの左肩のいちばん高い樹脂カバーの真下に「専用のミニアンテナ基板」を置き、長さ45mmの極細同軸ケーブルでメイン基板と繋いでいます。","summary":"Sony ILCE-7M4サービスマニュアル・CABINET TOP SECTION-1（Ref.262: A5033443A AN-1043 BOARD, COMPLETE / Ref.263: 184647441 CABLE, COAXIAL 45 mm）およびKolari Vision A7R V分解（「トップカバー取り外し前に2本の同軸ケーブルを外す」）で実在確認されたトップ内蔵デュアルバンドRFアンテナサブモジュール。","opticsAndPhysics":["AZ91Dマグネシウム合金外装は強力なファラデーケージとして2.4 GHz／5 GHzマイクロ波を−40 dB以上減衰させるため、カメラ上部の左肩またはペンタ前縁に設けた非導電樹脂RF透過窓（レドーム）直下へ独立アンテナ基板AN-1043を配置します。","特性インピーダンス 50 Ω ± 2 Ω の外径0.81 mm極細同軸ケーブル（長さ45 mm・U.FL/MHF4マイクロ同軸コネクタ付）でメイン基板のWi-Fi/BT RFフロントエンドへ低損失伝送し、報道現場の高速FTP即時送信と安定したスマホ連携を実現します。"],"formula":{"expression":"Z₀ = 50 Ω (L = 45 mm φ0.81 mm 極細同軸),   挿入損失 < 0.25 dB @ 5.8 GHz (VSWR < 1.5)","description":"カメラ最上部のRF透過窓へアンテナを独立移設し、マグネシウム外装と手持ち把持による電波減衰を回避。"},"nextGenInnovation":"Kolari Visionのα1分解で指摘されたように、同軸ケーブル上部にはクリア保護スリーブが巻かれ、トップデッキ開閉やねじ締結時の噛み込み断線を防ぐ工夫が凝らされています。","specs":[{"label":"実機品番","value":"Sony Ref.262 (A5033443A AN-1043 BOARD) ＋ Ref.263 (184647441 COAXIAL CABLE 45mm)"},{"label":"対応帯域","value":"2.4 GHz / 5 GHz IEEE 802.11ac/ax Wi-Fi ＆ Bluetooth 5.x デュアルバンド"},{"label":"伝送線路","value":"φ0.81 mm 50 Ω 金めっき編組極細マイクロ同軸ケーブル（長さ 45 mm）"},{"label":"配置利点","value":"カメラ手持ち時に左右の手のひらで覆われない最上部RFレドーム直下配置"}],"diagramType":"body_top_antenna_coax"},{"id":"body-power-lever-mechanism","order":58,"swatchColor":"#ef4444","groupKey":"個別微細層_B58_人差し指1本で0_2秒起動する同軸電源カラー","assembledPos":[-54.5,34.5,20.5],"explodeOffset":[-58,66,48],"integratedExplodeOffset":[-58,66,48],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B58. 同軸電源ON/OFFレバー・復帰トーションバネ ＆ 防塵シリコーンOリング","subtitle":"Coaxial Shutter-Collar Power ON/OFF Lever, Detent Leaf Spring & Red Silicone Shaft O-Ring","category":"個別微細層 B58 — 人差し指1本で0.2秒起動する同軸電源カラー＆軸回転防水Oリング","plainAnalogy":"シャッターボタンの周りをぐるっと囲んでいる「電源ON/OFFの回転つまみ」を分解した姿です。クルッと回す可動部分から雨が染み込みやすいため、軸の根元に「極細のシリコーンOリング」と「カチッと止まる板バネ」が精密に仕込まれています。","summary":"シャッターボタン（B04/B15）の同軸外周に配置された、電源ON/OFF回転カラーレバー、30°回転ストッパーカム、二位置クリック保持リーフスプリング、および回転軸からの雨水侵入を遮断する極小シリコーンOリングの精密同軸アセンブリ。","opticsAndPhysics":["「カメラを構えて右人差し指をわずかに伸ばすだけで0.2秒以内にON→半押しAF→撮影」という即応性を叶えるため、シャッターボタンの押し込み軸（Z/Y並進運動）と電源レバーの回転軸（同軸30°回転運動）を完全に独立させながらφ14 mm径内へ同心配置しています。","Imaging Resource等の防滴研究で強調される通り、回転可動軸の防水には固定パッキンではなく潤滑シリコーンOリングによる全周360°動的摺動シールが不可欠です。"],"formula":{"expression":"回転操作角 θ = 30° (切替トルク ≈ 14 mN·m),   回転軸動的Oリング圧縮率 15% 防滴封止","description":"シャッター並進軸と同軸共存させながら、カチッとした節度感と回転軸360°防滴シールを両立。"},"nextGenInnovation":"電源レバーの回転検出には非接触ホールセンサーまたは金めっき二股セルフクリーニング摺動ワイパー（SH-1035 / RL-1071基板上）を採用し、10万回開閉でも接触不良を起こしません。","specs":[{"label":"機構構成","value":"同軸30°回転電源レバー ＋ SUS二位置クリック板バネ ＋ 回転ストッパー"},{"label":"防水シール","value":"回転軸専用 高潤滑シリコーンOリング（φ11.5 × 線径 0.8 mm）"},{"label":"人間工学","value":"誤作動防止の適度な操作抵抗（14 mN·m）＆ グローブ対応突起タブ"},{"label":"連携接点","value":"B15 シャッタースイッチ同軸下の金めっき自己洗浄ワイパー接点"}],"diagramType":"body_power_lever_mechanism"},{"id":"body-mic-rubber-mount","order":59,"swatchColor":"#06b6d4","groupKey":"個別微細層_B59_レンズAF音・IBIS駆動音のボディ伝搬を遮","assembledPos":[0,35.5,19.5],"explodeOffset":[0,62,54],"integratedExplodeOffset":[0,62,54],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B59. ステレオマイク防振ラバーブーツ RUBBER MICROPHONE ＆ 保持ホルダー MIC HOLDER（SONY 502687801 / 502790401）","subtitle":"Vibration-Isolating Stereo Mic Rubber Boots (Sony Ref.304) & Retention Holder (Ref.308)","category":"個別微細層 B59 — レンズAF音・IBIS駆動音のボディ伝搬を遮断するマイク防振ブーツ","plainAnalogy":"カメラの上面にある左右2つの内蔵ステレオマイクは、そのまま金属ボディに付けるとレンズのモーター音や手ブレ補正の「ウィーン」という振動を拾ってしまいます。マイクを柔らかい「防振ゴムの靴下（ラバーブーツ）」で包み込んで浮かせて録音品質を守っています。","summary":"Sony ILCE-7M4サービスマニュアル・CABINET TOP SECTION-2（Ref.304: 502687801 RUBBER (885), MICROPHONE / Ref.308: 502790401 MIC HOLDER (89100) / Ref.309: BTITE 1.4×5.0固定ねじ）に実在する、内蔵ステレオマイクカプセルの機械的フローティング防振ラバーブーツ＆押さえホルダー機構。","opticsAndPhysics":["動画収録時にボディ内の5軸IBISアクチュエータやレンズのAF駆動・ズームリング操作で発生する固体伝搬振動（50〜800 Hz）がマイク筐体へ直接伝わると、音声トラックに耳障りな低周波ゴロゴロ音（ハンドリングノイズ）が混入します。","極低硬度（30 Shore A）のブチル／シリコーン防振ブーツ（Ref.304）で左右カプセルを完全フローティング支持し、さらにMIC HOLDER（Ref.308）で音波導入スリットのみを音響密閉することで、クリアなステレオ集音を実現します。"],"formula":{"expression":"固体伝搬ハンドリングノイズ減衰 ≥ −14 dB (50–800 Hz),   ブーツ硬度 30 Shore A 軟質フローティング","description":"カメラボディの機械振動からステレオマイクカプセルを音響機械分離するミニチュアショックマウント。"},"nextGenInnovation":"マイク前面には微細な疎水性音響透過メッシュ（ePTFE膜）を組み合わせ、風切り音低減と雨滴のマイク穴侵入防止を両立しています。","specs":[{"label":"実機品番","value":"Sony Ref.304 (502687801 RUBBER MICROPHONE) ＋ Ref.308 (502790401 MIC HOLDER)"},{"label":"防振材質","value":"超軟質 30 Shore A 粘弾性フローティング防振ラバーブーツ × 2（L/R）"},{"label":"固定構造","value":"専用樹脂MIC HOLDER ＋ BTITE 1.4×5.0ねじ締結（音響密閉チャンバー形成）"},{"label":"音響効果","value":"IBIS動作音・レンズAF駆動音・操作ボタン打音の固体伝搬を −14 dB 遮断"}],"diagramType":"body_mic_rubber_mount"},{"id":"body-rear-lc-cover-seals","order":60,"swatchColor":"#3b82f6","groupKey":"個別微細層_B60_バリアングル液晶の裏に隠れた防水壁・隠しねじ","assembledPos":[10,-8,-33.2],"explodeOffset":[34,-12,-80],"integratedExplodeOffset":[34,-12,-80],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B60. 背面LCD収納凹部カバー REAR LC COVER・防水パッキン ＆ ヒンジケーブルグロメット（SONY 502794901 / 501161101）","subtitle":"Recessed LCD Bay Cover Plate (Ref.53), Dual WP Cushions (Ref.54/124) & Swivel Cable Grommet (Ref.78)","category":"個別微細層 B60 — バリアングル液晶の裏に隠れた防水壁・隠しねじ覆い＆ケーブルブーツ","plainAnalogy":"バリアングル液晶画面をパカッと横へ開くと現れる、カメラ背面の「くぼみ（収納ポケット）」の底板と防水パーツ一式です。画面のヒンジを通る細いケーブルの入り口を「ゴムの首輪（グロメット）」と2枚の防水クッションで鉄壁に密閉しています。","summary":"Sony ILCE-7M4サービスマニュアル・CABINET REAR SECTION-1/2（Ref.53: 502794901 REAR LC COVER / Ref.54: 502863001 RE LC WP CUSHION A / Ref.124: 502863101 RE LC WP CUSHION B / Ref.78: 501161101 SV WP CABLE GROMMET / Ref.56: 503623301 GASKET BOT S）に実在する、背面LCD収納ポケット保護カバー＆ヒンジ配線貫通防水シーリング一式。","opticsAndPhysics":["バリアングル／4軸チルトモニターを展開すると、背面LCD収納凹部は直接雨や砂塵に晒されます。その内側にはメイン基板のヒートスプレッダと3本の背面隠しねじが直近に位置しています。","REAR LC COVER（Ref.53）が凹部底面の美観・保護壁・熱遮断層を形成し、周囲を2種類の防水クッション（Ref.54/124）と底面ガスケット（Ref.56）で封止。さらにLCDヒンジから引き込まれる極細同軸ケーブルの通過口をSV WP CABLE GROMMET（Ref.78）が360°密着シーリングします。"],"formula":{"expression":"LCD展開時 耐雨封止: RE LC COVER (Ref.53) ＋ クッションA/B ＋ SV WP GROMMET (Ref.78)","description":"モニター展開中もメイン基板室へ一滴の雨水も入れない、バリアングル機特有の背面凹部防水アーキテクチャ。"},"nextGenInnovation":"Lensrentalsの分解でも評価されたように、このカバーのサービス構造により、割れたLCDパネルやヒンジ同軸ケーブルをボディ全分解なしで短時間交換できます。","specs":[{"label":"実機品番","value":"Sony Ref.53 (REAR LC COVER) / Ref.54・124 (RE LC WP CUSHION A/B) / Ref.78 (SV WP GROMMET) / Ref.56"},{"label":"構成部材","value":"背面LCDポケット保護カバー・二重防水クッション・底面ガスケット・ケーブルグロメット"},{"label":"保護役割","value":"バリアングル液晶展開時の雨塵侵入遮断・背面3本隠しねじ保護・熱遮断"},{"label":"配線密閉","value":"SV WP CABLE GROMMET による極細同軸ケーブル貫通孔の360°気密シール"}],"diagramType":"body_rear_lc_cover_seals"},{"id":"body-dl1008-rtc-flex","order":61,"swatchColor":"#f59e0b","groupKey":"個別微細層_B61_メイン電池を抜いても時計と設定を忘れない_電","assembledPos":[-42.5,-18,-5.5],"explodeOffset":[-58,-42,-26],"integratedExplodeOffset":[-58,-42,-26],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B61. Sony純正 DL-1008 サブフレキ（Ref.411）・着脱不可ソケット BH0001 ＆ 二次リチウム電池 BT0001","subtitle":"Sony OEM Battery-Bay DL-1008 Flex Board (Ref.411), One-Time Socket BH0001 & Secondary Li-Mn Cell BT0001","category":"個別微細層 B61 — メイン電池を抜いても時計と設定を忘れない「電池室脇のミニ充電池ユニット」","plainAnalogy":"撮影中にメインのバッテリーを交換しても、カメラの日付や時刻・カスタム設定がリセットされませんよね？実はバッテリー室のすぐ脇に、小さなボタン型の「バックアップ用充電池（BT0001）」が専用フレキ基板（DL-1008）に乗せて隠されているのです！しかもSony公式マニュアルには「一度外した電池ソケット（BH0001）は再利用禁止！」と明記されているほど、接触信頼性にこだわったプロ仕様部品です。","summary":"Sony ILCE-7M4 公式サービスマニュアル BATTERY HOLDER SECTION Ref.410（500708501: ADHESIVE DL TOP）、Ref.411（A5033446A: DL-1008 FLEXIBLE BOARD）、BH0001（125192821: SOCKET, BATTERY）および BT0001（A175613418: 二次リチウム電池）の純正バックアップ電源アセンブリです。","opticsAndPhysics":["メインのNP-FZ100バッテリーを入れている間に数マイクロアンペアの極微弱電流で自動充電され、メイン電池を完全に抜いた状態でも数か月間にわたりリアルタイムクロック（RTC）と揮発性設定メモリを保持し続けます。","サービスマニュアル Note 2 には「DL-1008上の二次リチウム電池（BT0001）を交換する際は、必ずソケット（BH0001）も新品へ同時交換すること（一度外したソケットはバネ圧低下のため再利用不可）」と厳格に規定されています。","メイン基板ではなくバッテリーホルダー外周（BTH ASSY側）に独立配置することで、メイン基板の超高密度化と整備時の電池交換安全性を両立しています。"],"formula":{"expression":"t_hold = Q_cell / I_RTC ≈ 3 mAh / 1.5 μA ≈ 2,000時間（約3か月無給電保持）","description":"超省電力な時計回路（1.5マイクロアンペア）と小型充電池の組み合わせで、メイン電池なしでも数か月間時刻を守ります。"},"nextGenInnovation":"超低自己放電型のマンガンリチウム二次コイン電池（3V級）と専用両面粘着シート（ADHESIVE DL TOP）の採用により、長期間の防湿庫保管後も時計リセットが起きにくい信頼性を実現しています。","specs":[{"label":"Sony純正品番①","value":"Ref.411: A5033446A (DL-1008 FLEXIBLE BOARD) / Ref.410: 500708501"},{"label":"Sony純正品番②","value":"BH0001: 125192821 (電池ソケット・再利用不可) / BT0001: A175613418"},{"label":"配置位置","value":"バッテリーホルダー（BTH ASSY Ref.406）外壁 専用ポケット"},{"label":"役割","value":"メイン電池交換・長期保管時の日付時刻（RTC）およびカメラ設定保持"}],"diagramType":"body_dl1008_rtc_flex"},{"id":"body-bt2033-power-fpc","order":62,"swatchColor":"#d97706","groupKey":"個別微細層_B62_バッテリー端子からカメラ心臓部へ大電流を運ぶ","assembledPos":[-48,-8,5.5],"explodeOffset":[-76,-16,36],"integratedExplodeOffset":[-76,-16,36],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B62. Sony純正 BT_SOLDER / BT-2033 大電流バッテリー給電フレキ（Ref.401）＆ 内部電源ケーブル（Ref.413）","subtitle":"Sony OEM High-Current Battery Power Flex BT-2033 (Ref.401: A5023247A) & Power Harness Cable (Ref.413)","category":"個別微細層 B62 — バッテリー端子からカメラ心臓部へ大電流を運ぶSony純正「極太給電ハーネス」","plainAnalogy":"バッテリーを差し込む奥の金メッキ端子とメイン基板の間は、カメラ全体で一番大きな電流（最大6アンペア以上！）が流れる「大動脈」です。普通の薄いリボンだと電気が詰まって発熱してしまうため、Sony純正では分厚い銅箔をはんだ接合した専用の給電フレキ（BT-2033）と太めの電源ケーブル（Ref.413）、さらに耐熱テープ（Ref.402）でガッチリつないでいます！","summary":"Sony ILCE-7M4 公式サービスマニュアル BATTERY HOLDER SECTION Ref.401（A5023247A: BT_SOLDER including BT-2033 flexible board）、Ref.402（750000493: TAPE 631S #25）および Ref.413（184678731: CABLE）からなる主電源供給ハーネスです。","opticsAndPhysics":["BT-2033 フレキシブル基板は、一般の信号用FPC（銅厚12〜18μm）の2〜3倍にあたる厚銅箔（35〜70μm）を使用し、電池室奥の4極端子ブロック（B14）に直接強固にはんだ付け（BT_SOLDER）されています。","正極（+7.2V）・負極（GND）の主電源ラインに加えて、NP-FZ100の残量％を正確に読み取るインフォリチウム通信線（T端子・ID端子）を同一フレキで最短ルーティングしています。","8K動画収録や超望遠レンズのXDリニアモーターAF駆動時に瞬間的な大電流が流れても、電圧降下による「バッテリー残量急落表示」や強制シャットダウンを防ぎます。"],"formula":{"expression":"ΔV_drop = I_peak · R_BT2033 < 0.05 V   (厚銅箔で瞬間大電流でも電圧低下を防止)","description":"分厚い銅の電気道（BT-2033）で抵抗を極限まで下げることで、連写の瞬間でも電池のパワーを100%引き出します。"},"nextGenInnovation":"縦位置グリップ（VG-C4EM/C5）接続用フレキ（VG-1007 / B56）と電池室底部で並列合流できる立体レイアウトにより、グリップ装着時のデュアルバッテリー無停電切替も低損失で行えます。","specs":[{"label":"Sony純正品番①","value":"Ref.401 / Part No. A5023247A (BT_SOLDER / BT-2033 FLEXIBLE BOARD)"},{"label":"Sony純正品番②","value":"Ref.413: 184678731 (CABLE) / Ref.402: 750000493 (TAPE 631S #25)"},{"label":"導体仕様","value":"大電流対応 2oz厚銅ポリイミドFPC＋電池端子ダイレクトはんだ接合"},{"label":"信号構成","value":"7.2V主電源（+ / −）＋インフォリチウム残量通信・温度検知線"}],"diagramType":"body_bt2033_power_fpc"},{"id":"body-rs1024-rear-bus","order":63,"swatchColor":"#ea580c","groupKey":"個別微細層_B63_背面ボタン全部を1本にまとめず_4つに分けて","assembledPos":[0,0,-30.2],"explodeOffset":[-24,12,-78],"integratedExplodeOffset":[-24,12,-78],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B63. Sony純正 背面4分割モジュラー制御フレキ群（RS-1024 / SW-1041 / JS-1012 / KY-1035）","subtitle":"Sony OEM 4-Branch Modular Rear Control Flex Harness (Ref.55 RS-1024, Ref.62 SW-1041, Ref.63 JS-1012, Ref.105 KY-1035)","category":"個別微細層 B63 — 背面ボタン全部を1本にまとめず「4つに分けて修理しやすくした」純正フレキ網","plainAnalogy":"カメラの裏フタを開けると、背面ボタンの配線は1枚の巨大な板ではなく、実は「4つの小さなリボン基板」に賢く分かれています！①全部をまとめてメイン基板へつなぐ大幹線の「RS-1024」、②再生・ゴミ箱・Fn用の「SW-1041」、③グリグリ動かすジョイスティック専用の「JS-1012」、④上のMENU・AF-ON用の「KY-1035」。おかげでジョイスティックだけ壊れても、そこだけ安く交換できるのです！","summary":"Sony ILCE-7M4 公式サービスマニュアル CABINET REAR SECTION-1 & 2 に実在する4系統の純正フレキ基板（Ref.55: RS-1024 / Ref.62: SW-1041 / Ref.63: JS-1012 / Ref.105: KY-1035）のモジュラー配線ネットワークです。","opticsAndPhysics":["裏カバー（CAB REAR ASSY）を外す際にメイン基板から切り離す「1本の太い幹線リボン」が RS-1024（Ref.55: A5033449A）であり、裏カバー側の集約ハブとして各サブスイッチフレキとコントロールホイール（Ref.64）を統合します。","使用頻度が極めて高いAFジョイスティック（JS-1012: A5001912A）、下部ボタン（SW-1041: A5033451A）、上部AF-ON/MENU（KY-1035: 100999311）を別パーツ化することで、立体的な背面曲面への貼付精度と部分修理性を大幅に高めています。","各ボタン直下にはクリック感の明瞭なステンレス・スナップドーム（作動荷重約2.0〜2.8N）が保護PETフィルム下に密閉配置され、湿気による接点酸化を防ぎます。"],"formula":{"expression":"RS-1024 (幹線1本) ⇐ { SW-1041 ＋ JS-1012 ＋ KY-1035 ＋ Wheel }","description":"4つの小基板を1本の幹線リボン（RS-1024）にまとめることで、故障した部分だけをピンポイントで交換できる親切設計です。"},"nextGenInnovation":"カメラ背面をわずか1本のRS-1024幹線コネクタで本体と分離できる設計にしたことで、センサー清掃やメイン基板交換の整備時間が旧世代比で半分近くに短縮されました。","specs":[{"label":"幹線ハブフレキ","value":"Ref.55 / A5033449A (RS-1024 FLEXIBLE BOARD, COMPLETE)"},{"label":"下部ボタン系","value":"Ref.62 / A5033451A (SW-1041 FLEXIBLE BOARD, COMPLETE)"},{"label":"ジョイスティック","value":"Ref.63 / A5001912A (JS-1012 FLEXIBLE BOARD, COMPLETE)"},{"label":"上部ボタン系","value":"Ref.105 / 100999311 (KY-1035 FLEXIBLE BOARD)"}],"diagramType":"body_rs1024_rear_bus"},{"id":"body-rl1071-shutter-fpc","order":64,"swatchColor":"#f97316","groupKey":"個別微細層_B64_何十万回ものシャッター押しと前ダイヤルの力を","assembledPos":[-51.5,32.2,16.5],"explodeOffset":[-68,56,56],"integratedExplodeOffset":[-68,56,56],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B64. Sony純正 RL-1071 レリーズフレキ（Ref.257）・RL FPC BASE（Ref.251）＆ 前ダイヤル保持板（Ref.256）","subtitle":"Sony OEM Shutter Release RL-1071 Flex (Ref.257), Molded RL FPC Base (Ref.251) & Front Dial Plate (Ref.256)","category":"個別微細層 B64 — 何十万回ものシャッター押しと前ダイヤルの力を支える「グリップ頂上の土台」","plainAnalogy":"人差し指で一番よく押すシャッターボタンと、そのすぐ前のクルクル回す前ダイヤル。何十万回押してもフニャフニャしない秘密は、裏側に隠された専用の樹脂台座（RL FPC BASE）と頑丈な金属押さえ板（CNT D F HOLDER PLATE）！その上にシャッター専用フレキ（RL-1071）とスイッチブロック（Ref.258）をガッチリ載せて、プロ好みのカチッとした押し心地を作っています！","summary":"Sony ILCE-7M4 公式サービスマニュアル CABINET TOP SECTION-1 Ref.251（502790701: RL FPC BASE）、Ref.255（X50025381: CNT DIAL F ASSY）、Ref.256（500382401: CNT D F HOLDER PLATE）、Ref.257（A5036663A: RL-1071 FLEXIBLE BOARD）および Ref.258（100203812: SWITCH BLOCK）のグリップ頂上操作ユニットです。","opticsAndPhysics":["シャッター半押し（AF/AEロック）から全押し（レリーズ）までのわずか0.35mmのストローク差を指先に明瞭に伝えるため、RL-1071フレキの裏側を剛性の高い樹脂キャリア（RL FPC BASE）で面支持し、たわみ（空走感）を排除しています。","前電子ダイヤル（CNT DIAL F ASSY）は人差し指で斜め上から強い回転・押し込み荷重を受けるため、専用の金属ホルダープレート（CNT D F HOLDER PLATE）でトップカバーへ強固に固定され、軸ブレを防ぎます。","RL-1071のスイッチ部には2段同心ドーム接点と電源スイッチ接点が一体集約され、防水シール下の狭小グリップ頂上に納まっています。"],"formula":{"expression":"F_half ≈ 1.4 N → F_full ≈ 3.2 N   (剛性ベース支持で 0.35 mm 2段感触を鮮明化)","description":"裏側から硬い土台と金属板でしっかり支えることで、「半押し→全押し」の絶妙な2段階のクリック感がぼやけません。"},"nextGenInnovation":"シャッターボタンと前ダイヤル周りを独立キャリア（RL FPC BASE）にユニット化したことで、酷使される報道プロカメラマンのシャッタースイッチ交換整備も短時間・高精度で行えます。","specs":[{"label":"Sony純正品番①","value":"Ref.257: A5036663A (RL-1071) / Ref.251: 502790701 (RL FPC BASE)"},{"label":"Sony純正品番②","value":"Ref.256: 500382401 (CNT D F HOLDER PLATE) / Ref.258: 100203812"},{"label":"対応操作部","value":"2段シャッターレリーズ・同軸電源スイッチ・前面コマンドダイヤル"},{"label":"耐久性","value":"半押し／全押し数十万回操作に耐える高剛性ベース支持設計"}],"diagramType":"body_rl1071_shutter_fpc"},{"id":"body-sh1035-top-connect","order":65,"swatchColor":"#94a3b8","groupKey":"個別微細層_B65_重い望遠レンズを首から下げても_肩_が歪まな","assembledPos":[-4,35.8,-2],"explodeOffset":[0,72,16],"integratedExplodeOffset":[0,72,16],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B65. Sony純正 SH-1035 トップメインフレキ（Ref.307）・左肩連結補強板（Ref.313）＆ 右肩ストラップ連結板（Ref.261）","subtitle":"Sony OEM Top Main Flex SH-1035 (Ref.307), Top Connect Plate L (Ref.313) & Eyelet Plate G (Ref.261)","category":"個別微細層 B65 — 重い望遠レンズを首から下げても「肩」が歪まない金属つなぎ板＆トップ幹線フレキ","plainAnalogy":"カメラに1kg以上の重い望遠レンズを付けてストラップで首からぶら下げると、左右の「肩のつなぎ目」にものすごい引っ張り力がかかります！もし外装のフタだけだとパカッと開いたり歪んだりしてしまいます。そこでカメラの左右の肩の内側に、屋根と骨格をガッチリ縫い合わせる頑丈なステンレスの「つなぎ補強板（Ref.313 / Ref.261）」を入れ、さらに上面の電気をまとめる幹線フレキ（SH-1035）を通しています！","summary":"Sony ILCE-7M4 公式サービスマニュアル CABINET TOP SECTION-1/2 Ref.307（A5033450A: SH-1035 FLEXIBLE BOARD）、Ref.313（502790501: TOP CONNECT PLATE L）および Ref.261（502790601: EYELET PLATE G）によるトップ骨格連結＆制御幹線セットです。","opticsAndPhysics":["左肩の TOP CONNECT PLATE L（Ref.313）と右肩グリップ側の EYELET PLATE G（Ref.261）は、ストラップ吊り金具（EYELET L/G Ref.316/317）にかかる数kgの動的衝撃荷重（歩行・走行時のG荷重）をトップマグネシウムカバーとメイン内部骨格（Ref.362）の両方へ分散伝達します。","特殊な長尺高張力ねじ（Ref.259/312: M1.7 SG SPIN L=5.5mm）で強固に締結され、長期間の携行でも外装のきしみや防水パッキンのズレを防ぎます。","SH-1035 フレキシブル基板（Ref.307）は、トップデッキ上のモードダイヤル・露出補正ダイヤル・マイク・MIシューからの信号を束ねてメイン基板へ橋渡しする上部中枢ハーネスです。"],"formula":{"expression":"F_strap_drop = m · (1 + a/g) · g  →  連結プレート L/G で主骨格へ荷重分散","description":"歩いたり走ったりするときにストラップにかかる強い衝撃力を、左右の鉄のつなぎ板がボディ全体の骨組みへ逃がします。"},"nextGenInnovation":"外装パネルを単なる「覆い」ではなく、左右の連結プレート（Ref.313/261）で内部フレームと一体モノコック化することで、軽量ながらプロ用望遠ズームに耐えるねじり剛性を生み出しています。","specs":[{"label":"Sony純正品番①","value":"Ref.307 / Part No. A5033450A (SH-1035 FLEXIBLE BOARD, COMPLETE)"},{"label":"Sony純正品番②","value":"Ref.313: 502790501 (TOP CONNECT PLATE L) / Ref.261: 502790601 (EYELET PLATE G)"},{"label":"締結ビス","value":"Ref.259 / Ref.312: 418654511 (SCREW 0+Z M1.7 SG SPIN L=5.5mm)"},{"label":"役割","value":"左右ストラップ高荷重の骨格分散＆トップデッキ全スイッチ集約中継"}],"diagramType":"body_sh1035_top_connect"},{"id":"body-rear-thumb-grip","order":66,"swatchColor":"#1e293b","groupKey":"個別微細層_B66_片手でもカメラがスッと吸い付く_背面の親指引","assembledPos":[-52.5,2.5,-33.2],"explodeOffset":[-82,8,-72],"integratedExplodeOffset":[-82,8,-72],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B66. 背面エルゴノミクス親指レスト滑り止めエラストマー＆内部背面補強板 REAR PLATE（Ref.77: 502794501）","subtitle":"Ergonomic Rear Thumb-Rest High-Friction Elastomer Overmold & Internal Rear Plate (Ref.77: 502794501)","category":"個別微細層 B66 — 片手でもカメラがスッと吸い付く「背面の親指引っ掛けゴム＆裏側補強板」","plainAnalogy":"カメラを右手でギュッと握ったとき、前側のグリップだけでなく「後ろ側の親指が当たる出っ張り（サムレスト）」に指がピタッと引っかかるから片手でも落ちないのです！この部品は汗をかいても滑りにくい専用シボ加工の親指ゴムと、親指で強く押し込んでも裏フタがペコペコ凹まないよう裏側から支える金属の補強板（REAR PLATE Ref.77）のコンビです！","summary":"背面右肩の親指掛かり部（サムレスト）の高摩擦シボ加工エラストマーパッドと、Sony ILCE-7M4 CABINET REAR SECTION-1 Ref.77（502794501: REAR PLATE 89100）に対応する背面構造補強インナープレートです。","opticsAndPhysics":["片手保持時には、前グリップを握る4本指の力と、背面サムレストの張り出し（オーバーハング角約28°）に掛ける親指の反力が偶力（トルク）を作ってレンズ重量を安定支持します。","表面には耐皮脂・耐UV性に優れた熱可塑性エラストマー（TPE）＋微細シボ加工を施し、雨天や手汗で濡れた状態でも高い静止摩擦係数（μ > 0.9）を保ちます。","裏側に配置された REAR PLATE（Ref.77）が親指からの強い握り込み荷重と背面コントロールホイール操作荷重を受け止め、すぐ裏のメイン基板やカードスロットへのたわみ伝達を防ぎます。"],"formula":{"expression":"F_hold = μ_TPE · N_thumb + N_thumb · tan(28°)   (摩擦＋段差引っ掛かりで安定保持)","description":"滑りにくいゴムの摩擦と28°の絶妙な出っ張り段差の合わせ技で、力を入れすぎなくてもカメラが手に吸い付きます。"},"nextGenInnovation":"α7 IV / α7R V / α1 II 世代では、サムレストの張り出し形状とAF-ON／背面ダイヤルの位置関係を人間工学的に最適化し、親指をわずか数ミリ動かすだけで全撮影操作が完結するよう進化しています。","specs":[{"label":"Sony純正品番","value":"Ref.77 / Part No. 502794501 (REAR PLATE 89100)＋背面サムレストゴム"},{"label":"表皮材質","value":"耐皮脂・耐候性高摩擦エラストマー（TPE / シボ加工 μ > 0.9）"},{"label":"人間工学形状","value":"親指掛かり約28°オーバーハング段差＋背面ホイール操作逃げ形状"},{"label":"構造補強","value":"REAR PLATE による握り込み荷重分散＆背面シェルたわみ防止"}],"diagramType":"body_rear_thumb_grip"},{"id":"body-io-port-flap-seals","order":67,"swatchColor":"#0ea5e9","groupKey":"個別微細層_B67_昔みたいにプラプラしない_バネ蝶番_4連シリ","assembledPos":[56.2,0,-5],"explodeOffset":[96,6,-12],"integratedExplodeOffset":[96,6,-12],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B67. 左側面4連ヒンジ式I/Oポート扉・ステンレス蝶番スプリング軸＆成型シリコーン防水リップシール群","subtitle":"Hinged Left-Flank I/O Door Stainless Spring-Hinge Pins & Molded 4-Bay Silicone Lip-Seal Rings","category":"個別微細層 B67 — 昔みたいにプラプラしない！バネ蝶番＆4連シリコーン防水リップ付き端子扉メカ","plainAnalogy":"昔のカメラの端子フタは柔らかいゴムの栓で、開けるとプラプラしてケーブルの邪魔になったり千切れたりしました。最新カメラは「小さなドア（ヒンジ式ハード扉）」に進化！ドアの内側に小さなステンレスの蝶番（ちょうつがい）とバネ、さらに4つの端子口それぞれにピタッと食い込む「柔らかいシリコーンの防水パッキン輪っか」が一体成型されていて、開け閉めが気持ちよく雨も通しません！","summary":"左側面I/Oドア（B11）の裏側に内蔵された、マイク・ヘッドホン・HDMI・USB-C各ポート独立開閉用のステンレスヒンジ軸・トーションバネ・および各ポート開口に嵌合する4連一体成型シリコーン圧縮リップシール群です。","opticsAndPhysics":["4つのポート室ごとに独立したシリコーンゴム製リップシール（周回突起リブ）が、扉を閉じた瞬間にサイドキャビネット（B40）の開口フランジへ約0.4mm弾性圧入され、横殴りの雨や水しぶきの浸入を遮断します。","ステンレス製の極細ヒンジ軸と小型クリックバネが扉を約110°〜135°の開放位置で保持するため、ケーブル挿抜時にフタが勝手に閉まって指やプラグに当たるストレスがありません。","また外部マイクやHDMIケーブルだけを挿して使うときも、使わないUSB-Cやヘッドホン端子の扉は閉じたままにでき、動画撮影時の防塵防滴性を保てます。"],"formula":{"expression":"δ_lip ≈ 0.4 mm (弾性圧入)  ⇒  全4ポート独立防滴シール＆10,000回開閉耐久","description":"ドア裏の柔らかいシリコーン突起が枠に0.4mmギュッと密着して水を止め、金属の蝶番で千切れず何万回も開け閉めできます。"},"nextGenInnovation":"従来のTPE一体ヒンジ（折り曲げ疲労で数年後にちぎれる弱点）から、硬質樹脂ドア＋金属ピン蝶番＋独立シリコーンパッキンへ進化し、数万回の開閉耐久性を獲得しました。","specs":[{"label":"シール構造","value":"4ポート独立周回シリコーンゴム圧縮リップシール（マイク/HP/HDMI/USB-C）"},{"label":"ヒンジ機構","value":"φ1.0 mm ステンレス蝶番ピン＋開放保持クリックバネ"},{"label":"開閉耐久","value":"従来の軟質ゴム一体ヒンジ比で耐久性を大幅向上（> 10,000回）"},{"label":"現場メリット","value":"必要ポートのみ個別開放可能・ケーブル干渉ゼロ・防滴維持"}],"diagramType":"body_io_port_flap_seals"},{"id":"body-bottom-gasket-bot-s","order":68,"swatchColor":"#334155","groupKey":"個別微細層_B68_濡れた地面や三脚の雲台から水が這い上がるのを","assembledPos":[-4,-35.8,-2],"explodeOffset":[0,-94,-18],"integratedExplodeOffset":[0,-94,-18],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B68. Sony純正 GASKET BOT S（Ref.56: 503623301）底面背面合わせ目防水ガスケット＆ビス座Oリング群","subtitle":"Sony OEM Bottom-Rear Seam Weather-Seal Gasket (Ref.56: GASKET BOT S) & Baseplate Boss O-Rings","category":"個別微細層 B68 — 濡れた地面や三脚の雲台から水が這い上がるのを防ぐ「底面の防水堤防」","plainAnalogy":"雨上がりの地面や濡れた岩・ベンチにカメラをちょっと置いたとき、じつは一番危ないのが「底面のスキマ」から毛細管現象で水がジワジワ吸い上がること！そこでSony純正では底面と背面カバーの合わせ目に細長い専用の防水パッキン（GASKET BOT S Ref.56）を敷き、さらに底面のネジ穴周りにも防水処理を施して、下からの水攻めをブロックする「防水堤防」を作っています！","summary":"Sony ILCE-7M4 公式サービスマニュアル CABINET REAR SECTION-1 Ref.56（503623301: GASKET BOT S 89100）に対応する底面・背面接合ライン専用防水ガスケット、および底面ベースプレート固定ビス座の防水シーリングリング群です。","opticsAndPhysics":["カメラ底面は三脚クイックリリースプレートとの間に雨水が溜まりやすく、わずかな隙間があると毛細管現象で重力に逆らって水が内部へ吸い上げられます。","GASKET BOT S（Ref.56）は背面キャビネット最下辺とボトムカバー（Ref.15）の接合溝へ精密配置され、底面周囲のラビリンス段差と連携して水の吸い上げを物理遮断します。","さらに底面の複数本の固定ビス座には撥水シールリングとねじ込み面シール材を配し、ネジ山を伝って底面から水が侵入するルートも封鎖します。"],"formula":{"expression":"h_cap = 2σ·cosθ / (ρ·g·d)  →  GASKET BOT S で隙間 d を密閉し毛細管浸水を遮断","description":"細いスキマがあると水は下から上へ吸い上がってしまいます。底面専用ガスケットでスキマを潰し、水の吸い上げを止めます。"},"nextGenInnovation":"底面のポッティング防水ユニット（Ref.17）とこの GASKET BOT S（Ref.56）を組み合わせることで、地面スレスレのローアングル撮影や雨天三脚撮影での信頼性を飛躍的に高めています。","specs":[{"label":"Sony純正品番","value":"Ref.56 / Part No. 503623301 (GASKET BOT S 89100)"},{"label":"材質","value":"耐圧縮永久歪み EPDM独立気泡防水エラストマーガスケット"},{"label":"併用シール","value":"底面ベースプレート固定ビス座 撥水Oリング＆ラビリンス排水溝"},{"label":"保護シーン","value":"濡れた地面・三脚雲台上の水溜まりからの毛細管浸水防止"}],"diagramType":"body_bottom_gasket_bot_s"},{"id":"body-media-lid-base-seal","order":69,"swatchColor":"#475569","groupKey":"個別微細層_B69_撮影データが詰まったカード室を_2重の防水パ","assembledPos":[-61.8,1.5,-14.5],"explodeOffset":[-102,4,-24],"integratedExplodeOffset":[-102,4,-24],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B69. Sony純正 MEDIA LID BASE（Ref.60）・GASKET MED（Ref.61）＆ MEDIA LID WP CUSHION（Ref.122）","subtitle":"Sony OEM Media-Bay Subframe MEDIA LID BASE (Ref.60), GASKET MED (Ref.61) & WP Cushion (Ref.122)","category":"個別微細層 B69 — 撮影データが詰まったカード室を「2重の防水パッキン」で守る専用土台枠","plainAnalogy":"メモリーカードが入っている右側面のフタは、カメラを握る右手の手のひらが常にベッタリ当たる場所！だから手汗や雨粒が一番入りやすい危険地帯でもあります。大切な写真データを守るため、Sony純正ではカード室の入口に専用の受け枠（MEDIA LID BASE）を設け、なんと「枠側（GASKET MED）」と「フタ側（WP CUSHION）」の2重の防水パッキンでピタッと密閉しています！","summary":"Sony ILCE-7M4 公式サービスマニュアル CABINET REAR SECTION-1/2 Ref.60（502794801: MEDIA LID BASE）、Ref.61（502863501: GASKET MED）および Ref.122（502862701: MEDIA LID WP CUSHION）からなるデュアルカードスロット2重防滴構造です。","opticsAndPhysics":["MEDIA LID BASE（Ref.60）は背面キャビネット内側からカード扉開口の剛性を補強し、スライドロック扉（B21）を閉じた際に周囲全周へ均等なパッキン圧縮圧がかかる基準受け面を形成します。","外周溝に貼られる GASKET MED（Ref.61）と、扉内側に配される MEDIA LID WP CUSHION（Ref.122）の2段構えにより、握り込んだ右手から伝う汗や雨水がCFexpress/SDスロットの金メッキ端子を腐食させるのを防ぎます。","同時に扉の閉まりすぎやガタつきを吸収するクッションストッパーとしても働き、握ったときにカード扉が「ギシギシ鳴る」不快な軋み音を消します。"],"formula":{"expression":"Seal_card = GASKET MED (枠側) ＋ WP CUSHION (扉側) ⇒ 二重防汗・防滴密閉","description":"枠とフタのそれぞれに防水パッキンを配置した2重ロックで、手のひらの汗や雨粒から大事なメモリーカードを守ります。"},"nextGenInnovation":"スライド＋ヒンジ開放の2アクションロック機構と2重防水ガスケットの組み合わせにより、カバンの中での誤開放ゼロと雨天でのデータ保全を両立しています。","specs":[{"label":"Sony純正品番①","value":"Ref.60: 502794801 (MEDIA LID BASE 89100)"},{"label":"Sony純正品番②","value":"Ref.61: 502863501 (GASKET MED) / Ref.122: 502862701 (WP CUSHION)"},{"label":"保護対象","value":"デュアルCFexpress / SDカードスロット＆電気接点・収録データ"},{"label":"副次効果","value":"右手グリップ握り込み時のカード扉ガタつき・軋み音防止"}],"diagramType":"body_media_lid_base_seal"},{"id":"body-backlit-button-leds","order":70,"swatchColor":"#fde047","groupKey":"個別微細層_B70_真っ暗な星空・夜景撮影でもボタンがフワッと光","assembledPos":[0,0,-32.2],"explodeOffset":[-42,22,-84],"integratedExplodeOffset":[-42,22,-84],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B70. 暗所撮影用ボタンバックライト 0402極小LEDアレイ＆レーザー導光シリコーンシート","subtitle":"Night-Shooting Illuminated Button 0402 Micro-LED Array & Laser-Etched Silicone Light-Guide Film","category":"個別微細層 B70 — 真っ暗な星空・夜景撮影でもボタンがフワッと光って迷わない内蔵イルミネーション","plainAnalogy":"星空や夜景、暗いライブ会場で撮影するとき、「あれ、MENUボタンや再生ボタンどこだっけ？」と手探りで迷ったことはありませんか？最新フラッグシップボディのボタンの裏には、米粒の1/20サイズの極小LEDと、光を均一に運ぶ薄い「光ファイバーみたいなシリコーン導光シート」が仕込まれており、電源レバーをひねるだけでボタンの文字が目に優しい明るさでポワッと浮かび上がります！","summary":"夜間・暗所撮影時の操作性を飛躍的に高める、背面・上面主要ボタン（MENU / PLAY / DELETE / AF-ON / Fn / DISP等）直下の0402サイドビュー微細LEDアレイ、レーザー微細ドット加工シリコーン導光シート、および二色成型透光キーキャップ群です。","opticsAndPhysics":["消費電力わずか数mWの高効率0402白色／アンバー色LEDの光を、厚さ約0.2mmの光学シリコーン導光フィルム内部で全反射（TIR）させて各ボタン裏まで均一に導きます。","ボタン裏の真下だけレーザー微細ドットで光を上方向へ散乱取り出しすることで、少ないLED個数（4〜6個）でも全ボタンのアイコンがムラなく均一に発光します。","星景写真家の暗順応（暗闇に慣れた瞳）を壊さないよう輝度は極めて繊細にPWM調光され、ファインダーや背面モニターへ光が漏れないよう周囲を黒色遮光シートで囲っています。"],"formula":{"expression":"P_LED < 15 mW (PWM調光),   全反射導光フィルムで全ボタンを均一照明","description":"超省エネな極小LEDの光を薄い透明シートで全ボタンへ均等に配り、電池をほとんど減らさず暗闇での押し間違いをなくします。"},"nextGenInnovation":"従来は大型一体型プロ機（Nikon Z9 / Canon R1系）だけの特権だったイルミネーションボタンが、超薄型導光シート技術の進歩によりコンパクトなフルサイズボディにも搭載可能になりました。","specs":[{"label":"光源素子","value":"EIA 0402 サイドビュー極小白色/暖色LED × 6灯（PWM輝度制御）"},{"label":"導光構造","value":"t = 0.20 mm レーザーマイクロドット加工 光学シリコーン導光シート"},{"label":"キーキャップ","value":"レーザー刻印・二色成型透光耐摩耗樹脂（文字消えゼロ）"},{"label":"撮影メリット","value":"星景・夜景・舞台撮影での暗所ブラインド操作ミスを大幅低減"}],"diagramType":"body_backlit_button_leds"},{"id":"body-tally-lamp-diffuser","order":71,"swatchColor":"#ef4444","groupKey":"個別微細層_B71_今_録画中だよ_を前からも後ろからも一目で伝","assembledPos":[0,0,0],"explodeOffset":[-44,34,68],"integratedExplodeOffset":[-44,34,68],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B71. 前面・背面デュアル録画タリーランプ（高輝度赤LED＆プリズム拡散レンズ）＆ AF補助光フレネルレンズ","subtitle":"Dual Front/Rear Video Recording Tally LEDs with Prism Diffusers & Front AF-Assist Fresnel Lens","category":"個別微細層 B71 — 「今、録画中だよ！」を前からも後ろからも一目で伝える赤色タリー＆AF補助光レンズ","plainAnalogy":"動画撮影で一番悲しい失敗は「撮れていると思ったら録画ボタンが押せていなかった！」こと。そこでボディの前側（映る人側）と後ろ側（撮る人側）の両方に、録画中に赤くクッキリ光る「タリーランプ」を装備！しかもただの裸のLEDではなく、どの角度から見ても均一に光る小さなプリズム拡散レンズと、暗闇でピントを助ける前側のフレネル集光レンズが組み込まれています！","summary":"動画収録中ステータスを被写体側（前面）および撮影者側（背面）へ同時通知する高視認性赤色タリーLED＋フロストポリカーボネート拡散プリズム、および前面暗所AF補助光用フレネル集光レンズモジュールです。","opticsAndPhysics":["前面タリー／セルフタイマーランプは、高輝度赤色LEDの点光源を微細プリズム拡散レンズで広角（±70°以上）へ均一拡散させ、自撮りやインタビュー時の被写体が離れた位置からでも録画中をひと目で確認できます。","背面タリーランプはファインダーやモニターの周辺視野に入る位置へ配置され、撮影者が画面の細部を見ながらでも「録画中（REC）」を無意識に確信できます。","併設のAF補助光（オレンジ・赤色LED）は薄型フレネルレンズで前方約3m先へ光を効率よく集光し、真っ暗な室内でのコントラストAF・顔検出を強力にアシストします。"],"formula":{"expression":"FOV_tally > 140° (プリズム広角拡散)  ＋  I_AF_assist = G_Fresnel · I_LED","description":"タリーランプはプリズムで広く見やすく広げ、AF補助光はフレネルレンズで遠くまで明るく届ける正反対の光学設計です。"},"nextGenInnovation":"最新ハイブリッド機では、前面・背面のタリーランプをメニューから個別にON/OFF可能とし、野生動物撮影や舞台撮影では完全消灯しつつ、ワンマンYouTube/シネマ撮影では確実なREC確認を行えます。","specs":[{"label":"タリー配置","value":"前面（被写体向け）＋背面（撮影者向け）デュアル高輝度赤色LED"},{"label":"光学カバー","value":"耐候フロストPC広角拡散プリズム＋防水Oリング密閉ベゼル"},{"label":"AF補助光","value":"薄型光学フレネル集光レンズ（暗所約 0.3〜3.0 m 照射）"},{"label":"誤撮防止","value":"ワンマン動画・インタビュー撮影での「押し忘れ」事故をゼロに"}],"diagramType":"body_tally_lamp_diffuser"},{"id":"body-exp-dial-lock-btn","order":72,"swatchColor":"#eab308","groupKey":"個別微細層_B72_カバンの中で露出が勝手にズレる悲劇をワンタッ","assembledPos":[-43,38.6,-15],"explodeOffset":[-64,88,-32],"integratedExplodeOffset":[-64,88,-32],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B72. 露出補正／カスタムRダイヤル・中央プッシュトグルロック機構（ハートカムプランジャー＆バネ）","subtitle":"Exposure / Custom-R Dial Center Push-Toggle Lock Button, Heart-Cam Plunger & Return Spring","category":"個別微細層 B72 — カバンの中で露出が勝手にズレる悲劇をワンタッチで防ぐ「ノック式ロック機構」","plainAnalogy":"カメラを肩に掛けて歩いていたら、服に擦れて露出補正ダイヤルがいつの間にか「+2.0」に回って写真が真っ白になっていた…カメラ好きなら誰もが一度は経験する悲劇です！Sony α7 IV以降のRダイヤルは中央に「ノック式ボールペンと同じ仕組みのロックボタン」を内蔵！1回カチッと押すとロック、もう1回押すと解除でき、親指1本で勝手に回る悲劇を完全に防げます！","summary":"トップデッキ右後方の露出補正／カスタムRダイヤル中央に内蔵された、プッシュ・プッシュ（オルタネート動作）式ハートカムロックプランジャー、ステンレス係合ロックピン、および復帰コイルバネ機構です。","opticsAndPhysics":["ボールペンのノック機構と同じ「ハート型カム溝（ハートカム）」＋追従ピンを直径わずか数ミリのダイヤル軸中心に超小型化して組み込み、押すたびに「押し込みロック（回転固定）」と「ポップアップ解除（自由回転）」を交互に切り替えられます。","ロック時はプランジャー下端のステンレス係合歯がボディ側の固定セレーションへ噛み合い、カバンや衣服との強い擦れトルクでもダイヤルが1クリックたりとも動きません。","ボタン周囲には極小のシリコーン防塵Oリングを備え、ダイヤル中心の押しボタン隙間からの雨水浸入も防いでいます。"],"formula":{"expression":"State_{n+1} = Toggle(State_n)   (ハートカムで 1プッシュ＝ロック／解除を交互切替)","description":"ボールペンと同じハート型の溝の仕掛けで、押すたびに「回らないロック状態」と「回る状態」を片手で切り替えられます。"},"nextGenInnovation":"α7 IVから従来の「±3刻印入り固定露出ダイヤル」が無刻印＋プッシュロック付きカスタムRダイヤルへ進化し、ISO感度やWB変更など好きな機能を誤操作ゼロで割り当てられるようになりました。","specs":[{"label":"切替方式","value":"オルタネート動作（プッシュ・プッシュ）超小型ハートカム機構"},{"label":"構成部品","value":"中央プッシュボタン・ハートカム軸・SUS係合ロック爪・復帰コイルバネ"},{"label":"防水対策","value":"ボタン軸周回 極小シリコーンOリング防滴シール"},{"label":"実用効果","value":"携行・衣服擦れによる意図しない露出／ISOズレ事故を完全防止"}],"diagramType":"body_exp_dial_lock_btn"},{"id":"body-sv-dial-fpc-cover","order":73,"swatchColor":"#6366f1","groupKey":"個別微細層_B73_モードダイヤルの真下で雨水とホコリをブロック","assembledPos":[-24,35.6,-6],"explodeOffset":[-34,96,-24],"integratedExplodeOffset":[-34,96,-24],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B73. Sony純正 SV DIAL FPC COVER（Ref.310: A5038708A）＆ モードダイヤルブロック MD DIAL BLOCK ASSY（Ref.323）","subtitle":"Sony OEM Splash-Proof SV Dial FPC Cover (Ref.310) & Sealed Mode Dial Block Assy (Ref.323)","category":"個別微細層 B73 — モードダイヤルの真下で雨水とホコリをブロックする「防滴ドーム＆密閉ロータリー部」","plainAnalogy":"カメラの上面にあるモードダイヤル（M・A・S・Pなど）は、上から降ってくる雨がまっすぐ当たる場所です。しかもダイヤルはクルクル回るためどうしてもわずかなスキマができます。そこでSony純正では、ダイヤルの下にある電気スイッチ本体（MD DIAL BLOCK）の周りに専用の「傘みたいな防滴カバー（SV DIAL FPC COVER）」を被せて、万一水が入っても電気回路にかからないように守っています！","summary":"Sony ILCE-7M4 公式サービスマニュアル CABINET TOP SECTION-2 Ref.310（A5038708A: SV DIAL FPC COVER）および Ref.323（A5033617A: MD DIAL BLOCK ASSY）に対応する、トップモードダイヤル直下の密閉ロータリースイッチ＆防滴保護カバーです。","opticsAndPhysics":["MD DIAL BLOCK ASSY（Ref.323）は、多極金メッキ摺動接点ブラシとグレイコード接点パターンをコンパクトな密閉ドラムへ収めた高信頼ロータリーエンコーダモジュールで、電源OFF中でも物理的なモード位置を確実に記憶します。","その直下・側方を覆う SV DIAL FPC COVER（Ref.310）が、ダイヤル隙間を通過した微細な水滴やホコリからFPC配線および接点部を保護する防滴シールド（スプラッシュガード）として機能します。","静止画／動画／S&Q切替リング（B45）の防水クッション（Ref.322）と組み合わさることで、上面最大の回転操作部でも高い防塵防滴信頼性を達成しています。"],"formula":{"expression":"Gray Code 4-bit (隣接変化1bitのみ)  ⇒  モード切替時の誤認識（グリッチ）ゼロ","description":"回したときに隣り合うモード同士で信号が1か所しか変わらない工夫（グレイコード）で、素早く回しても絶対に誤作動しません。"},"nextGenInnovation":"モードダイヤルと下段の静止画／動画／S&Q切替ダイヤルを同軸2重構造にしながら、電気接点ブロックと防滴カバーをユニット化したことで、狭い軍艦部スペースに多機能を凝縮しています。","specs":[{"label":"Sony純正品番①","value":"Ref.310 / Part No. A5038708A (SV DIAL FPC COVER 891 S)"},{"label":"Sony純正品番②","value":"Ref.323 / Part No. A5033617A (MD DIAL BLOCK ASSY 89100)"},{"label":"検出方式","value":"密閉ドラム型 多極金メッキ接点グレイコード・ロータリースイッチ"},{"label":"保護機能","value":"上面モードダイヤル隙間からの雨滴・砂埃スプラッシュ遮断"}],"diagramType":"body_sv_dial_fpc_cover"},{"id":"body-rear-ftb-wp-cushions","order":74,"swatchColor":"#0f172a","groupKey":"個別微細層_B74_外装の_3枚がぶつかる角っこ_の極小スキマを","assembledPos":[0,0,0],"explodeOffset":[38,42,-52],"integratedExplodeOffset":[38,42,-52],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B74. Sony純正 3面合わせ目防水クッション群（Ref.51 REAR FRONT WP / Ref.74 REAR FTB WP / Ref.254 AF CUSHION）","subtitle":"Sony OEM 3-Way Shell Junction Waterproof Foam Dams (Ref.51, Ref.74 & Ref.254 Cushions)","category":"個別微細層 B74 — 外装の「3枚がぶつかる角っこ」の極小スキマを塞ぐSony純正・防水ダム群","plainAnalogy":"カメラの外装は「前フタ」「上フタ」「後ろフタ」の3つの大きなパーツが組み合わさっています。まっすぐな辺はゴムパッキンで塞げますが、実は一番水が漏れやすいのが「3枚のフタがT字にぶつかる角っこ（三叉路）」なのです！そこでSony純正では、その角っこ専用の特注サイズ防水スポンジ（Ref.51 / 74 / 254）をピンポイントで詰め込み、360度スキマなしの防塵防滴を完成させています！","summary":"Sony ILCE-7M4 公式サービスマニュアル CABINET REAR-1 Ref.51（501034701: REAR FRONT WP CUSHION）、Ref.74（502862901: REAR FTB WP CUSHION）および CABINET TOP-1 Ref.254（501141301: AF CUSHION）に対応する、外装三叉路接合部の専用防水圧縮ダム群です。","opticsAndPhysics":["フロント・トップ・リアの各マグネシウム外装カバーが交わる3面接合部（Tジャンクション）は、通常の線状ガスケットだけではコーナー部に0.2mmほどの微小な三角隙間（ピンホール）が生じやすい構造的弱点です。","独立気泡EPDM／高密度ウレタン防水クッションを3か所の接合要所に40%圧縮で充填配置することで、ピンホールを完全に塞ぎつつ外装カバー同士の微細なカタつきも抑えます。","Kolari Vision等の分解でも「裏パネルやトップカバーのフチ沿いに細かく貼られた黒い防水シーリング材」として確認される、まさに防塵防滴の影の立役者です。"],"formula":{"expression":"T-Junction Gap (0.2 mm)  +  Compressed Closed-Cell Foam (40%)  ⇒  ピンホール 0","description":"3枚のカバーがぶつかる角の極小スキマを、水を吸わない独立気泡スポンジでギュッと埋めて完全封鎖します。"},"nextGenInnovation":"各接合部の隙間幅（0.5〜1.5mm）に合わせて厚みや発泡硬度を個別に変えた多点ダイカットクッション設計により、ねじ締めトルクを上げずに高い防水シール性を実現しています。","specs":[{"label":"Sony純正品番①","value":"Ref.51: 501034701 (REAR FRONT WP CUSHION 850)"},{"label":"Sony純正品番②","value":"Ref.74: 502862901 (REAR FTB WP CUSHION 89100)"},{"label":"Sony純正品番③","value":"Ref.254: 501141301 (AF CUSHION 850)"},{"label":"役割","value":"前・上・後外装カバー3面T字接合部の微小ピンホール防水封鎖"}],"diagramType":"body_rear_ftb_wp_cushions"},{"id":"body-battery-cell-safety","order":75,"swatchColor":"#10b981","groupKey":"個別微細層_B75_バッテリーの中身を解剖_発火やショートを4重","assembledPos":[-54,-8.5,5],"explodeOffset":[-94,-54,48],"integratedExplodeOffset":[-94,-54,48],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B75. リチウムイオン電池パック内部・PTC過電流遮断素子・CID圧力安全弁＆セル壁NTC温度保護基板","subtitle":"NP-FZ100 Internal 2S1P Li-Ion Safety Architecture (PTC Thermal Fuse, CID Vent, Cell NTC & Dual-MOSFET BMS)","category":"個別微細層 B75 — バッテリーの中身を解剖！発火やショートを4重に防ぐ小さな安全装置たち","plainAnalogy":"NP-FZ100バッテリーの黒いケースの中には、単3電池を少し大きくしたような高性能リチウムイオン電池が2本直列に入っています。小さな電池にスマホ並みの大エネルギーが詰まっているため、安全対策はなんと4重！①異常な大電流で熱くなると自動で電気を止める「PTC温度ヒューズ」、②内圧が上がると物理的に回路を切り離す「CID安全弁」、③電池にベタ付けの「温度センサー（NTC）」、④過充電・過放電を監視する「デュアルMOSFET保護基板」が毎日あなたを守っています！","summary":"7.2V / 2280mAh（16.4Wh）直列2セル（2S1P）リチウムイオンバッテリー（B01）の内部に組み込まれた、スポット溶接ニッケル接続タブ、復帰型PTC過電流保護素子、内圧遮断CID安全ベント、セル壁密着NTCサーミスタ、およびデュアルN-MOSFETセルバランス保護基板です。","opticsAndPhysics":["2本の3.6Vリチウムイオンセルを純ニッケル（Ni）スポット溶接タブで直列接続し、中央電位（3.6V）をBMS保護基板へ引き出すことで、2本の電池の充電バラツキを常時監視（セルバランス保護）しています。","万一端子ショート等で過電流や異常発熱が起きた場合、①電子保護（デュアルMOSFET遮断：数ミリ秒）→ ②熱保護（PTC素子の抵抗急増による電流制限）→ ③物理保護（セル内圧上昇でCID電流遮断ディスクが反転切離し＋ガス開放ベント）の多段フェイルセーフが作動します。","セル側面に耐熱テープで密着したNTCサーミスタが電池内部温度をカメラ本体へ常時報告し、0℃未満でのリチウム析出危険充電や45℃超での高温充電を自動停止します。"],"formula":{"expression":"4重保護 = MOSFET電子遮断 → PTC熱遮断 → NTC温度監視 → CID物理圧力切離し","description":"電気・熱・温度・圧力の4つの異なる仕組みで何重にも見張っているため、高出力バッテリーでも安心して毎日使えます。"},"nextGenInnovation":"純正インフォリチウム電池は残量1%刻み演算用のクーロンカウンター（電流積算IC）と暗号認証チップを同一BMS基板に搭載し、極寒環境でも残り撮影可能枚数を正確に予測できます。","specs":[{"label":"セル構成","value":"3.6V 高エネルギー密度リチウムイオンセル × 2直列（2S1P 7.2V / 16.4Wh）"},{"label":"保護素子①","value":"デュアル低オン抵抗MOSFET（過充電・過放電・短絡 瞬間遮断）"},{"label":"保護素子②","value":"復帰型PTCサーマルヒューズ ＋ セル内蔵CID内圧遮断安全ベント"},{"label":"温度・残量管理","value":"セル壁密着NTCサーミスタ ＋ 1%精度クーロンカウンターBMS基板"}],"diagramType":"body_battery_cell_safety"},{"id":"body-anti-twist-tripod-pin","order":76,"swatchColor":"#64748b","groupKey":"個別微細層_B76_雲台やケージの_クルッと緩み_を防ぐ底面ガイ","assembledPos":[0,-36.9,0],"explodeOffset":[16,-98,22],"integratedExplodeOffset":[16,-98,22],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B76. 底面ビデオ雲台回り止めボス・凹型シリアル／技適QR銘板プレート＆微細テクスチャ防滑ベースパッド","subtitle":"Bottom Baseplate Anti-Twist Alignment Pocket, Recessed Model/Serial/QR Nameplate & Anti-Slip Pad","category":"個別微細層 B76 — 雲台やケージの「クルッと緩み」を防ぐ底面ガイド＆シリアル銘板・滑り止めパッド","plainAnalogy":"カメラを三脚や動画用ケージにネジ1本だけで留めると、縦位置に傾けた瞬間に重さでカメラが「クルッ！」とお辞儀して緩むことがありますよね。カメラの底面には三脚ネジ穴のすぐ隣に雲台のピンがハマる回り止めガイド＆滑り止めパッドがあり、さらに底面を傷つけにくい一段凹んだ位置にモデル名・製造番号・技適マーク・QRコードが刻まれた銘板プレートが美しく収まっています！","summary":"ボトムカバー（B12）底面の1/4-20 UNC三脚ネジ穴周辺に配された、ビデオ雲台／ケージ用回り止め位置決めガイド面、微細シボ防滑プロテクターパッド、および一段凹型（リセス）アルミ／難燃ラベル銘板（モデル名・シリアル番号・電波認証・修理QR）です。","opticsAndPhysics":["カメラ底面の接触座面を三脚ネジ軸に対して極めて高い平面度（< 0.05 mm）で機械加工し、周囲に高摩擦・耐摩耗の微細テクスチャ防滑座を設けることで、クイックリリースプレート装着時の金属同士の焼き付き傷と回転緩みを防ぎます。","銘板プレートは底面外周より約0.4mm一段低く凹ませたポケット（リセス）へ貼付されており、テーブルや三脚プレートに何千回置いてもシリアル番号や技適・FCC/CE認証表示、製造トレーサビリティQRコードが擦れて消えません。","三脚穴周囲の肉厚座面がそのままメイン基板ヒートパイプ末端（M38）からの最終放熱面にもなっています。"],"formula":{"expression":"T_resist = μ_pad · F_bolt · r_eff + F_pin · L_pin   (摩擦＋回り止めピンで回転緩みゼロ)","description":"ネジの締め付け摩擦と回り止めガイドの組み合わせで、重いレンズを縦向きにしても三脚の上でカメラが回りません。"},"nextGenInnovation":"最新世代のボディでは、三脚ネジ穴周辺のフラット座面を広げつつ電池扉との干渉距離を最適化し、アルカスイス互換プレートを付けっぱなしでもバッテリー交換ができる実用配慮が施されています。","specs":[{"label":"座面構造","value":"高平面度三脚フランジ座＋ビデオ雲台回り止め位置決めガイド＆防滑パッド"},{"label":"銘板保護","value":"0.4 mm 凹型リセス（擦れ防止）アルミ蒸着シリアル・技適・QR銘板"},{"label":"実用配慮","value":"大型クイックリリースプレート装着時の傷防止・回転緩み低減"},{"label":"位置関係","value":"光軸直下 1/4-20 UNC 三脚座（B12/B35）隣接底面エリア"}],"diagramType":"body_anti_twist_tripod_pin"},{"id":"body-vl-ir-awb-sensor","order":77,"swatchColor":"#38bdf8","groupKey":"ボディ個別詳細層_B77_カメラ正面に付いた_光の色のソムリエ_","assembledPos":[-28,26.5,29.2],"explodeOffset":[-36,44,78],"integratedExplodeOffset":[-36,44,78],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B77. 前面「可視光＋赤外線（VL+IR）ホワイトバランスセンサー」＆ 窓プリズム（Sony α7R VI / α1 II）","subtitle":"Front-Facing Visible Light + Infrared (VL+IR) Ambient Color Metering Sensor Module","category":"ボディ個別詳細層 B77 — カメラ正面に付いた「光の色のソムリエ」。日陰や室内でも自然な肌色を守る専用センサー","plainAnalogy":"白いTシャツでも、夕日の下ではオレンジ色に、日陰では青っぽく見えます。人間の脳は勝手に「これは白だ」と補正しますが、カメラは迷いやすいのが弱点でした。そこでカメラ正面に、人間の目に見える光だけでなく「見えない赤外線」まで測れる小さな専用の目（VL+IRセンサー）を搭載！太陽光か室内LEDかを瞬時に見抜き、AIと一緒にいつでも自然な肌色・白色に整えてくれます。","summary":"Sony α7R V／α1 II／α7R VI（2026年5月発表）のボディ前面上部へ新設された、可視光（RGB）と近赤外線（IR）の比率を同時に測光する専用環境光センサーモジュール。ディープラーニング光源推定と連携し、日陰・混在光・逆光でのオートホワイトバランス（AWB）精度を劇的に高めます。","opticsAndPhysics":["太陽光には豊富な近赤外線（IR）が含まれますが、屋内のLED照明や蛍光灯にはほとんどIRが含まれません。このセンサーが「可視光とIRのバランス」を直接測定することで、レンズ越しの画像だけでは区別しにくい「日陰の太陽光」と「青いLED照明」を確実に判別できます。","窓部にはワイドな視野角を持つ乳白色ディフューザー付き光学プリズムと防水Oリングが組み込まれており、画面外から差し込む環境光のスペクトルを均一にサンプリングします。","ソニーα1 II／α7R VIではこの測光データをAIプロセッシングユニットへ送り、顔が逆光で暗い場面や日陰のポートレートでもホワイトバランスと露出安定性を約20%向上させています。"],"formula":{"expression":"比 R_IR/Vis = I(850nm) / I(RGB)  ⇒  太陽光・白熱灯・LEDを瞬時判別しAI-AWB補正","description":"目に見える光と見えない赤外線の比率を測ることで、その場の照明の正体を見破って正しい色味に直す"},"nextGenInnovation":"従来は撮像センサーの絵柄だけから推測していた色温度判定を「専用フロント分光センサー＋AI」の二段構えに進化させた、2025–2026年ソニー最新世代ボディの象徴的ハードウェアです。","specs":[{"label":"検出波長帯","value":"可視光 RGB ＋ 近赤外線（IR）同時分光フォトダイオード"},{"label":"搭載位置","value":"ボディ前面上部（レンズマウント斜め上・防水窓内蔵）"},{"label":"主な効果","value":"日陰・ミックス光・LED下での自然な肌色＆AWB安定性向上"},{"label":"採用機種例","value":"Sony α7R V / α1 II / α7R VI（2026）"}],"diagramType":"body_vl_ir_awb_sensor"},{"id":"body-front-ir-remote-window","order":78,"swatchColor":"#9f1239","groupKey":"ボディ個別詳細層_B78_グリップ正面に埋め込まれた_リモコン専","assembledPos":[-52,14.5,28.8],"explodeOffset":[-88,22,74],"integratedExplodeOffset":[-88,22,74],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B78. 前面赤外線リモート受光窓（IRレシーバー光学フィルタ＆フォトダイオード基板）","subtitle":"Front Grip Infrared Remote Receiver Window (850/940nm Bandpass Filter & Photodiode PCB)","category":"ボディ個別詳細層 B78 — グリップ正面に埋め込まれた「リモコン専用の見えない窓」。三脚撮影をブレゼロで切る受光部","plainAnalogy":"テレビの前面にある「黒くてツヤツヤした小さな窓」と同じ部品です！カメラを三脚に立てて集合写真や夜景を撮るとき、手でシャッターを押すとカメラが少し揺れてしまいます。この赤い光だけ通す特殊な窓が、離れた場所からのリモコンの「見えない赤外線合図」をキャッチして、カメラに一切触れずにシャッターを切ってくれます。","summary":"右手グリップ正面の上部に埋め込まれた、可視光を遮断し940nm帯の赤外線リモコン信号のみを透過させる暗赤色IRパス光学ウィンドウと、内蔵アンプ付きIR受光フォトダイオード（RMT-DSLR2／スタジオ無線トリガー対応）モジュール。","opticsAndPhysics":["受光窓の樹脂は人間の目には真っ黒〜濃いワインレッドに見えますが、波長850〜950nmの赤外線に対しては85%以上の高透過率を持つ光学バンドパスフィルターになっています。","周囲の太陽光や室内照明のノイズと区別するため、リモコン信号は38〜40kHzの高速点滅（キャリア変調）で送られ、受光IC内のバンドパス復調回路だけが正規のシャッター命令を取り出します。","グリップの曲面に合わせて防水シールパッキンで密着固定されており、雨天の屋外タイムラプス撮影でも内部へ水を通しません。"],"formula":{"expression":"λ_pass ≈ 940 nm（可視光カット） ＋ 搬送波 f_c = 40 kHz 復調 ⇒ 誤動作ゼロの遠隔レリーズ","description":"可視光を遮る黒い窓と40kHzの合言葉チェックで、強い日差しの下でもリモコン命令だけを確実に受け取る"},"nextGenInnovation":"Bluetoothリモコンが普及した現在でも、ペアリング不要・電池持ち数年・複数台同時レリーズ可能な赤外線受光部はスタジオや星空タイムラプス現場で根強く重宝されています。","specs":[{"label":"光学窓特性","value":"可視光遮断・940nm近赤外線透過アクリルレンズ"},{"label":"変調周波数","value":"38 〜 40 kHz 変調パルス復調IC内蔵"},{"label":"受光視野角","value":"水平 ±45° / 垂直 ±35°（到達距離 約5〜7m）"},{"label":"防水構造","value":"グリップ前壁埋込＆全周シリコーンガスケット密閉"}],"diagramType":"body_front_ir_remote_window"},{"id":"body-bodycap-alc-b1em","order":79,"swatchColor":"#334155","groupKey":"ボディ個別詳細層_B79_レンズを外したとき繊細なイメージセンサ","assembledPos":[0,0,30.8],"explodeOffset":[0,4,96],"integratedExplodeOffset":[0,4,96],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B79. 純正バヨネット保護ボディキャップ CAP, BODY（Sony Ref.551: 418853601 / ALC-B1EM）","subtitle":"OEM E-Mount Bayonet Protective Body Cap (Ref.551: 418853601 / ALC-B1EM)","category":"ボディ個別詳細層 B79 — レンズを外したとき繊細なイメージセンサーとシャッター幕を守る「精密バヨネットのフタ」","plainAnalogy":"レンズを外したカメラの中は、ホコリ1粒でも写り込んでしまう超繊細なイメージセンサーが丸見えの状態です。このボディキャップは、レンズと同じ「3本のツメ（バヨネット）」でカチッとひねって確実にロックする専用のフタ。移動中にカバンの中でホコリや指がセンサーに触れるのをしっかり防ぎ、裏面の段差構造でゴミの侵入も食い止めます。","summary":"Sony ILCE-7M4公式サービスマニュアル MB N FRAME UNIT SECTION Ref.551（純正品番 `418853601`：市販名 `ALC-B1EM`）として登録されている、Eマウント用3爪バヨネットロック式ボディ保護キャップ。","opticsAndPhysics":["レンズマウントの3枚の金属板バネ（リーフスプリング）と噛み合う精密な3爪フランジを備え、約60°ひねるだけで一定の押し付け圧を保ちながら脱落を防ぎます。","キャップ外周には滑り止めローレット溝（ギザギザ）が刻まれており、手袋をした冬場や暗いスタジオでも片手で素早く開閉できます。","帯電防止剤を配合したABS/PC樹脂成型により、キャップの内側へホコリが静電気で吸い寄せられてセンサー上へ落ちる二次汚染を抑えています。"],"formula":{"expression":"3爪バヨネット係合（回転角 ≈ 60°） ＋ 帯電防止樹脂 ⇒ 輸送時のホコリ・衝撃からセンサー完全隔離","description":"レンズと同じ3本のツメでカチッと固定し、静電気ホコリや不意の接触からカメラの心臓部を守る"},"nextGenInnovation":"ソニーα7 IV以降の「電源OFF時シャッター閉幕機能（防塵幕）」とこのボディキャップの二重防御により、屋外のレンズ交換・運搬時のセンサークリーニング頻度を大幅に減らしています。","specs":[{"label":"Sony純正品番","value":"Ref.551: 418853601（市販型番 ALC-B1EM）"},{"label":"固定方式","value":"Eマウント 3爪バヨネット回転ロック（約60°）"},{"label":"材質特性","value":"帯電防止・低発塵 ABS/ポリカーボネート成型"},{"label":"保護対象","value":"35mmフルサイズセンサー・シャッター幕・10ピン接点"}],"diagramType":"body_bodycap_alc_b1em"},{"id":"body-sorplas-sereebo-liner","order":80,"swatchColor":"#10b981","groupKey":"ボディ個別詳細層_B80_廃棄プラスチックから生まれた_鉄並みに","assembledPos":[-6,0,-24.5],"explodeOffset":[24,18,-94],"integratedExplodeOffset":[24,18,-94],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B80. 再生難燃樹脂 SORPLAS™ 内部構造ライナー ＆ 炭素繊維複合 Sereebo® 補強シェル","subtitle":"Sony Recycled SORPLAS™ Internal Structural Liner & CFRP Sereebo® Hybrid Composite Shell (2024–2026)","category":"ボディ個別詳細層 B80 — 廃棄プラスチックから生まれた「鉄並みに頑丈でエコな次世代ボディ素材」の内部補強殻","plainAnalogy":"「リサイクル素材＝安っぽくて弱い」という常識を覆す最先端素材です！ソニーのカメラ内部には、工場の廃材や使用済み光学ディスクから生まれた独自再生プラスチック「SORPLAS（ソープラス）」が使われ、CO₂排出を72%も減らしながら新品同等の強度と燃えにくさを実現。さらに最新フラッグシップ界（Nikon Z8等）では、カーボン繊維入りの超軽量素材「Sereebo」とマグネシウムを組み合わせ、軽くてビクともしないボディを作っています。","summary":"Sony α7 IV／α1 II／FX30等で外装・内装部品へ積極採用されている最大99%再生材使用の難燃性ポリカーボネート「SORPLAS™」、および最新軽量フルサイズ機（Nikon Z8等）が採用する帝人製炭素繊維強化熱可塑性複合材「Sereebo®」を体現した内部ハイブリッド補強ライナー。","opticsAndPhysics":["ソニー独自の難燃剤技術により、SORPLAS™は最大99%ものリサイクル材を含みながら、バージン樹脂比で製造時CO₂を約72%削減しつつ99%の機械的強度・高い耐熱性・繰り返しリサイクル性を維持します（過去12年間でカメラ製品群だけで約426トンの新規プラスチックを代替）。","マグネシウム合金の前面マウント骨格（絶対的な光学精度が必要な部位）と、炭素繊維強化複合材（Sereebo®：金属並みの比剛性＋優れた電磁波透過性）やSORPLAS内部ライナーを適材適所で組み合わせることで、軽量化・高剛性・無線アンテナ感度向上を同時達成します。","金属よりも熱伝導が穏やかな複合樹脂ライナーをグリップや背面内側に挟むことで、8K動画撮影時の内部熱が撮影者の手へ直接伝わりにくい「低温やけど防止断熱バリア」としても働きます。"],"formula":{"expression":"Mg前面骨格（高剛性） ＋ SORPLAS/CFRP複合ライナー（CO₂ −72%・軽量・断熱・電波透過）","description":"力がかかる前面はマグネシウム、軽さ・断熱・電波透過が必要な内部と外周は最先端エコ複合材で支える"},"nextGenInnovation":"ソニー「Road to Zero（2050年環境負荷ゼロ）」と最先端カーボン複合加工が融合した、2024–2026年カメラボディ設計の最も重要なマテリアル革命です。","specs":[{"label":"Sonyエコ素材","value":"SORPLAS™（再生材率最大99%・製造CO₂ 約72%削減）"},{"label":"先端CFRP比較","value":"炭素繊維強化複合材（帝人 Sereebo® 等：高比剛性）"},{"label":"実績削減量","value":"ソニーカメラ製品群で累計 約426トン新規樹脂削減"},{"label":"副次メリット","value":"軽量化・手の低温やけど断熱・Wi-Fi電波透過性向上"}],"diagramType":"body_sorplas_sereebo_liner"},{"id":"body-front-grip-thumb-insert","order":81,"swatchColor":"#64748b","groupKey":"ボディ個別詳細層_B81_重い望遠レンズを片手で持っても手が痛く","assembledPos":[-53.5,-2.5,11.5],"explodeOffset":[-96,-8,62],"integratedExplodeOffset":[-96,-8,62],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B81. ディープグリップ内部エルゴノミクス骨格リブ ＆ 薬指・小指ホールド成形コア（Sony α9 III / α1 II世代）","subtitle":"Deep-Grip Internal Ergonomic Rib Core & Finger-Well Load-Bearing Insert (α9 III / α1 II Gen)","category":"ボディ個別詳細層 B81 — 重い望遠レンズを片手で持っても手が痛くならない、グリップの中に隠れた「人間工学の骨組み」","plainAnalogy":"カメラを握る右手グリップは、表面のゴムの下が空っぽなわけではありません！最新のα9 IIIやα1 IIでは、1.5kgを超える大口径望遠レンズを付けたまま何時間も撮っても手が疲れないよう、中指・薬指・小指が吸い付く深いくぼみ形状と、指の握力をしっかり受け止めてたわみをゼロにする格子状の補強骨格（リブコア）がグリップ内部にびっしり仕込まれています。","summary":"Sony α7 IVからα9 III・α1 II・α7R VIへと進化を遂げた「ディープ・エルゴノミクスグリップ」の内部構造。電池室壁面と外皮ラバーの間に配置され、中指フックのくぼみ形状とねじり剛性を支える高強度リブ付き成形インナーコア。","opticsAndPhysics":["大口径レンズ（例：FE 300mm F2.8 GMや28-70mm F2 GM）装着時は重心が大きく前方へ移動するため、右手グリップには強い「前倒れモーメント（ねじり荷重）」がかかります。","α9 III／α1 II世代ではシャッターボタンの傾き角度を前方へ最適化し、グリップ内側へ中指が深く掛かるアンダーカット形状と内部ハニカムリブを設けることで、少ない握力でもブレずに構えられるエルゴノミクスを実現しました。","内部リブが外部からの衝撃（落下・打撲）を吸収して中に入っているリチウムイオン電池パック（B01）の変形を防ぐクラッシュクッションの役割も兼ねています。"],"formula":{"expression":"M_grip = F_lens × L_cg  ⇒  中指フック深堀り＋内部格子リブで握力負担を約25%軽減","description":"重いレンズで前に傾く力を、指が引っかかる深いカーブと内部の丈夫な格子骨格でラクに支える"},"nextGenInnovation":"シャッターボタン角度・前面C5ボタン位置・深い指掛かりを一体設計した最新エルゴノミクス骨格により、縦グリップ無しでも超望遠レンズを軽快に振り回せます。","specs":[{"label":"構造形状","value":"中指アンダーカット＋多段格子補強リブ内蔵コア"},{"label":"保護機能","value":"バッテリー室側面クラッシュ衝撃緩衝フレーム"},{"label":"対応エルゴ設計","value":"Sony α7 IV → α9 III / α1 II / α7R VI 改良グリップ"},{"label":"効果","value":"重量級レンズ装着時の長時間ホールド疲労軽減"}],"diagramType":"body_front_grip_thumb_insert"},{"id":"body-deep-eyecup-ep21","order":82,"swatchColor":"#1e293b","groupKey":"ボディ個別詳細層_B82_晴天の屋外でも横からのまぶしい光をピタ","assembledPos":[0,47.5,-36.5],"explodeOffset":[0,62,-78],"integratedExplodeOffset":[0,62,-78],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B82. 着脱式ディープアイピースカップ EYE CUP ASSY（Sony Ref.5: X50009261 / α1 II付属 FDA-EP21）","subtitle":"Removable Soft-Silicone Deep Eyepiece Cup & Snap-Lock Rail (Ref.5: X50009261 / FDA-EP21)","category":"ボディ個別詳細層 B82 — 晴天の屋外でも横からのまぶしい光をピタッと遮断し、ファインダーに没入できる「目のクッション」","plainAnalogy":"夏の強い日差しの中でファインダーを覗くと、横から光が差し込んで画面が白っぽく見えにくくなります。このアイピースカップは、目元にやさしくフィットする柔らかいゴム製の「ひさし（シェード）」です。特に最新のα1 IIで標準付属になった深型カップ（FDA-EP21）は、メガネでも裸眼でも横からの光を完璧に遮り、映画館のようにクリアなファインダー映像に集中できます。","summary":"Sony ILCE-7M4公式サービスマニュアル OVERALL SECTION Ref.5（純正品番 `X50009261`：標準型 `FDA-EP19`）および α1 IIで標準同梱された深型アイピースカップ `FDA-EP21` に相当する、ソフトシリコーン製遮光カップ＆スプリングロック式スライド取付レール構造。","opticsAndPhysics":["外周の目当て部には柔らかく肌当たりの良い医療グレードに近いソフトシリコーンエラストマーを採用し、内側の硬質ポリカーボネート芯材と二色成形（インサート成形）で強固に一体化されています。","ファインダー外枠の左右レールへ上からスライドさせ、下端の2本の弾性ロック爪がカチッと引っ掛かる構造のため、バッグからの出し入れで不意に外れにくく、劣化時は工具なしで簡単に交換できます。","深型形状（FDA-EP21）は額や頬骨のカーブに沿って横光を遮断するため、9.44Mドット超高輝度EVFの黒の締まり（コントラスト）を屋外直射日光下でも100%引き出します。"],"formula":{"expression":"外光遮断シェード（深型FDA-EP21） ＋ 25mmハイアイポイント ⇒ 屋外直射下でもEVFコントラスト最大化","description":"柔らかい深型ゴムひさしが横からの太陽光をシャットアウトし、ファインダーの中をくっきり見やすくする"},"nextGenInnovation":"ユーザーの要望を受けてSony α1 IIから標準型（FDA-EP19）と深型（FDA-EP21）の両方が標準付属するようになり、プロスポーツ・野鳥撮影の視認性が一段と向上しました。","specs":[{"label":"Sony純正品番","value":"Ref.5: X50009261（FDA-EP19 / 深型 FDA-EP21）"},{"label":"成形構造","value":"硬質PC骨格 ＋ 軟質遮光シリコーン 二色成形"},{"label":"固定方式","value":"EVF枠スライドレール ＋ 下端ダブルスナップロック爪"},{"label":"効果","value":"屋外横光遮断・眼鏡傷防止・目元クッション保護"}],"diagramType":"body_deep_eyecup_ep21"},{"id":"body-diopter-dial-wp","order":83,"swatchColor":"#d97706","groupKey":"ボディ個別詳細層_B83_裸眼でもメガネでもファインダーのピント","assembledPos":[-21.5,48,-24.5],"explodeOffset":[-46,78,-58],"integratedExplodeOffset":[-46,78,-58],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B83. 視度調整ダイヤル CV DIOPTER ADJUST DIAL（Ref.2: 500367201）＆ 防水シート（Ref.301: 500374001）","subtitle":"External Diopter Adjustment Knurled Dial (Ref.2: 500367201) & Waterproof Barrier Sheet (Ref.301)","category":"ボディ個別詳細層 B83 — 裸眼でもメガネでもファインダーのピントを自分の目に合わせる「メガネ度数の調整ツマミ」","plainAnalogy":"近視や老眼の人が裸眼でファインダーを覗くと、画面の文字がボヤけて見えてしまいます。ファインダーのすぐ横に付いたこの小さなギザギザツマミをクルクル回すと、中のレンズが前後に動いて「カメラ側があなたの目の度数（−4.0〜＋3.0）に合わせてピント調整」してくれます！軸の裏側には雨の侵入を止める専用の防水シート（Ref.301）も挟まれています。","summary":"Sony ILCE-7M4公式サービスマニュアル OVERALL SECTION Ref.2（`CV DIOPTER ADJUST DIAL`：`500367201`）と CABINET TOP SECTION-2 Ref.301（`DIOPTER COVER WP SHEET B`：`500374001`）からなる、EVF視度調整機構の外部操作ノブ＆軸部防水シール構造。","opticsAndPhysics":["視度調整範囲は −4.0 m⁻¹（強い近視）〜 ＋3.0 m⁻¹（遠視・老眼）まで幅広くカバーし、内部のウォームカム／リードスクリューを介してEVF接眼レンズ群を数ミリ単位で精密に前後移動させます。","ツマミ外周には細かいローレット加工と節度あるクリック感（または引き出しロック機構）が与えられており、カバンの中で勝手に回ってピントがズレる誤操作を防ぎます。","ボディ外装を貫通する回転軸は雨水が入りやすい弱点ですが、裏面に専用ダイカットの防水シート（`500374001`）と軸シールOリングを配置することで防塵防滴性能を死守しています。"],"formula":{"expression":"視度範囲 D = −4.0 〜 +3.0 m⁻¹（ディオプター） ⇒ 内部接眼レンズを微動させ網膜へ鮮明結像","description":"横の小さなツマミを回すだけで、近視から遠視までどんな人の目にもファインダー文字をクッキリ合わせられる"},"nextGenInnovation":"超微細9.44MドットEVFの繊細なピントの山を裸眼で正確に見極めるために不可欠な、小さなツマミに防水・誤操作防止・精密ギアを凝縮したパーツです。","specs":[{"label":"Sony純正品番①","value":"Ref.2: 500367201（CV DIOPTER ADJUST DIAL）"},{"label":"Sony純正品番②","value":"Ref.301: 500374001（DIOPTER COVER WP SHEET B）"},{"label":"調整レンジ","value":"−4.0 〜 +3.0 m⁻¹（ディオプター）"},{"label":"防水機構","value":"貫通軸Oリング ＋ 背面専用防水バリアシート"}],"diagramType":"body_diopter_dial_wp"},{"id":"body-evf-eye-sensor-bezel","order":84,"swatchColor":"#7c3aed","groupKey":"ボディ個別詳細層_B84_顔を近づけた瞬間だけ自動でファインダー","assembledPos":[0,37.5,-34.2],"explodeOffset":[22,46,-78],"integratedExplodeOffset":[22,46,-78],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B84. EVFアイセンサー光学窓（Ref.117）・ES-1008基板（Ref.116）＆ 防塵プロテクタ（Ref.303）","subtitle":"OEM EVF Proximity Eye-Sensor Window (Ref.117), ES-1008 Flex (Ref.116), GND Sheet & EVF Protector (Ref.303)","category":"ボディ個別詳細層 B84 — 顔を近づけた瞬間だけ自動でファインダーを点ける「赤外線の見張り番」と防水窓ユニット","plainAnalogy":"カメラを顔に近づけてファインダーを覗くと、背面の大きな液晶画面がパッと消えて、自動でファインダーの中が光りますよね。それを感知しているのが、ファインダーのすぐ下にある小さな黒い窓！ここから目に見えない赤外線をそっと出し、「顔が2〜3cmまで近づいた！」と瞬時に気づいて画面を切り替え、電池の節約にも大貢献しています。","summary":"Sony ILCE-7M4公式サービスマニュアル CABINET REAR SECTION-2 Ref.114〜118（`EYE SENSOR WINDOW 501034401` / `ES-1008 FLEX A5022315A` / `ES GND SHEET 502997201` / `WP & RET CUSHION`）および TOP SECTION-2 Ref.303（`EVF PROTECTOR 502790801`）の完全統合モジュール。","opticsAndPhysics":["赤外線LED投光素子と受光フォトダイオードを1チップ化した近接センサーICが `ES-1008` フレキ基板上に実装され、顔やメガネからの反射赤外線強度をミリ秒単位で計測します。","光学窓（`501034401`）の周囲には防水クッション（`501034501`）と保持クッション（`501142001`）が二重に挟まれ、額の汗や雨が接眼部から基板へ浸入するのを防ぎます。","さらに `ES GND SHEET`（`502997201`）が静電気（顔や衣服からの静電放電ESD）をシャーシへ逃がし、上部側の `EVF PROTECTOR`（`502790801`）が外部衝撃からEVF光学ブロックを保護します。"],"formula":{"expression":"IR反射近接距離 d < 30 mm ⇒ 背面LCD消灯 ＆ EVF自動点灯（切替遅延 < 50 ms・省電力化）","description":"赤外線の跳ね返りで顔が近づいた瞬間を見抜き、0.05秒以下でファインダーと背面液晶を自動切り替えする"},"nextGenInnovation":"背面モニターを開いた状態での誤反応防止ロジックや、サングラス越しでも誤動作しない高ダイナミックレンジ近接検出へと洗練されています。","specs":[{"label":"Sony純正品番①","value":"Ref.116: A5022315A（ES-1008 FLEX） / Ref.117: 501034401"},{"label":"Sony純正品番②","value":"Ref.115: 502997201（ES GND） / Ref.303: 502790801"},{"label":"防水クッション","value":"Ref.114（RET CUSHION）＋ Ref.118（WP CUSHION）"},{"label":"役割","value":"EVF/LCD自動切替・顔からの静電気保護・EVF耐衝撃防護"}],"diagramType":"body_evf_eye_sensor_bezel"},{"id":"body-voice-memo-mic","order":85,"swatchColor":"#0ea5e9","groupKey":"ボディ個別詳細層_B85_騒がしいスタジアムでも撮影した写真へ_","assembledPos":[-28.5,29.5,-33.8],"explodeOffset":[-54,42,-88],"integratedExplodeOffset":[-54,42,-88],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B85. 背面口元専用「ボイスメモ・マイクロホン」音響チャンバー＆防風メッシュ（Sony α9 III / α1 II）","subtitle":"Dedicated Rear-Panel Voice Memo Microphone Chamber & Wind-Resistant Acoustic Mesh (α9 III / α1 II)","category":"ボディ個別詳細層 B85 — 騒がしいスタジアムでも撮影した写真へ「声のメモ」をくっきり吹き込める、カメラ背面の専用マイク","plainAnalogy":"スポーツや報道のカメラマンは、撮った直後に「背番号10番のゴール瞬間！」などと写真にメモを付けたいのですが、わざわざ文字を打つ時間はありません。最新のα9 IIIやα1 IIでは、カメラの「背面（ちょうど口元のすぐ目の前）」に専用の音声メモ用マイクを新設！大歓声のスタジアムでも自分の声だけをクリアに録音し、スマホアプリで自動文字起こしまでして編集部へ即送信できます。","summary":"Sony α9 IIIおよびα1 IIの背面パネルへ独立搭載された「ボイスメモ専用マイクロホン」モジュール。従来の前面動画用ステレオマイクとは別に、撮影者の口元方向へ指向性を向けた高S/N MEMSマイク＋防塵撥水音響メッシュ構造です。","opticsAndPhysics":["従来のカメラは上部・前面にマイクがあったため、背面側から話しかけるとカメラ自身のボディが壁になって声がこもり、周囲の歓声や風切り音に埋もれてしまいました。","背面の口元直近（約10〜20cmの至近距離）に専用ポートを設けることで、音圧が距離の二乗に反比例して稼げるため、騒音下でも圧倒的に高い音声S/N比（明瞭度）が得られます。","マイク孔の奥には撥水・防塵アコースティック不織布と防振ゴムブーツを挟み、息の吹きかかり（ポップノイズ）や雨滴の侵入を防ぎながらクリアな人の声帯域（300Hz〜4kHz）を通します。"],"formula":{"expression":"至近距離背面集音（口元 15 cm） ⇒ 騒音下S/N比大幅向上 ＋ IPTC音声タグ／自動テキスト変換FTP送信","description":"口元のすぐ前に専用マイクを置くことで、周囲の歓声に負けず自分の声だけをくっきり録音して写真に添付できる"},"nextGenInnovation":"撮った写真＋音声メモをそのまま2.5G LANや5GHz Wi-FiでFTP即納し、AI音声文字起こしで記事キャプションまで自動化する2025–2026年プロ報道ワークフローの核心パーツです。","specs":[{"label":"マイク素子","value":"背面専用・高S/N近接収音 MEMSマイクロホン"},{"label":"搭載位置","value":"カメラ背面パネル上部（撮影者の口元直近ポジション）"},{"label":"防塵防滴","value":"撥水アコースティックメッシュ＋防振シリコーンブーツ"},{"label":"採用機種例","value":"Sony α9 III / α1 II（報道・スポーツ即時納品対応）"}],"diagramType":"body_voice_memo_mic"},{"id":"body-joy-retainer-stack","order":86,"swatchColor":"#475569","groupKey":"ボディ個別詳細層_B86_親指でピント枠をグリグリ動かすスティッ","assembledPos":[-44,7.5,-33.8],"explodeOffset":[-66,20,-86],"integratedExplodeOffset":[-66,20,-86],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B86. AFジョイスティック4層防水サンドイッチ構造（JOY KNOB / RUBBER / RETAINER / HOLDER：Ref.70–73）","subtitle":"OEM Multi-Selector 4-Layer Weatherproof Sandwich Stack (Ref.70–73: 502794401 / 500389901 / A5014708A / 500390101)","category":"ボディ個別詳細層 B86 — 親指でピント枠をグリグリ動かすスティックを「雨とホコリから4重に守る」精密キャップ構造","plainAnalogy":"ゲームコントローラーのスティックのように360度グリグリ動く部品は、すき間ができやすく雨や砂が入りやすい場所です。そこでソニーの背面ジョイスティックは、親指が触れるギザギザの「ノブ」の下に、ジャバラ状に伸び縮みする「防水ゴムブーツ」、それをがっちり挟み込む「ステンレス押さえ板」、さらに土台の「ホルダー板」の4層サンドイッチで完璧に密閉しています！","summary":"Sony ILCE-7M4公式サービスマニュアル CABINET REAR SECTION-1 Ref.70〜73（`JOY RETAINER PLATE 502794401` / `JOY KNOB 500389901` / `JOY HOLDER PLATE A5014708A` / `JOY RUBBER 500390101`）の4層防塵防滴メカニカル・スタック。","opticsAndPhysics":["最外層の `JOY KNOB`（`500389901`）は親指の腹が滑らないピラミッド型マイクロローレット（格子凹凸）加工が施され、薄手の手袋越しでも8方向の操作ミスを防ぎます。","その直下の `JOY RUBBER`（`500390101`）は薄肉ベローズ（蛇腹）形状のシリコーン防水ブーツで、スティックを全方向へ傾けても裂けず・引っ張られず、水滴と砂埃の浸入路を完全に塞ぎます。","ゴムブーツの外周フランジを金属製の `JOY RETAINER PLATE`（`502794401`）と `JOY HOLDER PLATE`（`A5014708A`）で上下から均一に圧着固定することで、何十万回もの操作でも防水シールがズレない耐久性を確保します。"],"formula":{"expression":"4層密着構造：凹凸ノブ → 蛇腹防水ブーツ → SUS押さえ板 → 保持ベース ⇒ 全方向可動と防塵防滴を両立","description":"柔らかく伸びるゴムの蛇腹を金属プレートでサンドイッチすることで、自由に動かせるのに水が一切入らない"},"nextGenInnovation":"内部のスイッチ本体（B22）だけでなく外部の4層防水スタックまで独立交換できるモジュラー設計により、過酷な現場で長年酷使されても快適な操作感を維持できます。","specs":[{"label":"Sony純正品番①","value":"Ref.71: 500389901（JOY KNOB） / Ref.73: 500390101（RUBBER）"},{"label":"Sony純正品番②","value":"Ref.70: 502794401（RETAINER） / Ref.72: A5014708A（HOLDER）"},{"label":"防塵防滴方式","value":"薄肉ベローズ防水ブーツ＋金属プレート全周挟み込み"},{"label":"操作耐久","value":"全8方向＋中央押し込み 高頻度プロ操作対応"}],"diagramType":"body_joy_retainer_stack"},{"id":"body-media-lid-hinge-spring","order":87,"swatchColor":"#94a3b8","groupKey":"ボディ個別詳細層_B87_ロックを外した瞬間にカード扉が_スッ_","assembledPos":[-70,-5,-24],"explodeOffset":[-110,-22,-46],"integratedExplodeOffset":[-110,-22,-46],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B87. カード扉ステンレスヒンジ軸（Ref.120: 501035811）＆ 自動開放トーションバネ（Ref.121: 501035701）","subtitle":"OEM Memory Card Door Stainless Pivot Shaft (Ref.120: 501035811) & Pop-Open Torsion Spring (Ref.121: 501035701)","category":"ボディ個別詳細層 B87 — ロックを外した瞬間にカード扉が「スッ」と気持ちよく開く、極細ステンレス軸とバネの仕掛け","plainAnalogy":"メモリーカードを入れ替えるとき、ロックレバーを下にスライドすると扉が「カチャッ、スッ！」と心地よく自動で開きますよね。あの気持ちいい動きを作っているのが、扉の付け根に隠れた1本の精密なステンレスの心棒（シャフト）と、そこに巻き付いた小さなねじりバネ（トーションスプリング）です。何万回開け閉めしてもガタつかず、片手でも素早くカード交換ができます！","summary":"Sony ILCE-7M4公式サービスマニュアル CABINET REAR SECTION-2 Ref.120（`MEDIA LID SHAFT`：`501035811`）および Ref.121（`MEDIA LID ROTATION SPRING`：`501035701`）からなる、メモリーカードスロット扉の精密ヒンジ回転軸・自動開放スプリング機構。","opticsAndPhysics":["ステンレス鋼の精密研削ピン `MEDIA LID SHAFT`（`501035811`）が扉本体（`X50022791`）と背面ベース（`502794801`）を貫通し、ガタつき数十分の1mm以下の高精度な開閉軸を作ります。","軸に同軸装着された `MEDIA LID ROTATION SPRING`（`501035701`）は、扉を閉めた状態でわずかな蓄勢トルクを保っており、2アクションロック（B21）を解除した瞬間に扉を自動で跳ね上げます。","同時に、閉扉時はこのヒンジ軸と反対側のロックカムが防水ガスケット（B69 `GASKET MED`）を全周均等に圧縮する支点となるため、防塵防滴の気密安定性にも直結する重要部品です。"],"formula":{"expression":"トーションバネ復元トルク τ = k · Δθ  ⇒  ロック解除と同時に約95°へスムーズ自動開放","description":"閉めている間にバネに少しだけ力を溜めておくことで、ロックを外した瞬間に扉が気持ちよく自動で開く"},"nextGenInnovation":"従来の簡易樹脂ヒンジから金属軸＋精密ねじりバネ＋二重パッキン構造へ格上げされたことで、撮影現場の激しい連写カード交換でも折れ・緩みゼロの信頼性を誇ります。","specs":[{"label":"Sony純正品番①","value":"Ref.120: 501035811（MEDIA LID SHAFT）"},{"label":"Sony純正品番②","value":"Ref.121: 501035701（MEDIA LID ROTATION SPRING）"},{"label":"材質","value":"耐食・高耐摩耗 ステンレス鋼（SUS304 / ピアノ線）"},{"label":"動作特性","value":"ロック解除連動ポップオープン（開度 約95°）"}],"diagramType":"body_media_lid_hinge_spring"},{"id":"body-active-cooling-fan-duct","order":88,"swatchColor":"#06b6d4","groupKey":"ボディ個別詳細層_B88_水もホコリも電子回路に一滴も入れずに_","assembledPos":[22,12,-21.5],"explodeOffset":[68,34,-74],"integratedExplodeOffset":[68,34,-74],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B88. 防塵防滴「独立空冷マイクロブロワーファン ＆ 密閉アルミ熱交換トンネル」（FX3/FX5・LUMIX S1R II構造）","subtitle":"Weather-Sealed Isolated Active Cooling Micro-Blower Fan & Baffled Aluminum Heat-Exchanger Tunnel (2025–2026)","category":"ボディ個別詳細層 B88 — 水もホコリも電子回路に一滴も入れずに、8K動画の熱だけを風で追い出す「完全隔離エアコン」","plainAnalogy":"「冷却ファンを付けたら穴から雨やホコリが入っちゃうのでは？」と思いますよね。最新カメラ（Sony FX3/FX5やLUMIX S1R II等）のすごい発明は、風が通る「アルミのトンネル」と、電子基板が入った「カメラの中身」を壁で完全に隔離していること！熱だけを金属の壁越しにトンネルへ移し、極薄の静音ファンで外へ吹き飛ばすので、雨の中でも熱停止せず何時間でも8K動画を撮り続けられます！","summary":"Sony Cinema Line（FX3／2026年発表FX5）やPanasonic LUMIX S1R II／S5IIXが採用する、内部電子回路と物理的に完全隔離された密閉アルミ熱交換トンネル＆極薄遠心マイクロブロワーファン冷却ユニット。","opticsAndPhysics":["基板・センサー側の密閉コンパートメントと、外気が流れる冷却ダクトの間は継ぎ目のない一体成型アルミヒートシンク壁とシリコーンガスケットで完全に区切られており、ダクト内に水滴や砂塵が入っても基板へ一切到達しません。","超薄型（厚さ約4〜5mm）の多翼シロッコ（遠心）マイクロブロワーファンは流体軸受と低振動ブラシレスモーターを採用し、動画収録中でも内蔵マイクが拾わない極低騒音（約18〜22 dB）で連続排熱します。","4K 120pや8K RAW連続収録時に発生する10〜15W級の熱をリアルタイムで外気へ逃がすことで、真夏の屋外ロケでもサーマルシャットダウン無しの無制限連続録画を可能にします。"],"formula":{"expression":"Q_cool = ṁ_air · c_p · ΔT  （密閉アルミ隔壁で熱だけ伝導・水滴/塵の電子部侵入＝0）","description":"金属の壁を通して熱だけを風のトンネルへ移し、電子部品を濡らさずに静音ファンで外へ吹き飛ばす"},"nextGenInnovation":"2025–2026年のハイブリッド＆シネマカメラで標準化が進む「防塵防滴×アクティブ空冷」の両立構造。長時間ライブ配信や夏場の8Kワンオペ収録の常識を変えました。","specs":[{"label":"ファン形式","value":"極薄ブラシレス遠心マイクロブロワー（約18〜22 dB静音）"},{"label":"防水隔離構造","value":"基板側と完全別室の密閉アルミ熱交換ダクトトンネル"},{"label":"連続排熱能力","value":"8K/4K 60p〜120p 無制限連続収録対応"},{"label":"代表採用例","value":"Sony FX3 / FX5（2026） / LUMIX S1R II / S5IIX"}],"diagramType":"body_active_cooling_fan_duct"},{"id":"body-sigma-graphite-heatplate","order":89,"swatchColor":"#f97316","groupKey":"ボディ個別詳細層_B89_頭脳チップの熱を_金属板と熱伝導シート","assembledPos":[4,-3,-24],"explodeOffset":[28,-28,-86],"integratedExplodeOffset":[28,-28,-86],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B89. 純正放熱ブリッジ多層スタック：HEAT_PLATE（Ref.355）・熱伝導シートA（Ref.357）＆ 絶縁シートA/B（Ref.356/361）","subtitle":"OEM Mainboard Thermal Bridge Stack — HEAT_PLATE (Ref.355), Heat Transfer Sheet A (Ref.357) & Insulators A/B","category":"ボディ個別詳細層 B89 — 頭脳チップの熱を「金属板と熱伝導シート」でボディ全体へ素早く逃がす、電気もショートさせない断熱サンドイッチ","plainAnalogy":"動画撮影中、カメラの頭脳（BIONZ XR）は猛烈に熱くなります。そのままでは熱がこもって止まってしまうため、チップのすぐ裏に「柔らかい熱伝導シート」と「専用のアルミ放熱プレート（HEAT_PLATE）」を密着させて熱を吸い上げ、さらに金属板が基板と触れてショートしないよう「極薄の絶縁フィルムA/B」で安全に挟み込んだ、プロの放熱サンドイッチ構造になっています！","summary":"Sony ILCE-7M4公式サービスマニュアル MAIN BOARD SECTION Ref.355（`HEAT_PLATE 502789301`）、Ref.357（`HEAT TRANSFER SHEET A 502860201`）、および Ref.356／361（`INSULATING SHEET A 502992401` / `B 502992501`）からなる公式放熱＆電気絶縁サンドイッチ構造。","opticsAndPhysics":["メイン基板（SY-1122）の発熱源と `HEAT_PLATE`（`502789301`）の間を、柔軟な高熱伝導シート `HEAT TRANSFER SHEET A`（`502860201`）が空気層ゼロで隙間なく埋めます（空気は熱伝導率0.026 W/m·Kと断熱材並みのため、このシートの有無で温度が10°C以上変わります）。","放熱板の上下には精密打ち抜き加工されたポリカーボネート／マイラー製 `INSULATING SHEET A & B`（`502992401 / 502992501`）が貼られ、基板上のチップ部品やフレキ端子との電気的ショートを確実に防ぎます。","α7 IV・α7 V独自の「Σ（シグマ）字型グラファイト放熱構造」と連動して、イメージセンサーの揺れを妨げずにマグネシウム外装全面へ熱を均等拡散させます。"],"formula":{"expression":"R_th = t_pad / (k_pad · A) ↓  ⇒  空気層を排除しチップ熱をHEAT_PLATE経由で外装へ高速拡散","description":"熱を妨げるわずかな空気の隙間を柔らかいシートで埋め、電気ショートを防ぎつつ熱だけボディ全体へ逃がす"},"nextGenInnovation":"ファンレスの小型防塵防滴ボディでありながら、α7 IVの4K 60pやα7R VI（2026）の8K最大120分連続収録を支えるソニー伝家の宝刀パッシブ放熱設計です。","specs":[{"label":"Sony純正品番①","value":"Ref.355: 502789301（HEAT_PLATE） / Ref.357: 502860201"},{"label":"Sony純正品番②","value":"Ref.356: 502992401（INSUL A） / Ref.361: 502992501（INSUL B）"},{"label":"機能","value":"BIONZ XR熱結合拡散 ＋ 高耐圧ショート防止電気絶縁"},{"label":"連携構造","value":"ソニー独自 Σ（シグマ）字型グラファイト放熱経路"}],"diagramType":"body_sigma_graphite_heatplate"},{"id":"body-cfexpress-thermal-bridge","order":90,"swatchColor":"#3b82f6","groupKey":"ボディ個別詳細層_B90_超高速連写でアツアツになるメモリーカー","assembledPos":[-56,-5,-14],"explodeOffset":[-88,-32,-42],"integratedExplodeOffset":[-88,-32,-42],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B90. CFexpressカードスロット専用サーマルパッド＆マグネシウム放熱ヒートスプレッダ","subtitle":"CFexpress Type-A/B Card Cage Thermal Gap-Filler Pad & Chassis Heat-Spreader Bridge","category":"ボディ個別詳細層 B90 — 超高速連写でアツアツになるメモリーカードの熱を、ボディ側へ吸い出して速度低下を防ぐ冷却クッション","plainAnalogy":"最新のCFexpressカードはパソコンの超高速SSDと同じくらいのスピードでデータを書き込むため、8K動画や秒30コマ連写を続けるとカード自体がホッカイロのように熱くなります！熱くなりすぎると安全のため書き込み速度がガクンと落ちてしまうので、カードを入れる金属ケースのすぐ裏に「熱を吸い取る柔らかいクッション」を貼り、カードの熱をカメラの金属ボディ側へどんどん逃がしています。","summary":"CFexpress Type A / Type Bデュアルカードスロットの金属シールドケージ背面と、マグネシウムメイン骨格（B39）を熱結合する高コンプライアンス・シリコンサーマルギャップパッド＆銅箔放熱ブリッジ構造。","opticsAndPhysics":["PCIe Gen3/Gen4インターフェースで毎秒800〜1,900 MB/s超の連続書込みを行うCFexpressカードは、カード単体で2〜4W発熱し、放熱経路がない密閉スロット内では容易に75〜85°Cへ達してサーマルスロットリング（書き込み速度急減）を引き起こします。","カード挿入口の金属フレームとボディ骨格のわずかな隙間（1〜2mm）を、熱伝導率 3〜6 W/m·K の超柔軟ギャップフィラーパッドで密着橋渡しすることで、カード表面温度を10〜15°C低下させます。","同時に、カードの熱がすぐ隣にある右手グリップ外皮へ集中して熱くならないよう、熱拡散シートで底板・背面骨格側へ分散逃がしする熱設計が施されています。"],"formula":{"expression":"P_CFexpress ≈ 2〜4 W  →  サーマルパッド熱結合 → Mg骨格拡散（カード温度 −10〜15°C低減）","description":"超高速書き込みで熱くなるカードの熱を柔らかいパッドで金属ボディへ逃がし、連写や録画の途中停止を防ぐ"},"nextGenInnovation":"VPG200/VPG400規格の長時間8K RAW内部収録が当たり前になった2025–2026年フラッグシップ機で、SDカード時代には不要だった新たな必須熱設計パーツです。","specs":[{"label":"対象メディア","value":"CFexpress Type A / Type B 超高速PCIeメモリーカード"},{"label":"熱結合材","value":"高柔軟シリコン・サーマルギャップパッド（3〜6 W/m·K）"},{"label":"効果","value":"8K RAW / 30fps連写時のカード高温速度低下を防止"},{"label":"配置位置","value":"カードケージ内壁〜マグネシウムメインフレーム間"}],"diagramType":"body_cfexpress_thermal_bridge"},{"id":"body-external-cooling-vent-port","order":91,"swatchColor":"#0284c7","groupKey":"ボディ個別詳細層_B91_普段は雨を弾いて静かに放熱し_専用冷却","assembledPos":[34,-35.8,-14],"explodeOffset":[76,-78,-36],"integratedExplodeOffset":[76,-78,-36],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B91. 外部冷却グリップ連動エアフロー導風ルーバー＆撥水メッシュ吸排気口（Canon EOS R5 Mark II 拡張冷却構造）","subtitle":"Bottom-to-Side Cooling Grip Airflow Louver & Hydrophobic Mesh Intake/Exhaust Vent (EOS R5 Mark II Gen)","category":"ボディ個別詳細層 B91 — 普段は雨を弾いて静かに放熱し、専用冷却グリップを付けると「ターボ送風」できる拡張通気口","plainAnalogy":"普段の静止画撮影では静かでコンパクトなまま使いたいけれど、長時間の8K映画撮影のときだけ強力なファンで冷やしたい――そんな願いを叶えたのが最新の「外部冷却グリップ連動通気口」です！ボディの底と横に雨粒を通さない極細の網（撥水メッシュ）付き通気ルーバーを設けておき、別売りの冷却ファン付きグリップを底面にドッキングすると、ボディの中へ涼しい風を一気に送り込めます！","summary":"Canon EOS R5 Mark II（2024–2026）が初採用した、ボディ底面の吸気スリットから内部の独立ヒートシンク通路を通り左側面ルーバーへ抜ける「パッシブ／アクティブ切替式」外部冷却グリップ（CF-R20EP）連動エアフロー構造。","opticsAndPhysics":["通常使用時は底面〜側面ダクトを通る自然対流（煙突効果）でパッシブ放熱し、外部冷却ファン付きバッテリーグリップ（CF-R20EP等）を装着すると、底面吸気口へ強制送風して8K 60p RAWや4K 60pの連続撮影時間を数倍へ延長します。","吸排気スリットの内部にはステンレス微細メッシュ＋撥水フィルターが二重配置され、通気抵抗を抑えつつ小雨や砂埃の侵入をブロックします。","エアフロー経路自体が電子基板と密閉分離されているため、IP53級の防塵防滴性能を損なわずに「必要なときだけファンを後付けできる」画期的な拡張性を実現しています。"],"formula":{"expression":"通常＝自然対流パッシブ冷却  ／  冷却グリップ装着＝強制送風ダクト（8K連続収録時間を大幅延長）","description":"普段はファン無しの軽快ボディ、本気の動画ロケ時だけ底の通気口からファンで風を送り込める二刀流構造"},"nextGenInnovation":"「カメラ本体を厚く重くしたくない写真派」と「絶対に熱停止させたくない動画派」の双方を満足させる、2024–2026年ハイブリッドカメラの新しいボディ設計トレンドです。","specs":[{"label":"エアフロー経路","value":"底面吸気スリット → 内部密閉ダクト → 側面排気ルーバー"},{"label":"防塵防滴対策","value":"ステンレス微細メッシュ＋撥水エアフィルター＋密閉隔壁"},{"label":"拡張連携","value":"アクティブ冷却バッテリーグリップ（CF-R20EP等）直結"},{"label":"代表採用例","value":"Canon EOS R5 Mark II（2024–2026）"}],"diagramType":"body_external_cooling_vent_port"},{"id":"body-cable-protector-clamp","order":92,"swatchColor":"#64748b","groupKey":"ボディ個別詳細層_B92_つないだケーブルに足を引っかけても_端","assembledPos":[61,-2,-7],"explodeOffset":[108,-18,12],"integratedExplodeOffset":[108,-18,12],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B92. 純正脱着式 HDMI／USB-C ケーブルプロテクター（抜け・端子破損防止クランプ＆固定ネジ）","subtitle":"OEM Detachable HDMI / USB-C Cable Protector Strain-Relief Clamp & Captive Thumb Screw","category":"ボディ個別詳細層 B92 — つないだケーブルに足を引っかけても「端子がバキッと折れる悲劇」を防ぐ安全ストッパー","plainAnalogy":"スタジオ撮影や動画収録では、カメラの横に太いHDMIやUSBケーブルをつなぎっぱなしにします。うっかりケーブルを引っ張ってしまうと、抜けたり、最悪カメラ本体の端子が根元から折れて高額修理になってしまいます！このプロテクターはボディ左横の専用ネジ穴にガッチリ固定し、ケーブルを挟み込んで力をボディ側で受け止めてくれる「命綱クランプ」です。","summary":"Sony α7 IV／α9 III／α1 IIに標準付属し、左側面I/Oポート脇のステンレス補強ネジ座（B34）へ取り付ける純正脱着式ケーブルプロテクター（HDMI＆USB-C同時クランプ・抜け防止ブラケット）。","opticsAndPhysics":["クランプ本体がHDMIケーブルとUSB-Cケーブルの根元をコの字型スロットで挟み込み、ケーブルが引っ張られた際の引張力・曲げモーメントをメイン基板のハンダ付け部ではなく、強固なマグネシウム外装とステンレス補強枠へ逃がします。","コインや指で回せる脱落防止ローレットネジ（キャプティブスクリュー）を採用しており、撮影現場で素早く装着でき、ネジを紛失する心配もありません。","テザー撮影中のUSB切断によるデータ破損や、ライブ配信中のHDMIブラックアウト事故を物理的に防ぐ、プロ現場の必須安全パーツです。"],"formula":{"expression":"引張荷重 F_cable → クランプ経由で金属シャーシへ迂回 ⇒ 基板ハンダ部の破損応力 ≈ 0","description":"ケーブルが引っ張られた力を金属ボディ側で受け止め、繊細な端子や基板を根元破損から守る"},"nextGenInnovation":"外付けケージを買わなくても標準付属品だけでHDMI＆USB-Cの両方を同時ロックできる親切設計が、最新ソニーαフラッグシップ群の標準装備となっています。","specs":[{"label":"保護対象","value":"フルサイズHDMI ＋ USB Type-C ケーブル同時クランプ"},{"label":"取付方式","value":"ボディ左側面専用ネジ座＋脱落防止ローレットネジ"},{"label":"材質","value":"高剛性ガラス繊維強化ポリカーボネート＋ステンレスネジ"},{"label":"採用機種","value":"Sony α7 IV / α9 III / α1 II 標準付属"}],"diagramType":"body_cable_protector_clamp"},{"id":"body-dual-usbc-25g-lan-bay","order":93,"swatchColor":"#2563eb","groupKey":"ボディ個別詳細層_B93_充電しながら超高速データ転送_ができる","assembledPos":[51.5,-4.5,-8.5],"explodeOffset":[94,24,-26],"integratedExplodeOffset":[94,24,-26],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B93. 2026次世代プロI/Oベイ：デュアルUSB-C（給電＋データ同時）＆ 2.5GBASE-T有線LAN RJ-45強化ジャック","subtitle":"2026 Pro Dual USB-C (Simultaneous 100W PD + 10Gbps Data) & 2.5GBASE-T Ethernet RJ-45 Bay (α7R VI / α1 II / FX5)","category":"ボディ個別詳細層 B93 — 「充電しながら超高速データ転送」ができるUSB-C 2口と、光回線並みに速い有線LANポート","plainAnalogy":"昔のカメラはUSB-Cが1つしかなかったので、「パソコンへ写真を送るか、バッテリーを充電するか」でポートを取り合いがちでした。2026年の最新世代（Sony α7R VI／FX5やNikon Z8）はUSB-Cを2つ搭載し、片方で100W急速給電しながらもう片方で10Gbpsデータ転送やタイムコード同期を同時実行！さらにα1 IIは2.5ギガ有線LAN端子を備え、撮った写真を1秒以内に編集デスクへ飛ばせます。","summary":"Sony α7R VI（2026年5月）・FX5（2026年7月）のデュアルUSB Type-Cポート（USB-PD給電専用＋SuperSpeed USB 10Gbpsデータ／タイムコード対応）と、Sony α1 IIの2.5GBASE-T有線LAN（RJ-45）強化レセプタクルを統合した次世代プロI/Oベイ構造。","opticsAndPhysics":["2つのUSB-Cポートはそれぞれ独立した電源保護IC（ESDダイオード・過電圧保護）と金属EMIシールドシェルを備え、一方へUSB-PD 30〜100W電源をつないだまま、もう一方で10Gbps PCテザー転送・外付けSSD収録・タイムコード入力を干渉ゼロで並列稼働できます。","2.5GBASE-T有線LAN端子（RJ-45）は従来の1000BASE-T比で2.5倍の通信速度を誇り、内部にパルストランスと金属EMIスプリングフィンガーを組み込んで50MP〜67MP RAWの超高速FTP伝送やWake-on-LAN遠隔起動を支えます。","頻繁なケーブル抜き差しに耐えるため、全ポートの金属外殻をステンレス補強フレームへ直接レーザー溶接／ネジ固定して10,000回以上の挿抜耐久を確保しています。"],"formula":{"expression":"USB-C①（10Gbps転送/TC） ＋ USB-C②（USB-PD連続給電） ＋ 2.5GBASE-T LAN（最大2.5Gbps即納）","description":"給電用とデータ用の2つのUSB-Cと超高速2.5G有線LANで、電池切れも待ち時間もないプロ現場を実現"},"nextGenInnovation":"2026年最新のα7R VI・FX5でついにソニーαにも「デュアルUSB-C」が到来し、国際スポーツ報道・シネマ・スタジオ現場の接続ボトルネックを完全に解消しました。","specs":[{"label":"デュアルUSB-C","value":"SuperSpeed 10Gbps転送 ＋ USB-PD専用給電（2ポート独立）"},{"label":"有線LAN規格","value":"2.5GBASE-T（2.5Gbps）RJ-45・SSL/TLS暗号化＆WoL対応"},{"label":"機械耐久","value":"全金属シールド外殻＋シャーシ直結EMIスプリング接地"},{"label":"最新採用例","value":"Sony α7R VI（2026） / FX5（2026） / α1 II / Nikon Z8"}],"diagramType":"body_dual_usbc_25g_lan_bay"},{"id":"body-audio-jack-jk1028","order":94,"swatchColor":"#ef4444","groupKey":"ボディ個別詳細層_B94_マイクやイヤホンの差し込み口を_メイン","assembledPos":[51,14.5,-6.5],"explodeOffset":[92,46,-12],"integratedExplodeOffset":[92,46,-12],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B94. 純正3.5mmマイク／ヘッドホン保持枠 JK HOLDER（Ref.205）・JACK PLATE（Ref.353）＆ JK-1028フレキ（Ref.206）","subtitle":"OEM 3.5mm Mic/Headphone Isolated Jack Module — JK HOLDER (Ref.205), JACK PLATE (Ref.353) & JK-1028 Flex (Ref.206)","category":"ボディ個別詳細層 B94 — マイクやイヤホンの差し込み口を「メイン基板から切り離して守る」ノイズ防止＆破損防止ブロック","plainAnalogy":"外付けマイクやヘッドホンを毎日抜き差しする3.5mm丸型ジャックをメイン基板へ直接くっつけると、もし端子が壊れたときにカメラの頭脳ごと全交換になり、しかもデジタル回路の「ジーッ」という電気ノイズが音に混ざってしまいます。ソニーはマイク端子を独立した小さな基板（JK-1028）と頑丈な保持枠（JK HOLDER）に分離し、音質と修理しやすさの両方を守っています！","summary":"Sony ILCE-7M4公式サービスマニュアル VF BLOCK SECTION Ref.205（`JK HOLDER 502789601`）、Ref.206（`JK-1028 FLEXIBLE BOARD A5022316A`）、および MAIN BOARD SECTION Ref.353（`JACK PLATE 502789401`）からなる3.5mmオーディオ入出力アイソレーション・アセンブリ。","opticsAndPhysics":["3.5mmプラグインパワー対応マイク入力（赤枠）とリアルタイム音声モニタリング用ヘッドホン出力（緑/黒枠）を、メイン基板（SY-1122）から物理分離された専用サブフレキ `JK-1028` 上に実装しています。","金属製 `JACK PLATE`（`502789401`）と高剛性 `JK HOLDER`（`502789601`）がプラグの挿抜力と横こじり力をシャーシへ受け流すため、メイン基板へのクラック伝播を完全に防ぎます。","アナログ音声ラインを高速デジタルバスから空間隔離し、金属プレートでシールド接地することで、Wi-Fi通信中やIBIS作動時でもヘッドホンへ「ピー・ジー」という高周波ノイズが乗らないクリーンな音声収録を実現します。"],"formula":{"expression":"メイン基板から物理分離（JK-1028） ＋ 金属JACK PLATE接地 ⇒ アナログ音声フロアノイズ極小化＆単体交換可能","description":"音声の差し込み口を独立ブロック＋金属カバーで守ることで、雑音の混入と基板破損のどちらも防ぐ"},"nextGenInnovation":"デジタル24-bit/32-bitフロートMIシュー音声と並び、汎用3.5mmマイク・タイムコード入力の信頼性とメンテナンス性を支える堅実なプロ向け内部構造です。","specs":[{"label":"Sony純正品番①","value":"Ref.205: 502789601（JK HOLDER） / Ref.353: 502789401（JACK PLATE）"},{"label":"Sony純正品番②","value":"Ref.206: A5022316A（JK-1028 FLEXIBLE BOARD）"},{"label":"端子構成","value":"3.5mmステレオマイク（プラグインパワー）＋ 3.5mmヘッドホン"},{"label":"設計メリット","value":"アナログ音声EMI隔離＆ジャック破損時の低コスト単体修理"}],"diagramType":"body_audio_jack_jk1028"},{"id":"body-mimo-wifi6e-nfc-coil","order":95,"swatchColor":"#eab308","groupKey":"ボディ個別詳細層_B95_2本のアンテナで写真転送を2倍速にする","assembledPos":[-66.5,4,4],"explodeOffset":[-108,32,34],"integratedExplodeOffset":[-108,32,34],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B95. 2×2 MIMO 5/6GHz Wi-Fi第2ダイバーシティアンテナ ＆ 側面NFCワンタッチ・フェライトコイル","subtitle":"2×2 MIMO 5/6GHz Diversity Secondary Antenna & Side-Grip Ferrite-Backed NFC Coil (α1 II / α7 V)","category":"ボディ個別詳細層 B95 — 2本のアンテナで写真転送を2倍速にする「Wi-Fiツイン受信機」と、スマホをかざすだけのNFCコイル","plainAnalogy":"マグネシウムの金属ボディは電波を跳ね返してしまうため、アンテナが1本だけだと手で持った角度によってスマホやWi-Fiとの通信が途切れやすくなります。最新カメラ（α1 IIやα7 V）はトップだけでなくボディ側面の電波が抜ける窓にも「2本目のアンテナ（2×2 MIMO）」を離して配置し、2車線道路のように転送速度を2倍へ！さらにグリップ横にはスマホをピッと触れるだけの銅線コイル（NFC）も仕込まれています。","summary":"トップデッキの主アンテナ（B57 `AN-1043`）とペアを組んで5GHz/6GHz帯の2×2 MIMO空間多重通信を実現する第2ダイバーシティ・アンテナモジュールと、グリップ側面の金属渦電流を抑えるフェライトシート裏打ち13.56MHz NFCループコイル。","opticsAndPhysics":["2本のアンテナを波長に応じた空間距離・直交偏波で離して配置（ダイバーシティ配置）することで、手でカメラを構えたときの人体吸収による電波低下を互いに補い、最大2倍の実効スループットでRAW画像や動画を高速FTP転送できます。","NFC（13.56MHz近距離無線）コイルは、そのまま金属ボディに貼ると渦電流が発生して磁界が打ち消され全く反応しなくなります。そこでコイルとマグネシウム殻の間に高透磁率の「黒色焼結フェライトシート」を挟み、磁束をすべて外側（スマホ側）へ集中させています。","さらにBluetooth 5.x低消費電力アンテナとも帯域協調し、カメラの電源OFF中でもスマホからSDカード内の画像を閲覧・自動転送できる最新ワークフローを支えます。"],"formula":{"expression":"2×2 MIMO（空間2ストリーム＝転送速度最大2倍） ＋ フェライト裏打ち13.56MHz NFC磁界遮蔽","description":"離れた2本のアンテナで電波の死角を消して速度を2倍にし、特殊な磁性シートで金属ボディでもNFCを反応させる"},"nextGenInnovation":"2025年末発表のSony α7 Vで5GHz＋6GHz帯の2×2 MIMO対応へ進化し、ワイヤレスでも有線並みのストレスフリーなスタジオテザー撮影が可能になりました。","specs":[{"label":"無線規格","value":"Wi-Fi 5/6E（5GHz / 6GHz）2×2 MIMO空間多重 ＋ Bluetooth 5.x"},{"label":"NFC構造","value":"13.56MHz銅パターンコイル ＋ 高透磁率フェライト遮蔽シート"},{"label":"配置工夫","value":"金属殻の電波透過ウィンドウ裏・主アンテナと直交分離配置"},{"label":"最新採用例","value":"Sony α9 III / α1 II / α7 V（2025–2026）"}],"diagramType":"body_mimo_wifi6e_nfc_coil"},{"id":"body-bottom-wp-potting","order":96,"swatchColor":"#8b5cf6","groupKey":"ボディ個別詳細層_B96_濡れた地面や雪の上にカメラを置いても底","assembledPos":[-6,-36.5,-2],"explodeOffset":[-30,-104,14],"integratedExplodeOffset":[-30,-104,14],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B96. 純正底面防水ポッティング封止アセンブリ BOTTOM WP POTTING B-ASSY（Sony Ref.17: A5025879A）","subtitle":"OEM Factory-Dispensed Bottom Waterproof Silicone Potting Assembly (Ref.17: A5025879A)","category":"ボディ個別詳細層 B96 — 濡れた地面や雪の上にカメラを置いても底から絶対に水を通さない「工場充填の防水樹脂シール」","plainAnalogy":"風景やスポーツ撮影では、濡れた草むら・雨上がりのアスファルト・雪の上にカメラを直置きすることも珍しくありません。一番水がしみ込みやすい底面の継ぎ目と配線通り道には、ゴムパッキンだけでなく工場で液状の防水シリコーン樹脂をすき間なく流し込んで固める「ポッティング封止（防水コーキング）」が施されています。サービスマニュアルでも「取り扱い注意」の特別印が付く本気の防水層です！","summary":"Sony ILCE-7M4公式サービスマニュアル OVERALL SECTION Ref.17（純正品番 `A5025879A`：`BOTTOM WP POTTING B-ASSY`、公式Note 2「防水ポッティング部品取扱規定」指定部品）の底面防水樹脂封止アセンブリ。","opticsAndPhysics":["通常の圧縮ゴムガスケットだけでは防ぎきれない複雑な3次元角部・底面ネジ貫通部・縦位置グリップ接続ハーネス出口のミクロな隙間を、硬化型防水シリコーンポッティング材で完全充填して毛細管現象による水の吸い上げを断ち切ります。","ソニーの公式サービスノートでは、分解修理時にポッティングの剥がれ・亀裂が確認された場合は再利用せず新品交換または規定防水シーラント再充填を義務付けるほど、底面防滴の要となっています。","氷点下−10°Cの極寒から＋50°Cの炎天下まで硬化・ひび割れしない耐候性シリコーンエラストマー処方が採用されています。"],"formula":{"expression":"底面毛細管すき間 → 液状シリコーン充填硬化（ポッティング） ⇒ 濡れた路面・雪上直置きでも浸水経路＝0","description":"お風呂場の防水コーキングのように底面のわずかなすき間を専用樹脂で完全に埋め、下からの浸水をシャットアウトする"},"nextGenInnovation":"外装のパッキンだけでなく「分解しないと絶対に見えない工場ポッティング防水」まで施されていることが、プロが嵐の中でカメラを信頼できる本当の理由です。","specs":[{"label":"Sony純正品番","value":"Ref.17: A5025879A（BOTTOM WP POTTING B-ASSY）"},{"label":"サービス規定","value":"公式Note 2「防水ポッティング部品取扱対象」指定部位"},{"label":"封止材料","value":"広温度耐候・無腐食性シリコーン防水ポッティング樹脂"},{"label":"保護対象","value":"底面カバー合わせ目・縦グリ接続通線部・底面角部"}],"diagramType":"body_bottom_wp_potting"},{"id":"body-cinema-cage-threads","order":97,"swatchColor":"#cbd5e1","groupKey":"ボディ個別詳細層_B97_重い外付けケージなしで_マイクやモニタ","assembledPos":[0,36.2,2],"explodeOffset":[46,86,26],"integratedExplodeOffset":[46,86,26],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B97. ケージ不要・ボディ直結 1/4-20 UNC 多点リグマウントネジ座（5箇所ステンレスインサート：FX3 / FX5規格）","subtitle":"Direct-to-Chassis 5-Point Stainless 1/4-20 UNC Cage-Free Rig Mounting Bosses (Sony Cinema Line FX3 / FX5)","category":"ボディ個別詳細層 B97 — 重い外付けケージなしで、マイクやモニターをボディへ直接ネジ止めできる「5つの頑丈なネジ穴骨格」","plainAnalogy":"動画撮影で外付けモニターや大型マイクをカメラに付けたいとき、普通はカメラ全体に「ケージ」という重い金属の鳥かごを被せる必要がありました。最新のシネマ系ボディ（Sony FX3／FX5）は、ボディの天面3箇所と左右側面の計5箇所に、マグネシウム骨格へ直接埋め込んだ「超頑丈な1/4インチ金属ネジ穴」を標準装備！ケージ無しで軽快にプロ装備をガッチリ直付けできます。","summary":"Sony Cinema Line（FX3／FX30／2026年発表FX5）が切り拓いた、ボディ天面3箇所＋左右側面2箇所の計5箇所に高強度ステンレス製1/4-20 UNCヘリサート／インサートボスと回り止めピン穴を直接鋳込んだ「ケージレス・リグマウント構造」。","opticsAndPhysics":["マグネシウム合金へ直接ネジを切ると頻繁な着脱でネジ山が摩耗（かじり）するため、高硬度のステンレス鋼インサートナット（1/4-20 UNC）を厚肉ボス部へ圧入・インサート成形し、数十kg級の引抜き耐力を実現しています。","ネジ穴の底は貫通しない「袋穴（ブラインドホール）構造」になっており、長めのアクセサリーネジをねじ込んでも内部のフレキ基板や電子部品を突き破らず、かつ穴底からの浸水も完全に遮断します。","天面3点のネジ座はXLRオーディオハンドルユニットの2点＋補助固定や、マジックアーム・外部レコーダーの直結に対応し、システム全体の重量を200〜300gも軽量化します。"],"formula":{"expression":"5点SUS袋穴インサート（1/4-20 UNC） ⇒ 外部金属ケージ不要（−250g軽量化＆内部貫通ゼロ防水）","description":"ボディ自体に底の閉じた頑丈なステンレスネジ穴を5つ埋め込み、ケージなしでもプロ機材を安全に直付けできる"},"nextGenInnovation":"2025–2026年の動画・ハイブリッドボディ設計へ広く波及した「ボディそのものがリグの骨格になる」革命的メカニカル思想です。","specs":[{"label":"ネジ規格","value":"1/4-20 UNC ステンレス鋼インサートボス × 5箇所"},{"label":"配置","value":"ボディ天面 ×3 ＋ 左側面 ×1 ＋ 右側面 ×1（回り止め穴付）"},{"label":"安全構造","value":"内部非貫通ブラインド（袋穴）防水・基板突き抜け防止"},{"label":"代表採用例","value":"Sony Cinema Line FX3 / FX30 / FX5（2026）"}],"diagramType":"body_cinema_cage_threads"},{"id":"body-mi-shoe-fix-wp-stack","order":98,"swatchColor":"#f59e0b","groupKey":"ボディ個別詳細層_B98_重いストロボやマイクを乗せてもビクとも","assembledPos":[0,54.5,-7.5],"explodeOffset":[0,96,-22],"integratedExplodeOffset":[0,96,-22],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B98. マルチインターフェースシュー内部防水4点固定スタック（FIX PLATE Ref.311 / SHELL Ref.327 / WP RUBBER Ref.324 / MIS-2006）","subtitle":"OEM Multi-Interface Shoe Internal Structural & Waterproof Stack (Ref.311 / 324 / 325 / 327 / 328 / 331)","category":"ボディ個別詳細層 B98 — 重いストロボやマイクを乗せてもビクともせず、雨も一滴も通さない「ホットシューの裏側4重構造」","plainAnalogy":"カメラのてっぺんに付いているホットシュー（アクセサリー台座）には、ずっしり重いストロボや大型マイクが乗り、しかも雨が真っ先に降りかかります。実はその裏側には、天井の内側から挟み込んで強度を倍増させる金属の当て板（FIX PLATE）、特殊なせん断防止ネジ4本、そして21本のデジタル端子をぐるっと包む防水ゴムブーツ（WP RUBBER）が隠れていて、グラつきと水濡れを完璧に防いでいます！","summary":"Sony ILCE-7M4公式サービスマニュアル CABINET TOP SECTION-2 Ref.311（`MI SHOE FIX PLATE 500395901`）、Ref.324（`MI SHOE FPC WP RUBBER 501695501`）、Ref.325（`MIS-2006 FLEX A5001908A`）、Ref.327（`MI SHOE SHELL PLATE 500294302`）、Ref.328（特殊頭M1.7ネジ×4）の完全スタック構造。","opticsAndPhysics":["外部の金属レール（`MI SHOE SHELL PLATE`）とトップデッキ裏面の高強度当て板（`MI SHOE FIX PLATE 500395901`）でマグネシウムルーフを上下からサンドイッチ固定することで、重いスピードライトやXLRアダプター装着時のこじり破損（シュー浮き）を防ぎます。","21ピンのデジタルオーディオ／電源インターフェース端子フレキ（`MIS-2006`）の貫通穴は、専用成型の防水ゴムブーツ（`MI SHOE FPC WP RUBBER 501695501`）で密着シールされ、雨天のストロボ撮影でも天井からの漏水を防ぎます。","固定ネジには頭部の高さを極限まで低くした特殊頭ネジ（`500294701`, L=3.3mm）を採用し、さらに化粧プレート（`MI SHOE SCREW COVER 500294602`）で覆うことでアクセサリーのスムーズな差し込みと防錆を両立しています。"],"formula":{"expression":"上部SHELL ＋ 特殊ネジ4本 ＋ 裏面FIX PLATE挟み込み ＋ WP RUBBER密閉 ⇒ 高荷重耐性＆天井防水","description":"天井の上下から金属板でサンドイッチ固定して重いストロボを支え、端子の隙間は専用ゴムで完全防水する"},"nextGenInnovation":"α7R VI（2026）やFX5の32-bitフロート4chデジタル音声伝送を支える21ピンMIシューの機械的・環境的信頼性の根幹です。","specs":[{"label":"Sony純正品番①","value":"Ref.311: 500395901（FIX PLATE） / Ref.327: 500294302（SHELL）"},{"label":"Sony純正品番②","value":"Ref.324: 501695501（WP RUBBER） / Ref.325: A5001908A（MIS-2006）"},{"label":"締結方式","value":"Ref.328 特殊低頭M1.7ネジ ×4本 ＋ Ref.329 ネジ隠しカバー"},{"label":"対応負荷","value":"大型クリップオンストロボ・XLR-A4デジタル音声アダプタ"}],"diagramType":"body_mi_shoe_fix_wp_stack"},{"id":"body-top-wp-cushions-sv","order":99,"swatchColor":"#475569","groupKey":"ボディ個別詳細層_B99_ボディの小さな段差やヒンジの影に貼り巡","assembledPos":[-14,22,-18],"explodeOffset":[-18,66,-68],"integratedExplodeOffset":[-18,66,-68],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B99. トップデッキ＆背面LCD凹部 4箇所防水ウレタンクッション群（Ref.269 / Ref.322 / Ref.54 / Ref.124）","subtitle":"OEM Precision Die-Cut Waterproof Foam Dams — TOP WP F3 (Ref.269), SV WP B (Ref.322) & RE LC WP A/B (Ref.54/124)","category":"ボディ個別詳細層 B99 — ボディの小さな段差やヒンジの影に貼り巡らされた「見えない防水スポンジの堤防」","plainAnalogy":"カメラの外装パーツ同士が重なる細かい段差や、バリアングル液晶を折りたたんで収める背面のくぼみは、どうしても髪の毛ほどのすき間ができます。そこに工場で1枚ずつ精密に貼られているのが、水を通さない独立気泡の「防水スポンジの堤防（WPクッション）」！外からは全く見えませんが、雨がボディの表面を伝って中へ入り込もうとするのを何重もの堤防でせき止めます。","summary":"Sony ILCE-7M4公式サービスマニュアルに記載された4種の重要防水クッション群：トップ前部の `TOP WP CUSHION F3`（Ref.269: `501030701`）、静止画/動画ダイヤル下の `SV WP CUSHION B`（Ref.322: `502861101`）、および背面LCD収納凹部全周の `RE LC WP CUSHION A/B`（Ref.54: `502863001` / Ref.124: `502863101`）。","opticsAndPhysics":["一般的なスポンジ（連続気泡）は水を吸ってしまいますが、カメラ用の防水クッション（WP CUSHION）は気泡の一つひとつが独立して閉じた「独立気泡（クローズドセル）マイクロセルウレタン／EPDMフォーム」を採用し、圧縮率30〜50%で優れた止水バリアを形成します。","特にバリアングル液晶の収納凹部周囲（`RE LC WP CUSHION A & B`）は、モニターを開いて撮影する際に雨滴が直接当たりやすいため、背面カバーと内部骨格の継ぎ目を二重に防御しています。","同時にこれらのクッションは外装カバーの微細なビビり音（共振）を抑える制振スペーサーとしても機能し、握ったときの「塊感（ソリッドな剛性感）」を高めています。"],"formula":{"expression":"独立気泡フォーム（圧縮30〜50%） × 外装継ぎ目4箇所配置 ⇒ 毛細管浸水ブロック＆外装ビビりゼロ","description":"水を吸わない特殊なミクロ気泡スポンジをパーツの継ぎ目にぎゅっと挟み込み、水滴とガタつきの両方を防ぐ"},"nextGenInnovation":"目に見える大型Oリングだけでなく、これら数十点の微細なダイカット防水クッションの積み重ねが、最新世代ソニーαの高いフィールド信頼性を支えています。","specs":[{"label":"Sony純正品番①","value":"Ref.269: 501030701（TOP F3） / Ref.322: 502861101（SV B）"},{"label":"Sony純正品番②","value":"Ref.54: 502863001（RE LC A） / Ref.124: 502863101（RE LC B）"},{"label":"素材構造","value":"独立気泡（クローズドセル）高復元マイクロセルフォーム"},{"label":"役割","value":"外装合わせ目止水堤防・防塵密閉・外装共振防止"}],"diagramType":"body_top_wp_cushions_sv"},{"id":"body-np-sa100-dc-c2-pd","order":100,"swatchColor":"#f97316","groupKey":"ボディ個別詳細層_B100_容量1_3倍_電池の健康診断ができる","assembledPos":[-54.5,-20.5,1.5],"explodeOffset":[-88,-86,32],"integratedExplodeOffset":[-88,-86,32],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B100. 2026次世代大容量 NP-SA100（2670mAh）劣化診断BMS ＆ 100W USB-PD直結カプラー DC-C2","subtitle":"2026 High-Capacity NP-SA100 (2670mAh) Health-Telemetry BMS & 100W USB-PD DC Coupler DC-C2 (α7R VI / FX5)","category":"ボディ個別詳細層 B100 — 容量1.3倍＆電池の健康診断ができる2026最新バッテリーと、電池交換ゼロで無限収録できる100W給電アダプター","plainAnalogy":"長時間のライブ配信や映画撮影で一番怖いのが「途中でバッテリー切れ」と「古い電池が突然0%になるトラブル」です。2026年発表のソニー最新電源システムは、容量が約1.3倍（2670mAh）に増え「あとどれくらい元気か（劣化度）」をカメラ画面へリアルタイム報告する新型バッテリー（NP-SA100）と、電池の代わりに差し込んでモバイル電源から100Wで無限給電できる専用カプラー（DC-C2）に対応しています！","summary":"2026年5月〜7月にSony α7R VI／FX5とともに登場した最新SAシリーズ大容量バッテリー `NP-SA100`（2670mAh、NP-FZ100比約1.3倍・劣化度モニタリング対応）と、100W USB Power Delivery電源から連続安定給電する専用DCカプラー `DC-C2` インターフェース構造。","opticsAndPhysics":["次世代高エネルギー密度セルと改良InfoLITHIUM BMSチップの組み合わせにより、NP-FZ100（2280mAh）比で約1.3倍の2670mAh（CIPA最大710枚撮影）を実現しつつ、充放電サイクル・内部抵抗上昇から電池の劣化ステータスをカメラ本体と充電器（BC-SAD1）へ通知します。","専用DCカプラー `DC-C2` はバッテリー形状のダミーユニット内部に高効率DC-DCレギュレータとサージ保護回路を内蔵し、100W以上のUSB-PD電源から本体へ発熱を最小限に抑えながら常時給電できます。","バッテリー扉の専用ゴム通し口（B47）からケーブルを引き出せるロック構造により、カメラ本体のUSB-Cポートを塞がずに丸1日のスタジオ収録や8K 120分連続撮影を完走できます。"],"formula":{"expression":"NP-SA100（2670mAh ≈ 1.3× FZ100・劣化診断） ＋ DC-C2（100W USB-PD直結無限給電）","description":"1.3倍長持ちで寿命も分かる最新電池と、電池の形をした100W直結電源カプラーで電源切れの不安を完全解消"},"nextGenInnovation":"2026年最新のα7R VI・FX5が導入した次世代電源エコシステムであり、高消費電力な8K RAW・AI AF・高輝度EVF時代を根底から支えます。","specs":[{"label":"2026新型電池","value":"Sony NP-SA100（2670 mAh / InfoLITHIUM劣化診断付）"},{"label":"容量向上比","value":"NP-FZ100比 約1.3倍（LCD撮影 最大約710枚 CIPA）"},{"label":"連続給電機器","value":"DCカプラー DC-C2（USB-PD 100W以上対応・ロック機構）"},{"label":"発表・採用","value":"Sony α7R VI / FX5（2026年5月〜7月発表）"}],"diagramType":"body_np_sa100_dc_c2_pd"},{"id":"body-c2pa-security-kensington","order":101,"swatchColor":"#2563eb","groupKey":"ボディ個別詳細層_B101_遠隔カメラの盗難を防ぐ_頑丈な鍵穴_","assembledPos":[46,-24.5,10.5],"explodeOffset":[88,-56,46],"integratedExplodeOffset":[88,-56,46],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B101. 盗難防止セキュリティワイヤー座 ＆ C2PA撮影真正性ハードウェア署名モジュール（AI偽造対策チップ）","subtitle":"Reinforced Anti-Theft Security Lock Slot & C2PA Hardware Root-of-Trust Camera Authenticity Module (2025–2026)","category":"ボディ個別詳細層 B101 — 遠隔カメラの盗難を防ぐ「頑丈な鍵穴」と、この写真はAI偽造ではない本物だと証明する「デジタル実印チップ」","plainAnalogy":"オリンピック会場の天井に設置する無人カメラは、ワイヤー錠でしっかり固定する「盗難防止の頑丈な鍵穴（セキュリティスロット）」が欠かせません。さらに2025–2026年は大問題になっている「AIディープフェイク写真」への切り札として、シャッターを切った瞬間にカメラ内部の改ざん不可能な専用チップが「本物のカメラで撮った証拠のデジタル実印（C2PA電子署名）」を写真と動画に自動で刻印してくれます！","summary":"ボディ外装骨格へステンレス補強板ごと組み込まれた盗難防止セキュリティワイヤーアンカー（ケンジントン互換ロック座）と、Sony Camera Authenticity Solution（C2PA国際標準規格準拠・静止画＆動画対応）を実行する耐タンパー・ハードウェアセキュリティモジュール（HSM）。","opticsAndPhysics":["盗難防止スロットは外装の樹脂ではなく内部マグネシウム骨格＋焼き入れステンレス裏当て板へ直接アンカーされており、スタジアムや美術館の常設・リモートカメラをワイヤーロックで物理保護します。","C2PA（Coalition for Content Provenance and Authenticity）対応ハードウェアセキュリティモジュールは、工場出荷時に書き込まれた固有の秘密鍵（改ざん不可の耐タンパー領域）を使い、撮像直後のセンサーデータと3D深度情報へ公開鍵暗号の電子署名を焼き込みます。","Sony α1 II・α9 III・α7 IV（最新FW）・α7R VI（2026）は静止画だけでなく動画へのC2PA署名にも対応し、報道機関や読者が「AI生成ではなく実写である」ことを数秒で数学的に検証できる信頼インフラを構築しています。"],"formula":{"expression":"Sign_C2PA = ECDSA(SHA-256(画像＋3D深度情報), K_priv_HSM)  ⇒  AI偽造・改ざんを数学的に100%検知","description":"カメラ内部の秘密の鍵で撮った瞬間に「本物のデジタル実印」を押し、後から1ピクセルでも改ざんされると即座に見抜ける"},"nextGenInnovation":"生成AI時代のジャーナリズム・証拠写真・商業撮影を守るため、2025–2026年のプロ用カメラボディに不可欠となった「物理セキュリティ×暗号セキュリティ」の最終防衛線です。","specs":[{"label":"物理防犯構造","value":"焼き入れステンレス裏当て付 セキュリティロックアンカー"},{"label":"電子署名規格","value":"C2PA国際標準準拠（Sony Camera Authenticity Solution）"},{"label":"暗号保護基盤","value":"耐タンパーHardware Root-of-Trust 秘密鍵内蔵HSM"},{"label":"対応コンテンツ","value":"静止画＆動画 撮像時リアルタイム真正性証明（2025–2026）"}],"diagramType":"body_c2pa_security_kensington"},{"id":"body-dial-detent-ball-spring","order":102,"swatchColor":"#f59e0b","groupKey":"純正精密操作感_B102_ダイヤルを回したときの_カチッ_カチッ","assembledPos":[-33.5,34.2,-6.5],"explodeOffset":[-76,138,-28],"integratedExplodeOffset":[-76,138,-28],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B102. 純正ダイヤルクリック鋼球ユニット（AM DIAL BALL HOLDER / STEEL BALL / SV SPRING）","subtitle":"Sony OEM Precision Dial Detent Steel Ball (Ref.321), Ball Holder (Ref.320) & Spring (Ref.319)","category":"純正精密操作感 B102 — ダイヤルを回したときの「カチッ、カチッ！」という極上の手応えを作る小さな鉄の玉とバネ","plainAnalogy":"カメラのモードダイヤルや露出ダイヤルを回すと、高級時計のように気持ちよく「カチッ、カチッ」と止まりますよね。その正体は、真鍮の筒に入った「直径わずか1.5ミリのピカピカな鋼球」を小さなバネが波型の溝へ押し付けている仕掛け！これがあるから、ファインダーを覗いたまま目をつぶっても設定を1目盛りずつ正確に回せます。","summary":"ソニー公式ILCE-7M4サービスマニュアルに独立部品として指定される、ダイヤル回転の節度感（クリックトルク）を生み出す純正3点精密機構：`AM DIAL BALL HOLDER`（Ref.320: `500417201`）、硬化ステンレス鋼球 `BALL, STEEL`（Ref.321: `767111211`）、および専用予圧バネ `SV DIAL SPRING`（Ref.319: `503009301`）です。","opticsAndPhysics":["ダイヤル裏面に刻まれた波型カム溝（ディテント・クラウン）に対し、微小コイルバネが硬化鋼球を一定の法線荷重で押し付けることで、回転角ごとに明瞭なエネルギー極小点（クリック位置）を作ります。","プラスチックの爪ではなく高硬度ステンレス鋼球＋専用低フリクショングリスを採用することで、10万回以上回してもクリック感がヘタらず、真冬の氷点下でも軽快な操作感を保ちます。","意図しないポケット内やバッグ内でのダイヤル誤回転を防ぎつつ、指先1本で軽やかに回せる絶妙なトルク設計（約25〜45 mN·m）が施されています。"],"formula":{"expression":"τ_click = F_spring · r_cam · tan(α_groove) ≈ 35 mN·m  （鋼球＋バネによる極上クリック感）","description":"バネの押付力とカム溝角度の精密設計により、誤操作を防ぎつつ指先に心地よい節度感を永続的に発生"},"nextGenInnovation":"高級機械式カメラから受け継がれた鋼球クリック構造を、防塵防滴Oリングと組み合わせた現代ミラーレスの職人ディテール。","specs":[{"label":"ソニー純正品番","value":"Ref.319: 503009301 / Ref.320: 500417201"},{"label":"クリック鋼球","value":"Ref.321: 767111211（硬化ステンレス球）"},{"label":"目標クリック力","value":"約 25〜45 mN·m（長寿命ヘタリレス）"},{"label":"搭載部位","value":"モードダイヤル／静止画・動画切替ダイヤル直下"}],"diagramType":"body_dial_detent_ball_spring"},{"id":"body-oem-keycap-dome-set","order":103,"swatchColor":"#64748b","groupKey":"純正操作ボタン_B103_暗い夜景でも指先の感触だけで押し分けら","assembledPos":[-41,2,-32.6],"explodeOffset":[-124,6,-134],"integratedExplodeOffset":[-124,6,-134],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B103. 純正背面8大操作キーキャップ＆2色成形防水シリコーンドーム群（AF-ON / MENU / Fn等）","subtitle":"Sony OEM Rear 8-Button Keycap Cluster & Waterproof Dual-Shot Silicone Domes (Ref.65–69, 106–112)","category":"純正操作ボタン B103 — 暗い夜景でも指先の感触だけで押し分けられ、雨粒の侵入も完璧に塞ぐ背面の主役ボタン群","plainAnalogy":"カメラの背面には「AF-ON」「MENU」「Fn」「再生」「ゴミ箱」など大事なボタンが並んでいますよね。実はボタンの頭の下には「やわらかいシリコーンゴムの雨合羽（防水スカート）」がびっしり敷き詰められていて、雨の中で何度も押しても中に水が1滴も入らない構造になっているんです！","summary":"ソニーILCE-7M4サービスマニュアル（Ref.65〜69, Ref.106〜112）に記載された、背面・肩部の主要操作キー（`AF-ON`、`AEL`、`C1`、`C3`、`MENU`、`Fn`、`再生`、`削除/C4`）の個別成形キーキャップ群と、外装隙間からの浸水を完全に遮断する一体型防水シリコーンドーム・メンブレンです。","opticsAndPhysics":["各ボタンは親指だけでブラインドタッチできるよう、ボタン直径・高さ・表面の凹凸（AF-ONは大きく少し高く、削除ボタンは誤押し防止のため周囲ガード付き）を0.2 mm単位で差別化しています。","レーザー刻印または2色成形アイコンにより、汗や指脂で何年使い込んでも文字が消えにくく、さらに裏側のシリコーンラバーが筐体穴を全周シールして雨滴と砂塵をブロックします。","直下の金属タクトドーム（荷重約1.6〜2.2 N）と組み合わせることで、冬用の厚手グローブ越しでも「押した！」と確実にわかる歯切れ良いクリック感を実現します。"],"formula":{"expression":"F_act ≈ 1.8 N ／ ストローク ≈ 0.35 mm ／ 全周シリコーン防水スカート密着シール","description":"絶妙な押下荷重と凹凸形状の違いにより、ファインダーから目を離さず雨天でも確実なブラインド操作を実現"},"nextGenInnovation":"暗闇でもボタン位置が光って見えるバックライト透過2色成形（Nikon Z9 / Canon R1系）や、カスタマイズ可能なCボタン配置へさらなる進化。","specs":[{"label":"主要8キー構成","value":"AF-ON / AEL / C1 / C3 / MENU / Fn / 再生 / 削除"},{"label":"サービス番号群","value":"Sony ILCE-7M4 Ref.65–69, Ref.106–112 系統"},{"label":"防水構造","value":"一体型シリコーン・ラバードーム防滴スカート"},{"label":"耐久寿命","value":"30万回以上の連続押下クリア"}],"diagramType":"body_oem_keycap_dome_set"},{"id":"body-forged-strap-eyelets","order":104,"swatchColor":"#cbd5e1","groupKey":"純正高荷重金具_B104_3キロ超の超望遠レンズをぶら下げて走っ","assembledPos":[0,18.5,1],"explodeOffset":[0,118,86],"integratedExplodeOffset":[0,118,86],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B104. 純正左右高荷重「鍛造ステンレス・ストラップアイレット本体」EYELET G / L","subtitle":"Sony OEM Forged Heavy-Load Strap Lug Eyelets EYELET G (Ref.316) & EYELET L (Ref.317)","category":"純正高荷重金具 B104 — 3キロ超の超望遠レンズをぶら下げて走っても絶対に抜けない「マグネシウム直結の命綱アンカー」","plainAnalogy":"カメラの首掛けストラップを引っ掛ける左右の金具（アイレット）は、外から見ると小さな輪っかですが、実はカメラの中で頑丈なマグネシウム骨格にガッチリボルト留めされた「ロッククライミングの安全アンカー」なんです！重いレンズを付けて歩いても抜けない強度と、穴から水が入らない防水Oリングを兼ね備えています。","summary":"ソニー公式ILCE-7M4サービスマニュアルに記載された、右グリップ側（`EYELET G` Ref.316: `A5025945A`）および左側（`EYELET L` Ref.317: `A5025944A`）の鍛造高強度ステンレス製ストラップ取付アイレット本体、内部荷重分散アンカー座、および防水EPDMシーリングOリングの完全アセンブリです。","opticsAndPhysics":["カメラ本体＋超望遠レンズ（合計3〜4 kg）を肩に掛けて走ったり飛び跳ねたりすると、瞬間的に数G（150〜200 N超）の衝撃引張荷重がストラップ金具の根本へ集中します。","アイレット本体をプラスチック外装ではなく内側のマグネシウム合金メインシャーシへ直接貫通固定し、裏側から幅広のアンカー板で荷重を逃がすことで破損・引き抜けを完全に防ぎます。","外装カバーを貫通する軸部には必ず圧縮EPDM防滴Oリングを装着し、ストラップを伝って流れ落ちる雨水のボディ内部侵入をシャットアウトします。"],"formula":{"expression":"F_pull_max ≥ 200 N（約 20 kgf 静荷重耐性） ／ シャーシ直結＋EPDM防水軸シール","description":"外装ではなく内部マグネシウム骨格へ直接締結することで、重量級レンズ装着時の激しい携行衝撃にもびくともしない"},"nextGenInnovation":"三角環のカタカタ音を抑える防振ブッシュや、縦位置撮影でも手に当たりにくい人間工学オフセット角度配置を採用。","specs":[{"label":"ソニー純正品番","value":"Ref.316: A5025945A (G) / Ref.317: A5025944A (L)"},{"label":"素材・製法","value":"鍛造高強度ステンレス鋼（SUS）＋内部アンカー"},{"label":"引張耐久基準","value":"200 N 以上（重量級望遠レンズ携行保証）"},{"label":"防水対策","value":"貫通軸部 圧縮EPDM Oリング密着封止"}],"diagramType":"body_forged_strap_eyelets"},{"id":"body-bth-assy-fp2438","order":105,"swatchColor":"#d97706","groupKey":"純正電池室骨格_B105_電池の出し入れをスムーズに案内し_大電","assembledPos":[-54.5,-5.5,1.5],"explodeOffset":[-156,-54,48],"integratedExplodeOffset":[-156,-54,48],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B105. 純正モールド電池室インナー骨格「BTH ASSY」＆メイン連絡フレキ「FP-2438」","subtitle":"Sony OEM Molded Battery Holder Inner Frame BTH ASSY (Ref.406) & Interconnect Flex FP-2438 (Ref.359)","category":"純正電池室骨格 B105 — 電池の出し入れをスムーズに案内し、大電流をメイン基板へ届ける「電池ボックスの骨と血管」","plainAnalogy":"電池を入れる筒の中をよく覗くと、プラスチックの案内レールや電池がガタつかないように押さえる板バネが見えますよね。あれが純正パーツ「BTH ASSY」！そして電池室の奥からメイン基板へ大電流と残量データ（あと何%か）を運ぶオレンジ色の専用フラットケーブルが「FP-2438」です。","summary":"ソニー公式ILCE-7M4サービスマニュアルに明記された、NP-FZ100バッテリーを精密保持するガラス繊維強化モールド電池室インナー骨格 `BTH ASSY`（Ref.406: `X50022741`）と、電池端子・ロック検知スイッチをメイン基板へ結ぶ専用ポリイミド連絡フレキ `FP-2438`（Ref.359: `198422111`）です。","opticsAndPhysics":["電池挿入時の逆差し（前後間違い）を物理的に防ぐ非対称ガイドリブと、カメラを激しく振ってもバッテリーがガタついて瞬断しない側壁弾性テンションバネを一体成形しています。","電池フタ開閉検知マイクロスイッチの信号線と、4K/8K撮影時の瞬間ピーク電流（最大3〜4 A）およびInfoLITHIUM通信線を1本の `FP-2438` フレキシブル基板へ高密度配線しています。","難燃性（UL94 V-0）樹脂を採用し、万一の電池異常発熱時にもグリップ外装や周囲の基板へ熱と電気的ショートが波及しない安全隔壁の役割も担います。"],"formula":{"expression":"V_drop = I_peak · R_flex < 25 mV @ 3.5 A  （幅広銅箔電源ラインによる瞬断ゼロ給電）","description":"大電流でも電圧降下を極小に抑える専用フレキと高精度ガイド骨格により、高速連写時の電源瞬断を完全防止"},"nextGenInnovation":"電池残量1%刻み表示や電池劣化度診断を支える高精度通信ラインと、USB PD急速充電時の安全温度監視をコンパクトに統合。","specs":[{"label":"電池室骨格品番","value":"Sony OEM Ref.406: X50022741（BTH ASSY）"},{"label":"連絡フレキ品番","value":"Sony OEM Ref.359: 198422111（FP-2438）"},{"label":"対応バッテリー","value":"NP-FZ100 大容量リチウムイオン（7.2V）"},{"label":"安全・機能","value":"逆差し防止リブ・防振バネ・UL94 V-0難燃材"}],"diagramType":"body_bth_assy_fp2438"},{"id":"body-optical-smart-controller","order":106,"swatchColor":"#8b5cf6","groupKey":"次世代プロ操作_B106_ボタンの上を指でスッとなぞるだけでピン","assembledPos":[-43.5,22,-32.8],"explodeOffset":[-124,66,-124],"integratedExplodeOffset":[-124,66,-124],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B106. 光学式タッチ「AFスマートコントローラー」（指先なぞり高速AF移動パッド）","subtitle":"Optical Touch AF-ON Smart Controller (IR Optical Micro-Trackpad, Canon EOS R1/R3 Class)","category":"次世代プロ操作 B106 — ボタンの上を指でスッとなぞるだけでピント枠が爆速ワープする「超小型光学マウス」","plainAnalogy":"サッカーや野鳥の撮影では、被写体が右から左へ一瞬で動きますよね。ジョイスティックをカチカチ倒す代わりに、「AF-ONボタンの中央」に仕込んだ超小型の光学センサー（パソコンの光学マウスと同じ原理！）の上を親指でスッとなぞると、ピント合わせの枠が指の動きそのままに爆速ワープする魔法のボタンです！","summary":"スポーツ・報道向けフラッグシップ機（Canon EOS R1 / R3等）でプロカメラマンから絶賛される、親指押し込み式「AF-ON」ボタンの中央へ光学式モーションセンサーを一体内蔵した次世代「スマートコントローラー」ユニットです。","opticsAndPhysics":["ボタン表面に埋め込んだ透明サファイア／高硬度樹脂ウィンドウの内側から赤外線LEDを照射し、指紋の微細な凹凸が動く様子を毎秒数千フレームの小型CMOSセンサーで光学トラッキングします。","スマホのような静電容量式タッチと違い「光学読み取り方式」を採用しているため、雨で手が濡れていても、あるいはスポーツ撮影で薄手の手袋をしていても誤動作なく追従できるのがプロ機ならではの強みです。","AF作動（押し込み）と測距点移動（表面なぞり）を親指1本・持ち替えゼロで同時操作でき、決定的な一瞬のAF追従スピードを劇的に高めます。"],"formula":{"expression":"Δ(x_AF, y_AF) = G_sens · OpticalFlow(finger_surface)  （応答遅延 < 4 ms・雨天/手袋対応）","description":"ボタン表面の光学フロー解析により、親指を離さず瞬時に画面端から端までAFエリアを自在に滑走制御"},"nextGenInnovation":"視線入力AFとスマートコントローラーの併用により、大まかに目で狙って最後は親指のなぞりでミリ単位微調整する最速フォーカスワークフローを実現。","specs":[{"label":"検知方式","value":"赤外線LED＋小型光学オプティカルフローセンサー"},{"label":"一体機能","value":"AF-ON機械押し込み＋360°指先なぞりAF移動"},{"label":"耐環境性","value":"雨天・水滴付着・薄手手袋越しでも安定動作"},{"label":"代表採用例","value":"Canon EOS R1 / EOS R3 フラッグシップ系統"}],"diagramType":"body_optical_smart_controller"},{"id":"body-gnss-ceramic-antenna","order":107,"swatchColor":"#10b981","groupKey":"衛星測位_時刻同期_B107_宇宙の衛星から電波を直接受け取り_","assembledPos":[-16,35.4,-12],"explodeOffset":[-44,152,-52],"integratedExplodeOffset":[-44,152,-52],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B107. 内蔵マルチGNSS（GPS / みちびき）セラミックパッチアンテナ＆LNA低雑音増幅基板","subtitle":"Built-In Multi-Constellation GNSS (GPS/GLONASS/Galileo/QZSS) Ceramic Patch Antenna & LNA","category":"衛星測位＆時刻同期 B107 — 宇宙の衛星から電波を直接受け取り、撮影場所と「0.001秒も狂わない時刻」を全写真へ自動記録","plainAnalogy":"旅先や登山で何千枚も写真を撮ると「これどこの山だっけ？」とわからなくなりますよね。スマホに頼らずカメラ単体で空のGPSや日本の「みちびき」衛星の微弱な電波を直接キャッチする小さな白いお豆腐型パーツが、このセラミックパッチアンテナ！写真に位置情報と超正確な世界標準時を自動で刻んでくれます。","summary":"プロ向けフラッグシップ機（Nikon Z9 / Canon EOS R1等）の軍艦部トップ直下に内蔵された、高誘電率セラミック・パッチアンテナ、SAW帯域通過フィルター、および超低雑音アンプ（LNA）一体型のマルチGNSS衛星測位モジュールです。","opticsAndPhysics":["上空約20,000 kmの衛星から届く電波は -130 dBm 以下という極めて微弱なレベルのため、金属のマグネシウム外装では遮断されてしまいます。そこでトップ肩部にRF透過樹脂窓を設け、その直下へ小型化できる高誘電率セラミックパッチ（ε_r ≈ 20〜36）を天頂向きに配置します。","アメリカのGPS、欧州のGalileo、ロシアのGLONASS、そして日本の準天頂衛星「みちびき（QZSS）」の4系統（L1帯 1575.42 MHz等）を同時受信し、ビル街や渓谷でも素早く高精度な測位を行います。","通信社や報道現場では、複数台カメラのシャッター時刻を原子時計基準（UTC）へ自動同期し、写真EXIFへの撮影場所・日時改ざん防止メタデータ付与にも大活躍します。"],"formula":{"expression":"λ_ceramic = λ_0 / √ε_r ≈ 190 mm / √36 ≈ 31 mm（半波長パッチ ≈ 14 mm へ超小型化！）","description":"高誘電率セラミックの中で電波の波長を縮めることで、14ミリ角の極小サイズで宇宙からの衛星電波を高感度受信"},"nextGenInnovation":"C2PAコンテンツ認証（B101）と内蔵GNSS時刻・位置情報を暗号署名で結びつけ、報道写真の「いつ・どこで撮られた本物か」を証明する時代へ。","specs":[{"label":"対応衛星網","value":"GPS / GLONASS / Galileo / みちびき（QZSS）"},{"label":"アンテナ構造","value":"14×14 mm 高誘電率セラミックパッチ＋LNA"},{"label":"受信周波数帯","value":"L1帯 1575.42 MHz（円偏波RHCP最適化）"},{"label":"主な活用","value":"EXIF位置自動記録・報道マルチ機UTC時刻同期"}],"diagramType":"body_gnss_ceramic_antenna"},{"id":"body-timecode-sync-port","order":108,"swatchColor":"#ef4444","groupKey":"プロ映画同期_B108_何台ものカメラと録音機の映像・音声を_1","assembledPos":[51.2,6.5,6.5],"explodeOffset":[154,34,42],"integratedExplodeOffset":[154,34,42],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B108. プロ映画同期用タイムコード（TC IN/OUT）ロック式同軸端子＆TCXOシンク基板","subtitle":"Cinema Timecode (TC IN/OUT) Lockable Coaxial Terminal & High-Precision TCXO Sync Module","category":"プロ映画同期 B108 — 何台ものカメラと録音機の映像・音声を「1コマのズレもなく」ピタッと合わせる映画現場の絶対時計","plainAnalogy":"映画やライブ撮影では、5台のカメラと別撮りの高音質マイクを同時に回します。あとで編集するとき全部の映像のタイミングを手作業で合わせるのは地獄ですよね。そこで全カメラを「タイムコード（時:分:秒:コマ）」という共通のデジタル時計でピタッと繋ぐ専用端子がこれ！ロック付きで抜けにくく、編集が一瞬で終わります。","summary":"ソニーシネマライン（FX3 / FX6 / FX5世代）やハイブリッド上位機へ搭載される、SMPTE LTC（Linear Timecode）信号を入出力するロック式同軸／専用TC端子と、カメラ単体でも長時間ズレない高精度温度補償水晶（TCXO）タイムコードジェネレータ基板です。","opticsAndPhysics":["「23.976 / 24 / 29.97 / 59.94 fps」などのフレーム単位で正確な時刻ラベル（時:分:秒:フレーム）を全カットへ焼き込み、別録りの音声レコーダーや複数台のカメラ素材を編集ソフト上でワンクリック完全同期させます。","一度マスタークロックとケーブル接続して同期（ジャムシンク）した後は、ケーブルを抜いても内蔵の±0.5 ppm級TCXOが24時間経っても1フレーム未満の超高精度でカウントを刻み続けます。","端子周囲はシールド金属シェルと防水Oリングを備え、現場でケーブルが引っ張られても接触不良やノイズ混入が起きない堅牢構造です。"],"formula":{"expression":"Δt_drift < 1 frame / 24 h  （SMPTE 12M LTC 準拠 ／ TCXO安定度 ±0.5 ppm）","description":"1日回しっぱなしでも1コマ未満しか狂わない専用時計とTC端子で、マルチカメラ映画編集の同期作業をゼロ化"},"nextGenInnovation":"ケーブル接続に加えて、Bluetooth／Ultra-Wideband無線タイムコード同期にも対応し、ジンバルやドローン搭載機まで一括同期するスマート制作現場へ。","specs":[{"label":"対応規格","value":"SMPTE 12M LTC（23.98 / 24 / 25 / 29.97 / 59.94）"},{"label":"入出力切替","value":"TC IN / TC OUT 双方向（ジャムシンク対応）"},{"label":"時計精度","value":"内蔵 TCXO（24時間で 1 フレーム未満の誤差）"},{"label":"代表採用知見","value":"Sony Cinema Line（FX3 / FX6 / FX5）系統"}],"diagramType":"body_timecode_sync_port"},{"id":"body-haptic-piezo-buttons","order":109,"swatchColor":"#06b6d4","groupKey":"次世代ボタンレスUI_B109_物理的なすき間ゼロなのに_指で押","assembledPos":[-47,-14,-32.6],"explodeOffset":[-136,-54,-124],"integratedExplodeOffset":[-136,-54,-124],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B109. 機械接点ゼロ・完全防水「感圧ピエゾ・ハプティック（触覚振動）ボタン」モジュール","subtitle":"Zero-Moving-Seam Force-Sensing Piezo Haptic Feedback UI Module (Sigma BF 2025–2026 Class)","category":"次世代ボタンレスUI B109 — 物理的なすき間ゼロなのに、指で押すと「カチッ！」と本物そっくりに震えて答える未来ボタン","plainAnalogy":"最近のスマホのホームボタンやノートPCのトラックパッドって、本当は凹んでいないのに押すと「カチッ！」と気持ちいい感触が返ってきますよね。2025〜2026年登場の次世代カメラ（Sigma BFなど）は、その「感圧＋超高速ピエゾ振動」をカメラのボタンへ初採用！動くすき間がないのでホコリも水も入らず故障もしにくいんです。","summary":"2025〜2026年の革新的ミニマル・フルサイズ機（Sigma BF）で世界初採用された、機械的な可動スイッチ接点を持たないソリッドステート「感圧ひずみゲージ＋積層ピエゾ・ハプティック（触覚振動）フィードバック」操作モジュールです。","opticsAndPhysics":["指先の押下力（数十〜数百グラム）を裏面の高感度ひずみゲージ（ピエゾ抵抗フィルム）が電気抵抗変化として1ミリ秒以内に検知するため、誤タッチを防ぎつつ意図した押し込みだけを認識します。","押し込みを検知した瞬間、直下の積層圧電（ピエゾ）アクチュエータが約150〜220 Hzの鋭い1周期パルス振動を発生させ、脳に「物理ボタンがカチッと沈んだ」という鮮明な触覚錯覚（ハプティクス）を与えます。","物理的なボタン貫通穴や金属バネ接点の摩耗・酸化が原理的に存在しないため、極限の防塵防滴シール性と長寿命、さらには好みに応じた押し心地の強弱カスタマイズまで可能にします。"],"formula":{"expression":"ΔR / R = GF · ε_finger  →  a_piezo(t) = A_0 · sin(2πf_h t) · e^(−t/τ)  （応答 < 2 ms）","description":"指の圧力をひずみゲージで即検知し、2ミリ秒未満の鋭いピエゾ振動で「物理的なすき間ゼロの極上クリック感」を再現"},"nextGenInnovation":"アルミ削り出しユニボディと感圧ハプティクスの融合により、操作系トラブルの最大原因だった「スイッチ浸水・接点摩耗」を根本から解消する次世代デザイン。","specs":[{"label":"圧力検知","value":"ピエゾ抵抗ひずみゲージ（誤タッチ防止閾値制御）"},{"label":"触覚発生","value":"超高速積層ピエゾ・ハプティック振動子（< 2 ms）"},{"label":"構造メリット","value":"可動すき間ゼロ・究極の防塵防滴・接点摩耗レス"},{"label":"最新実機知見","value":"Sigma BF（2025〜2026）フルサイズ初採用技術"}],"diagramType":"body_haptic_piezo_buttons"},{"id":"body-focus-mode-lever","order":110,"swatchColor":"#3b82f6","groupKey":"即応フロント操作_B110_メニュー画面を開かずに左手の指先ひと","assembledPos":[34.5,-18.5,27.6],"explodeOffset":[96,-54,104],"integratedExplodeOffset":[96,-54,104],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B110. 前面独立メカニカル「フォーカスモード切替レバー（AF-S / AF-C / DMF / MF）」＆防水接点","subtitle":"Front-Left Independent Mechanical Focus-Mode Lever (AF-S/AF-C/DMF/MF) & Sealed Rotary Wafer","category":"即応フロント操作 B110 — メニュー画面を開かずに左手の指先ひとつで「オート／マニュアル」を一瞬切替するプロ伝統レバー","plainAnalogy":"オートフォーカスで撮っていたのに、急に目の前の枝にピントが邪魔されて手動（MF）に切り替えたい瞬間ってありますよね。メニューを探していたらシャッターチャンスを逃します！カメラの正面左下にこの物理レバーがあれば、左手の指で「カチッ」とひねるだけで0.5秒でAFとMFを切り替えられるんです。","summary":"プロ向けカメラの伝統的かつ最も実用的な前面左下部メカニカル「フォーカスモード切替レバー（S / C / DMF / M）」と、中央プッシュボタン、防水軸Oリング、および4接点金メッキ・ロータリースイッチ基板の完全モジュールです。","opticsAndPhysics":["レンズを左手で支えた自然な構えのまま、人差し指または中指だけで4ポジション（AF-S単写・AF-C動体追従・DMF微調整・MF手動）を瞬時にブラインド切替できます。","電源を切った状態でもレバーの角度を見るだけで現在のフォーカス設定が一目でわかり、中央のプッシュボタンを併用すればAFエリアモード切替も即座に行えます。","前面最下部という雨滴や泥はねを受けやすい位置にあるため、回転シャフトへ二重のEPDM防滴Oリングと高耐久金メッキ摺動接点ウェハーを組み込んでいます。"],"formula":{"expression":"4ポジション機械デテント（角間隔 25°）＋ 二重EPDM軸シール（IP防滴保護）","description":"電源オフでも設定が一目瞭然な物理切替レバーと、悪天候でも腐食しない密閉金接点スイッチの黄金コンビ"},"nextGenInnovation":"メニュー操作が増えがちなデジタルカメラにおいて、プロの現場要求から再評価され続けている「瞬時物理インターフェース」の象徴。","specs":[{"label":"切替段数","value":"4ポジション（AF-S / AF-C / DMF / MF）＋中央ボタン"},{"label":"配置位置","value":"ボディ前面・レンズマウント右下（左手即応位置）"},{"label":"防水保護","value":"回転軸 二重EPDM Oリング＋密閉ロータリー接点"},{"label":"代表採用例","value":"プロ機前面フォーカス切替伝統機構"}],"diagramType":"body_focus_mode_lever"},{"id":"body-drive-mode-lock-subdial","order":111,"swatchColor":"#f97316","groupKey":"プロ左肩即応ダイヤル_B111_1枚撮り・超高速連写・セルフタイ","assembledPos":[34.5,36.2,-5.5],"explodeOffset":[92,138,-28],"integratedExplodeOffset":[92,138,-28],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B111. 左肩「ドライブモード／連写切替ダイヤル＆中央プッシュロック」（Sony α1 II / α9 III系）","subtitle":"Left-Shoulder Dual-Deck Drive/Focus Mode Dial & Center Push-Lock Release (α1 II / α9 III)","category":"プロ左肩即応ダイヤル B111 — 1枚撮り・超高速連写・セルフタイマーを「ロック解除して一発切替」できるダブルダイヤル","plainAnalogy":"普段は1枚ずつ撮っているのに、突然タカが飛び立った瞬間「今すぐ秒間30コマ連写にしたい！」と思いますよね。プロ向けフラッグシップの左肩には、中央のロックボタンを押しながらクルッと回すだけで「単写→高速連写→タイマー」を一発切替できる専用2段ダイヤルが付いています。ロック付きでバッグの中で勝手に回りません！","summary":"Sony α1 II・α9 IIIなどフラッグシップ機の左肩を象徴する、上段ドライブモード（単写／Lo／Mid／Hi+連写／タイマー）＆下段フォーカスモード切替の2段同軸ダイヤルと、誤操作防止の中央プッシュロック解除機構です。","opticsAndPhysics":["中央のロックボタンを押している間だけロック爪（プランジャー）が引っ込み回転できるようになる構造（または押すたびにロック／フリー切替）により、移動中の意図しない設定ズレを完全に防止します。","上段ダイヤルと下段リングが同軸二重シャフトで独立回転し、それぞれの直下に防水Oリングと独立したグレーコード接点ブラシを収めた時計並みの高密度メカニズムです。","右手はシャッターボタンに置いたまま、左手だけで瞬時に連写速度を切り替えられるため、スポーツ・野鳥撮影の歩留まりを劇的に引き上げます。"],"formula":{"expression":"同軸2段独立シャフト（上段：ドライブ切替 ／ 下段：AFモード）＋ 中央プランジャーロック","description":"左右の手の役割分担を最適化するフラッグシップ伝統の左肩ロック付き2段ダイヤルで、一瞬のシャッター好機を逃さない"},"nextGenInnovation":"α9 III / α1 IIではC5ブーストボタン（連写速度ブースト）と連携し、通常連写から一瞬で120fps／30fpsへ跳ね上げるプロ仕様の操作体系を構築。","specs":[{"label":"構成","value":"左肩 2段同軸ダイヤル＋中央ロック解除ボタン"},{"label":"切替機能","value":"ドライブモード（S / Lo / Mid / Hi+）＆ フォーカス"},{"label":"防水シール","value":"内外2重同軸シャフト EPDM 防滴Oリング"},{"label":"代表採用例","value":"Sony α1 II（2024–2025） / α9 III 系統"}],"diagramType":"body_drive_mode_lock_subdial"},{"id":"body-drop-freefall-imu","order":112,"swatchColor":"#e11d48","groupKey":"落下セーフティ_B112_カメラが宙に放り出された_無重力の一瞬","assembledPos":[-16,-24.5,-10.5],"explodeOffset":[-56,-138,-58],"integratedExplodeOffset":[-56,-138,-58],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B112. 落下検知「3軸高G加速度センサー」（フリーフォール検知→IBIS＆レンズ緊急保護指令）","subtitle":"3-Axis High-G Freefall Drop-Detection Accelerometer & Emergency IBIS/Lens Park Trigger","category":"落下セーフティ B112 — カメラが宙に放り出された「無重力の一瞬」を0.03秒で見抜き、床に着く前に内部を防御態勢へ","plainAnalogy":"うっかりカメラを手から滑らせてしまったとき、落ちている最中はカメラ全体が一瞬だけ「宇宙と同じ無重力（0G）」になります。この超小型センサーはその「0Gになった瞬間」をたった0.03秒で察知！地面にぶつかる約0.4秒も前に「大変だ、落ちた！IBISに緊急ブレーキをかけろ！」とカメラ中へ緊急指令を飛ばします。","summary":"カメラ底面の高剛性マグネシウム骨格アイランドへ直接リジッド実装された、フリーフォール（自由落下）検知割り込み機能付き3軸高G（±16G）MEMS加速度センサーと、電池瞬断時でも保護動作を完遂させる緊急バックアップ・スーパーキャパシタ回路です。","opticsAndPhysics":["静止しているカメラには常に下向き1.0 Gの重力が掛かっていますが、落下した瞬間にX・Y・Zの合成加速度 √(ax²+ay²+az²) が 0.2 G 以下（無重力状態）へ急落します。","この無重力状態が約30ミリ秒続くとハードウェア割り込み（INT1）が即座に発火し、メインCPUを待たずIBIS電磁ブレーキ（S88）・保護シールド幕（S75）・レンズフォーカス群ロックへ緊急退避信号を並列送信します。","さらに着地衝撃（最大100 G級）のログを不揮発メモリへ記録し、サービスセンターでの精密点検時に衝撃履歴からダメージ箇所を的確に診断するブラックボックス機能も兼ねます。"],"formula":{"expression":"‖a‖ = √(a_x² + a_y² + a_z²) < 0.25 g （30 ms 継続で落下確定 → 緊急防御割込み発火！）","description":"自由落下特有の無重力状態を30ミリ秒で即判定し、床衝突前にIBISブレーキと防塵幕保護を自動発動"},"nextGenInnovation":"IBIS直載の制振加速度計（S85）とボディ側落下検知IMU（B112）がタッグを組み、高価なフラッグシップ機をアクシデントから救うインテリジェント自己防衛システム。","specs":[{"label":"検知素子","value":"3軸高G（±16G）MEMS加速度センサー（ハード割込）"},{"label":"落下判定時間","value":"約 25〜35 ms（無重力閾値 < 0.25 G）"},{"label":"連動防御対象","value":"IBIS緊急電磁ブレーキ（S88）・レンズ鏡筒退避"},{"label":"バックアップ","value":"着地瞬断対策 緊急電源ホールドコンデンサ"}],"diagramType":"body_drop_freefall_imu"},{"id":"body-vgrip-locking-pin-bay","order":113,"swatchColor":"#94a3b8","groupKey":"縦グリ剛結インターフェース_B113_縦位置グリップや動画リグを","assembledPos":[-24,-35.6,0.5],"explodeOffset":[-82,-142,42],"integratedExplodeOffset":[-82,-142,42],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B113. 縦位置グリップ（VG-C5 / VG-C6）連結用ガイドボス・回り止めピン穴＆強化ナット座","subtitle":"Vertical-Grip (VG-C5/VG-C6) Anti-Twist Locating Pin Socket & Load-Spreader Base Seat","category":"縦グリ剛結インターフェース B113 — 縦位置グリップや動画リグを付けたとき「1ミリもねじれず一体化する」底面の秘密穴","plainAnalogy":"カメラを縦に構えてポートレートやスポーツを撮るときに大活躍する「縦位置グリップ（バッテリー2個入る下部ハンドル）」。三脚ネジ1本だけで留めるとクルッと回って緩んでしまいますよね。そこで底面の三脚穴の隣に「硬い位置決めピン穴」と「補強プレート」を用意し、2点でガッチリ噛み合わせて1つの塊のように一体化させます！","summary":"純正縦位置グリップ（Sony VG-C4EM / VG-C5 / VG-C6等）およびプロ用ビデオ三脚ヘッド・シネマケージを一切のガタつき・回転ズレなく強固に連結するための、カメラ底面・硬化ステンレス回り止めピン穴（ガイドソケット）と内部チタン／鋼製荷重分散ベース座です。","opticsAndPhysics":["三脚ネジ（1/4-20 UNC）単体では軸回りの回転モーメント（ねじれ）を受け止めきれず、重い望遠レンズで縦位置撮影を続けると徐々にネジが緩む弱点がありました。","三脚穴から約15〜22 mm離れた基準位置へ精密リーマ加工のガイドピン穴（±0.03 mm公差）を設け、グリップ側のスプリング位置決めピンと噛み合わせることで回転自由度を物理的にゼロ拘束します。","さらに三脚座とガイド穴を底面内部の1枚の厚肉補強プレートで繋ぐことで、望遠レンズ支持時の底板たわみやマグネシウム亀裂を徹底的に防ぎます。"],"formula":{"expression":"τ_resist = F_pin · d_lever  （三脚ネジ＋精密回り止めピン2点拘束で回転ズレ完全ゼロ）","description":"ネジ1点留めの弱点である回転緩みを専用ガイドピン穴と内部補強座で封じ、ボディと縦グリを一体モノコック化"},"nextGenInnovation":"最新世代では電池室貫通の接点だけでなく、底面直接通信端子や高強度シネマリグ用3/8インチ兼用ロック機構と連携し、拡張性をさらに向上。","specs":[{"label":"対応機器","value":"純正縦位置グリップ（VG-C4EM / C5 / C6）・ビデオ雲台"},{"label":"ピン穴公差","value":"精密硬化ステンレスブッシュ（±0.03 mm）"},{"label":"補強構造","value":"三脚ナット座一体型・高剛性荷重分散プレート"},{"label":"主な効果","value":"縦位置撮影時のガタ・ねじれ緩み完全解消"}],"diagramType":"body_vgrip_locking_pin_bay"},{"id":"body-cnt-dial-switch-blocks","order":114,"swatchColor":"#14b8a6","groupKey":"純正モジュール基板_B114_前ダイヤルと背面スイッチ群を_交換","assembledPos":[-49,22,-8.5],"explodeOffset":[-164,72,-46],"integratedExplodeOffset":[-164,72,-46],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B114. 純正制御スイッチブロック「CNT DIAL F ASSY」＆「SWITCH BLOCK RL88100 / BK88100」","subtitle":"Sony OEM Front Control Dial Module CNT DIAL F ASSY (Ref.255) & Switch Blocks RL88100 / BK88100","category":"純正モジュール基板 B114 — 前ダイヤルと背面スイッチ群を「交換しやすい独立ユニット」にまとめた整備の要","plainAnalogy":"カメラの中のボタンやダイヤルが全部1枚の巨大基板にハンダ付けされていたら、ボタン1個が壊れただけで修理代が何万円もかかってしまいますよね。ソニーの純正設計では、前ダイヤル部（CNT DIAL F）や背面スイッチ群（RL88100 / BK88100）を小さな専用ブロックに分け、精密コネクタでパチッと繋ぐことで修理しやすく長持ちさせています！","summary":"ソニー公式ILCE-7M4サービスマニュアルに純正アセンブリ品番として登録された、前コマンドダイヤル制御モジュール `CNT DIAL F ASSY`（Ref.255: `X50025381`）と、背面・右肩の操作スイッチを集約した `SWITCH BLOCK, CONTROL RL88100`（Ref.258）および `BK88100`（Ref.64）のモジュラー制御ブロック群です。","opticsAndPhysics":["押し込み頻度が最も高い前ダイヤルや背面カスタムボタン群を、メインのBIONZ XR高多層基板から物理的に分離した専用サブスイッチブロックへ独立実装しています。","各スイッチブロックにはチャタリング（電気的なバタつき）を抑える保護ESDダイオードとプルアップ抵抗網が近接配置され、FPCゼロ挿抜（ZIF）コネクタ1本でメイン基板へ確実に接続されます。","このモジュラー設計により、プロの過酷な現場で数年後にスイッチ摩耗や浸水トラブルが起きても、該当スイッチブロックだけの短時間・低コスト交換で新品の操作感へ蘇らせられます。"],"formula":{"expression":"モジュラー分離設計：CNT DIAL F + RL88100 + BK88100  （ZIFコネクタ接続・ESD ±15 kV保護）","description":"消耗しやすい操作系を独立ユニット化することで、高い整備性・耐静電気性・長寿命プロサポートを両立"},"nextGenInnovation":"各操作ブロックごとに防滴シールと独立アース経路を備え、高湿度・極寒環境下でも誤動作ゼロの確実なスイッチ応答を保証。","specs":[{"label":"ソニー純正品番","value":"Ref.255: X50025381（CNT DIAL F ASSY）"},{"label":"スイッチブロック","value":"Ref.258: RL88100 ／ Ref.64: BK88100"},{"label":"接続インターフェース","value":"防振ロック付き 0.3 mm ピッチ ZIF コネクタ"},{"label":"設計メリット","value":"迅速な部分修理性・耐静電気ESD保護強化"}],"diagramType":"body_cnt_dial_switch_blocks"},{"id":"body-peo-anti-corrosion-coat","order":115,"swatchColor":"#22d3ee","groupKey":"極限外装コーティング_B115_汗や海風で錆びやすいマグネシウム","assembledPos":[0,35.6,12],"explodeOffset":[16,134,68],"integratedExplodeOffset":[16,134,68],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B115. マグネシウム外装「プラズマ電解酸化（PEO）耐食下地＋撥油フッ素トップコート」多層皮膜","subtitle":"Magnesium AZ91D Plasma Electrolytic Oxidation (PEO) Ceramic Barrier & Fluorine Topcoat","category":"極限外装コーティング B115 — 汗や海風で錆びやすいマグネシウムを「セラミックの鎧と撥油コート」で10年守る表面技術","plainAnalogy":"マグネシウム合金は軽くて頑丈な最高の金属ですが、実はそのままでは海辺の塩風や人の汗でとても錆びやすいんです。そこで電気火花（プラズマ）で金属の表面自体を硬いセラミックの鎧（PEO皮膜）に変え、その上から手触りのいい艶消し塗装と皮脂を弾くフッ素コートを重ねる「4重バリア」でボディを美しく守り抜きます！","summary":"カメラ外装のチクソモールド・マグネシウム合金（AZ91D）表面に施される、高耐食セラミック化下地「プラズマ電解酸化（PEO / マイクロアーク酸化）」、微細シボ艶消しウレタン塗装、および指紋・皮脂・雨滴を弾く撥油フッ素トップコートの多層表面保護皮膜スタックです。","opticsAndPhysics":["電解液中でマグネシウム外装に高電圧パルスをかけると表面に微小なプラズマ放電が生じ、母材と一体化した厚さ約10〜20 µmの硬質酸化マグネシウム（MgO）セラミック耐食バリア層が成長します。","従来のクロメート処理と違い六価クロムを使わない環境対応プロセスでありながら、塩水噴霧試験で数倍以上の耐腐食性と、塗装が絶対にペリッと剥がれない強固なアンカー密着力を発揮します。","最外層にはカメラマンが気持ちよく握れる微細レザートーン艶消し塗膜と撥油フッ素仕上げを施し、汗・日焼け止めクリーム・雪解け水による変色やベタつきを防ぎます。"],"formula":{"expression":"4層防食スタック：AZ91D母材 → PEOセラミック(15 μm) → 艶消しシボ塗装 → フッ素撥油膜","description":"母材と融合した硬質セラミック下地と撥油トップコートの4重装甲で、潮風・汗・擦り傷からボディを長期保護"},"nextGenInnovation":"環境負荷ゼロのクロムフリーPEO技術と耐摩耗ナノセラミック粒子入りトップコートにより、長年のプロ現場でも精悍な艶消しブラックを維持。","specs":[{"label":"耐食下地処理","value":"クロムフリー・プラズマ電解酸化（PEO 15 μm）"},{"label":"中塗・質感層","value":"高耐傷マットブラック・微細シボウレタン塗装"},{"label":"最外層保護","value":"撥水・撥油フッ素トップコート（指脂防止）"},{"label":"保護性能","value":"塩水噴霧・汗・耐摩耗・環境RoHS完全適合"}],"diagramType":"body_peo_anti_corrosion_coat"},{"id":"body-starlight-red-tally-filter","order":116,"swatchColor":"#dc2626","groupKey":"星空_動画サイン_B116_真っ暗な星空の下では目を眩ませない_","assembledPos":[-22,35.4,21.5],"explodeOffset":[-68,122,92],"integratedExplodeOffset":[-68,122,92],"edgeOpacity":0.22,"standaloneOnly":true,"title":"B116. 星空撮影用ナイトビジョン赤色減光フィルタ窓＆全方向360°ステータス・タリー導光プリズム","subtitle":"Starlight Night-Vision 660 nm Red Dimmer Filter & 360° Dual-Color Tally Light-Guide Prism","category":"星空＆動画サイン B116 — 真っ暗な星空の下では目を眩ませない「深紅の光」、動画収録中は前からでも分かる「赤ランプ」","plainAnalogy":"真っ暗な山頂で星空を撮るとき、カメラの明るい緑や白のランプがピカッと光るとせっかく暗闇に慣れた目（暗順応）が一瞬で台無しになってしまいますよね。一方、動画撮影中はカメラの正面にいる出演者にも「いま録画中だよ！」とハッキリ伝えたい！この導光プリズムと深紅フィルタ窓が、その正反対の2つの願いをスマートに叶えます。","summary":"カメラ肩部〜前面にかけて光学アクリル（PMMA）導光プリズムを立体ルーティングし、動画収録時に360°全方向から視認できる赤／緑デュアル・タリーランプ機能と、星空・天体撮影時に人間の暗順応を壊さない660 nm深紅（ナイトビジョン）減光フィルタ切替を両立した光学ステータス表示ユニットです。","opticsAndPhysics":["人間の網膜で暗闇を見る桿体（かんたい）細胞は青〜緑の光（500 nm付近）に極めて敏感ですが、波長660 nmの深赤色にはほぼ反応しないため、赤色減光モードを使うと暗闇に慣れた視力を維持したまま操作できます。","通常動画モードでは、内部の極小RGBチップLEDの光を全反射（TIR）導光プリズムでカメラ前面・上面・背面の3方向へ同時分岐させ、自撮りやインタビュー中でも出演者が一目でREC中（赤）と待機中（緑）を判別できます。","不要な周囲への光漏れ（センサーや他人のカメラへの赤カブリ）を防ぐ遮光ハウジングと防水レンズ窓を一体成形しています。"],"formula":{"expression":"λ_night ≈ 660 nm（暗順応保護・桿体感度 < 0.1%） ／ 動画REC時 360°全反射プリズム導光","description":"天体撮影時の目への優しさと、動画収録時の圧倒的な視認性を1つの立体導光プリズム窓へ凝縮"},"nextGenInnovation":"Nikon Z8 / Z9の「赤色画面表示（ウォームディスプレイ）」やSony FX3の前後マルチタリーの利点を融合した、写真・動画ハイブリッド時代の気配り設計。","specs":[{"label":"光学構造","value":"全反射（TIR）立体PMMA導光プリズム＋遮光枠"},{"label":"星空モード波長","value":"約 660 nm 深赤色（人間の暗順応を破壊しない）"},{"label":"動画タリー機能","value":"前面・上面・背面 3方向同時REC/待機通知"},{"label":"防水仕様","value":"透明窓周囲 インサート密着防滴シール"}],"diagramType":"body_starlight_red_tally_filter"}]'),n={unitId:e,version:a,nameJa:l,nameEn:o,declaredPartCount:116,parts:t};export{s as declaredPartCount,n as default,o as nameEn,l as nameJa,t as parts,e as unitId,a as version};
